INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693408660', 'Par Bieleta Original Cofap Cruze 1.4 16v Turbo 2017 2018 2019 2020 2021 2022 2023', 'Seja Bem-vindo(a)!! É um prazer imenso tê-lo em nosso anuncio. Abaixo algumas informações sobre o Produto e Aplicação. Por fim, conheça um pouco mais sobre a nossa loja. Produtos: 2 Bieletas Dianteiras Lado Esquerdo ou Direito Marcas: Cofap Aplicação: Cruze 1.4 16v Turbo 2017 2018 2019 2020 2021 2022 2023 Garantia: 90 dias. É novo, e acompanha nota fiscal Sim! Todos nossos produtos são novos acompanhados de nota fiscal. Sobre a Loja: Somos uma empresa que trabalha exclusivamente com o setor de peças para veículos leves e médios, sendo eles nacionais ou importados. Oferecemos peças com qualidade, prazo de entrega, parcerias com as melhores marcas e eficiência no atendimento. Temos uma equipe de profissionais qualificados para orientar o cliente nas suas mais variadas necessidades relacionadas à manutenção do seu veículo. Oferecemos também um amplo estoque de peças e envios diários. Visamos constantemente o aperfeiçoamento e melhoria dos serviços para a satisfação total do cliente. - ATENÇÃO Para garantia de AMORTECEDORES, só serão aceitas mediante apresentação do certificado enviado junto ao produto. Sem esse documento, não será possível efetuar a garantia do produto. Em caso do não recebimento do certificado, favor nos enviar assim que receber a mercadoria e notar a ausência.', 227.44, 227.44, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rdwp-m0xhxutjtzy21a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373135807%2F22693408660', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9610881893', 'Bolsa Mochila Saída Maternidade Lequeen Multifuncional Grande Encaixe Trocador Lequeen', 'Características - Marca: Lequeen - Material: 100% Poliéster de alta resistência - Medidas (AxLxP): 40x32x16 - Peso: 0,850 kg - Capacidade: 20,5 L - Confeccionada em tecido 100% poliéster Oxford de alta resistência - Acompanha ganchos, encaixe USB e trocador - Possui bolso com amplo espaço interno para diversos itens - Possui um compartimento interno com zíper (ideal para roupas molhadas) - Possui bolso frontal com duas divisórias térmicas para mamadeiras e elástico para até 3 talheres - Possui duas divisórias frontais com fechamento em tiras duplas adesivas - Possui fechamento frontal com botão imantado e compartimento para pequenos objetos com fechamento em zíper - Possui bolsos laterais sendo um térmico - Possui bolso lateral com fácil acesso para lenços umedecidos - Possui bolso oculto na parte traseira com zíper - Possui passador para mala - Possui compartimento para notebook de até 15 polegadas - Alças de costas reguláveis e acolchoadas tornando a mochila confortável (Padded Shoulder Straps) - Alça de mão reforçada - Alças separadas com encaixes, permitindo acoplar no carrinho do bebê - Amplo espaço interno - Logo, etiquetas e puxadores personalizados - Tratamento interno antibacteriano - Tecido com proteção impermeável ______________________________________ Esta bolsa mochila possui inúmeros bolsos internos e externos (Multi-pocket) - 8 x bolsos de armazenamento (interior) - 2 x porta mamadeiras interno bolso (frente) - 1 x bolso porta lenço umedecido (lateral) - 1 x bolso térmico (lateral) ______________________________________ Itens inclusos: 1x mochila 1x trocador ______________________________________ Indicações de uso - Mochila para fazer compras - Mochila para viajar - Mochila para passear - Pode ser usada como Mochila ou Bolsa ______________________________________ Cuidados de conservação - Evite carregar excesso de peso - Embalar objetos com cantos vivos cortantes - Para limpeza, utilize apenas pano úmido ou esponja macia e sabão neutro. Não expor a luz do sol para secar - Não utilizar nenhum produto químico para limpeza - Conservar em local seco e arejado', 299.9, 229.9, NULL, 'Mom & Baby > Baby Travel Essentials > Diaper Bags', 'https://cf.shopee.com.br/file/b006118780cca4df6e59224c07827fe9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F345061139%2F9610881893', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
