INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209707419', 'Removedor de Esmalte Seduction Zulu', 'O Removedor de Esmalte Seduction da Zulu remove o esmalte de forma rápida e eficaz, sem deixar as unhas esbranquiçadas, além de possuir um aroma agradável. Modo de uso: Umedecer um algodão com o removedor de esmalte Zulu seduction e aplicar nas unhas até remover totalmente o esmalte. Se necessário repetir a aplicação.', 9.79, 9.79, NULL, 'Health > Personal Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258e-mqnelz1cwu0wd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555087%2F58209707419', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193005990', 'Jogo 2 Pneus Continental Aro 18 ContiCrossContact LX2 225/55R18 98V', 'Marca: CONTINENTAL Modelo: CONTICROSSCONTACT LX2 Medida: 225/55R18 Largura: 225 Perfil: 55 Tamanho de Aro: 18 Índice de peso: 98 - 750 kg Índice de velocidade: V - 240 km/h Tipo de Veiculo: SUV Tipo de terreno: HT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: SIMÉTRICO UTGQ: N/A Adesão à àgua: C Eficiência energética: C Ruído externo: 72 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Continental ContiCrossContact LX2 proporciona ótimo desempenho em aderência, estabilidade e resistência. Uma nervura contínua é responsável por melhorar a aderência nas curvas e em mudanças de direção. A estrutura interna com cintas de aço gêmeas, exercem força sobre a banda de rodagem, permitindo maior contato da borracha com o solo. Isso garante mais conforto e desgaste homogêneo do pneu. Desenvolvido para SUVs e veículos off-road. Sobre a marca Continental A marca Continental foi fundada em Hanover, na Alemanha em 1871. Os pneus Continental são referência mundial em desempenho e qualidade, equipando os mais modernos e sofisticados carros. São usados como pneu original de fábrica em marcas como BMW, Mercedes e Porsche, tanto com pneus comuns quanto em pneus RunFlat. Seja em pneus para carros de passeio, carros esportivos, utilitários, a Continental oferece inovações e a garantia de segurança total nos trajetos realizados.', 2074.75, 1881.61, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdy5-lxlqkbfyy6ll53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23193005990', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093013267', 'Pneu Pirelli Aro 17 Powergy 225/45R17 91W', 'Marca: PIRELLI Modelo: POWERGY Medida: 225/45R17 Largura: 225 Perfil: 45 Tamanho de Aro: 17 Índice de peso: 91 - 615 kg Índice de velocidade: W - 270 km/h Tipo de Veiculo: CARRO Tipo de terreno: HT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: Assimétrico UTGQ: N/A Adesão à àgua: B Eficiência energética: C Ruído externo: 70 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores.O Pirelli Powergy é o pneu ideal para motoristas que estão em busca de uma solução eficiente, segura e confortável para encarar os desafios do dia a dia. Sua construção foi desenvolvida para reduzir a distância em frenagens, principalmente no piso molhado. Essa qualidade, atrelada ao desenho das lamelas com barbatanas na banda de rodagem, diminui as chances de aquaplanagem e derrapagens na chuva. O Powergy foi construído com tecnologia de ponta e materiais de alta qualidade para proporcionar melhor aderência e precisão nas manobras. Além disso, a baixa resistência ao rolamento melhora a eficiência energética, o conforto e aumenta a economia de combustível. Sobre a marca Pirelli A Pirelli nasceu na Itália há mais de 100 anos, em Milão. Com longa tradição na construção de pneus, a marca produz soluções para carros, motos, tratores, caminhões e ônibus e possui fábricas espalhadas pelo mundo. A Pirelli é a atual fornecedora de pneus da Fórmula 1, a principal categoria do automobilismo mundial, e possui longa tradição em pneus de alto desempenho.', 613.52, 613.52, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-820nt-mncvb4rf1ts472', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F22093013267', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260052548', 'Dupla Body Splash Delight e Vanilla Rum Barbour’s Beauty 200ml Perfume Feminino', 'DUPLA BODY SPLASH DELIGHT E VANILLA RUM 200ML A Dupla Delight e Vanilla Rum da Barbour’s Beauty combina duas fragrâncias femininas envolventes para quem gosta de perfumes doces, elegantes e sofisticados. O Delight traz uma fragrância floral fresca e refinada, com lichia, ruibarbo, bergamota, rosa turca, peônia, cashmeran, cedro e vetiver. O Vanilla Rum traz baunilha intensa, rum licoroso e especiarias quentes, criando uma fragrância oriental gourmand marcante, sensual e cheia de personalidade. Ideal para quem deseja alternar entre uma fragrância floral sofisticada e uma fragrância doce quente e envolvente. O KIT CONTÉM: -1 Body Splash Delight Barbour’s Beauty 200ml -1 Body Splash Vanilla Rum Barbour’s Beauty 200ml COMPOSIÇÃO Álcool Etílico, Água, Perfume Delight, Perfume Vanilla Rum, Fenoxietanol, Farnesol, Laurato de Glicerila, Álcool Benzílico, Salicilato de Benzila, Cumarina, Geraniol, Hidroxicitronelal, Isoeugenol, Limoneno, Linalol, Cinamaldeído, Álcool Cinamílico', 140.9, 98.63, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/br-11134207-820ll-mq3gnx289og0f2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1579330222%2F58260052548', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
