INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499831843', 'Calha de Chuva TG Poli Sandero 07/14 4 Portas', 'A Calha de Chuva Renault Sandero 07/14 4 Portas é o produto ideal para dias de chuva. O defletor da TG Poli permite que o motorista deixe o vidro com uma fresta aberta, evitando que fique embaçado. A Calha de Chuva Renault Sandero 07/14 4 Portasé fabricada em acrílico na cor fumê e tem fácil instalação e ótima durabilidade. Ficha Técnica: Material: Acrílico. Cor: Fumê. Dimensões do produto na embalagem (AxLxC):4,2 x 20,5 x 100 (cm) Peso: 1,220 Tipo de Instalação: Colagem fita dupla-face. Garantia: 5 anos.', 273.78, 205.34, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Deflectors', 'https://cf.shopee.com.br/file/sg-11134201-22110-6jw47ixnlnjv32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1452490205%2F20499831843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
