INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14295822597', 'NIVEA Hidratante Facial Acne Control 50g', 'O que é? Nova linha de Acne Control da NIVEA apresenta este hidratante facial que reduz a acne e melhora visível da aparência da pele em apenas 7 dias. Ajuda a reduzir a irritação causada pela acne. Para que serve o NIVEA Hidratante Facial Acne Control? Reduz a acne e ajuda a reequilibrar a pele de 5 maneiras: 1. Ajuda a combater 99% da bactéria causadora da acne**; 2. Controla a oleosidade e proporciona efeito matte; 3. Com ácido salicílico que ajuda a remover células mortas; 4. Ajuda a reduzir a vermelhidão da acne 5. Sensação de pele hidratada. Benefícios e diferenciais -Ajuda a combater 99% da bactéria causadora da acne** -Ajuda a reduzir a irritação causada pela acne -Sal marinho 99% puro -Ácido Salicílico: ajuda a remover células mortas -Extrato de Alcaçuz Dourado e Magnólia -Carnitina: ajuda a controlar a oleosidade -Ácido Hialurônico: ajuda na hidratação da pele Como usar o NIVEA Hidratante Facial Acne Control? USO DIÁRIO Aplique diariamente no rosto limpo. Utilize duas vezes ao dia. CUIDADO: Evite contato com os olhos.', 61.9, 61.9, NULL, 'Beauty > Skincare > Acne Treatment', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meeey2jbvbpeaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F502619181%2F14295822597', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23695027301', 'KIT NIVEA Hidratante Labial Disney Princesas Edição Limitada 3 Unidades 4,8g cada', 'Kit NIVEA Hidratante Labial Disney Princesas Edição Limitada com 3 unidades. Este kit especial reúne as versões inspiradas nas Princesas Disney para manter os lábios hidratados, macios e protegidos contra o ressecamento, além de contar com embalagens colecionáveis. O kit contém: • 1 NIVEA Hidratante Labial Cupcake de Baunilha Bela Disney® Princesa 4,8g • 1 NIVEA Hidratante Labial Sorbet de Melancia Moana Disney® Princesa 4,8g • 1 NIVEA Hidratante Labial Morango Silvestre Rapunzel Disney® Princesa 4,8g Benefícios: • Hidratação prolongada dos lábios • Ajuda a prevenir o ressecamento • Fórmula confortável para uso diário • Aromas deliciosos e suaves • Embalagens temáticas Disney Princesas • Edição limitada Conteúdo total: 3 hidratantes labiais de 4,8g cada. Produto original NIVEA.', 83.9, 49.9, NULL, 'Beauty > Skincare > Lip Treatment', 'https://cf.shopee.com.br/file/br-11134201-820l6-mqye8r5hiuiudd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F502619181%2F23695027301', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
