INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26888009964', 'Kit 3 Cuecas Boxer Polo Star Cotton Algodão Masculina Original', 'Kit Cuecas Boxer Polo Star Cotton Masculina Original Ideal para quem busca conforto diário com um toque de sofisticação, o Kit de Cuecas Boxer Polo Star é a escolha perfeita para homens que não abrem mão de qualidade, estilo e bem-estar. Confeccionadas em Cotton, possui Algodão Premium com Elastano, essas cuecas proporcionam toque macio, fresco e gelado na pele, além de caimento perfeito. O modelo boxer curto combina visual moderno com máxima liberdade de movimento. Sobre o Produto: - Modelagem: Boxer Curta; - Cintura: Elástico suave e personalizado com o logo repetitivo; - Forro: Sem forro interno; - Costura: Reforçada para maior durabilidade; - Tecido: Toque macio e gelado, de alta qualidade. Composição: Cor Preta e Branca: 96% Algodão, 4% Elastano Cor Cinza: 84,5% Algodão, 11,5% Poliéster, 4% Elastano Tamanhos disponíveis: P: Veste do 38 ao 40 M: Veste do 42 ao 44 G: Veste do 46 ao 48 GG: Veste do 50 ao 52 Cores disponíveis: Preto - Branco - Cinza Envio: O kit é enviado de forma aleatória, podendo haver repetição de cores. Principais Características: Algodão premium para maior conforto e respirabilidade; Modelagem boxer curta: moderna e discreta; Tecido cotton com toque gelado e ajuste perfeito; Cós elástico reforçado com logo da marca; Costuras reforçadas para maior durabilidade; Sem forro interno, garantindo leveza e conforto. Gênero: Masculino Este kit é a união perfeita entre elegância, conforto e resistência, pensado para homens exigentes que valorizam cada detalhe do vestir.', 110.9, 57.9, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbfm7kr89eqq8d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2