INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51905997841', 'Livro Lindas Orações para Meninas Capa Almofadada', 'Descrição O livro Lindas Orações para Meninas, publicado pela Editora Ciranda Cultural, é uma obra delicada e inspiradora que apresenta orações especialmente pensadas para o público infantil feminino. Com linguagem simples e acessível, o livro ajuda as meninas a desenvolverem momentos de fé e espiritualidade desde cedo, incentivando a prática da oração e a confiança em Deus. O acabamento em capa almofadada ilustrada confere charme e durabilidade, tornando-o ideal para uso diário, leitura em família ou como presente especial. Ficha técnica Título: Lindas Orações para Meninas – Capa Almofadada Editora: Ciranda Cultural ISBN: 9788538088455 Ano de publicação: 2018 Idioma: Português Formato: Capa almofadada ilustrada Número de páginas: 16 Dimensões: 27 cm x 21 cm Peso: 350 g Categoria: Literatura Infantil Cristã, Oração, Espiritualidade Indicação etária: Crianças a partir de 4 anos Palavras-chave lindas orações para meninas, livro infantil cristão, ciranda cultural, capa almofadada, oração para crianças, espiritualidade infantil', 17.13, 17.13, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mki2rxezy0w100', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F51905997841', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
