INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52910959911', 'Bíblia Sagrada ACF João 3:16 Capa Dura Borda Pintada', '📖 Descrição A Bíblia Sagrada ACF – João 3:16 – Capa Dura com Borda Pintada (ISBN 9788577427321), publicada pela Kippah Store, é uma edição especial da tradução Almeida Corrigida Fiel (ACF), reconhecida por sua fidelidade ao texto bíblico original. O design temático “João 3:16” destaca um dos versículos mais conhecidos e centrais da fé cristã, tornando esta Bíblia uma peça significativa tanto para uso pessoal quanto para presentear. Com acabamento em capa dura resistente e bordas pintadas, esta edição alia durabilidade e beleza, sendo ideal para leitura diária, estudos bíblicos e momentos devocionais. 📑 Ficha técnica Título: Bíblia Sagrada ACF – João 3:16 – Capa Dura – Borda Pintada Editora: Kippah Store ISBN: 9788577427321 Ano de publicação: 2026 Idioma: Português Tradução: Almeida Corrigida Fiel (ACF) Formato: Capa dura com borda pintada Número de páginas: 992 Dimensões: 14 cm x 21 cm Peso: 450 g Categoria: Religião e Espiritualidade, Bíblia Sagrada Recursos: Texto completo da Bíblia, acabamento resistente, bordas pintadas, design temático “João 3:16” 🔑 Palavras-chave bíblia acf, joão 3:16, almeida corrigida fiel, capa dura, borda pintada, kippah store, estudo bíblico, presente cristão', 28.66, 28.66, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-820lb-mojrtegx6v4397', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F52910959911', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
