INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50107337712', 'Boné New Era Snapback A-frame NY New York Yankees Original', '***ENVIO IMEDIATO APÓS A CONFIRMAÇÃO DO PAGAMENTO*** SEJAM BEM VINDOS À KROKODILUS SURF! DESCRIÇÃO: O boné da New Era com fechamento snapback é um acessório que combina estilo urbano, conforto e a qualidade reconhecida mundialmente da marca. Com design moderno e versátil, é perfeito para complementar looks casuais e streetwear no dia a dia. O modelo apresenta painel frontal estruturado com o icônico logo “NY” do New York Yankees bordado em destaque, trazendo autenticidade e representando uma das franquias mais tradicionais do beisebol mundial. O bordado possui acabamento detalhado, garantindo um visual marcante e sofisticado. A aba curva com costuras reforçadas proporciona um caimento clássico e ajuda na proteção contra o sol, enquanto a estrutura do boné oferece conforto e excelente ajuste à cabeça. O modelo também conta com bordado lateral da New Era, reforçando a originalidade e o padrão premium da marca. Outro grande diferencial é o fechamento snapback, sistema de ajuste em pinos que permite regular o tamanho de forma prática e segura, proporcionando encaixe confortável para diferentes medidas. ESPECIFICAÇÕES: Marca: New Era; Modelo: Aba curva; Fechamento: Snapback (ajuste regulável); Logo frontal bordado do New York Yankees; Bordado lateral com logo New Era; Estrutura frontal reforçada; Aba curva com costuras resistentes; Estilo casual e urbano; Confortável e ideal para uso diário; Tamanho: Único.', 249.9, 179.9, NULL, 'Fashion Accessories > Hats & Caps', 'https://cf.shopee.com.br/file/sg-11134201-82613-mlxvm6e2jke88c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F324536294%2F50107337712', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23699128099', 'Choker Borboleta Vazado em Prata 925 Legítima Delicado e Moderno', 'A choker borboleta vazada em prata 925 é uma joia delicada e elegante, que simboliza leveza e transformação. Seu design moderno com pingente de borboleta recortado traz um toque de feminilidade e sofisticação, perfeito para compor looks elegantes e cheios de significado. Ideal para o uso diário ou ocasiões especiais, essa peça combina perfeitamente com outras correntes e chokers, criando composições únicas e harmoniosas. Características: - Material: Prata 925 legítima - Modelo: Choker com pingente de borboleta vazada - Comprimento: Ajustável - Fecho: Tradicional - Acabamento: Polido e brilhante - Acompanha: Certificado de garantia de autenticidade - Observação: Não acompanha caixinha Uma joia delicada e atemporal, perfeita para expressar leveza, liberdade e estilo em cada detalhe.', 139.0, 139.0, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/br-11134207-820mg-mlrsmrgg6ccm46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340468765%2F23699128099', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209467277', 'Skol Pilsen Cerveja Lata', 'Skol Pilsen é uma típica cerveja clara, com sabor leve e suave. Seu teor de amargor é menos acentuado e seu teor alcoólico é médio. Por ser leve e refrescante, é perfeita para curtir mais rolês com a galera.', 3.49, 3.49, NULL, 'Food & Beverages > Alcoholic Beverages > Beer & Cider', 'https://cf.shopee.com.br/file/sg-11134201-8258h-mqnekp4pe9du64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554958%2F58209467277', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45314516053', 'Brinco Feminino Ear Cuff Fio Cravejado com Gota Pendurada Prata 925', 'O Brinco Ear Cuff Fio Cravejado com Gota Pendurada em Prata 925 é uma joia moderna e sofisticada, perfeita para quem deseja destacar o visual com elegância. O fio cravejado com zircônias proporciona brilho intenso, enquanto a delicada gota pendurada adiciona movimento e charme, criando um efeito refinado e contemporâneo. Material: Prata 925 Pedra: Zircônias transparentes Detalhe: Ear cuff com fio cravejado e gota pendurada Fecho: Pino com tarraxa Acompanha: Certificado de garantia de autenticidade Observação: Não acompanha caixinha Uma joia delicada e elegante, ideal para ocasiões especiais ou para trazer um toque de sofisticação ao dia a dia.', 400.0, 220.0, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/br-11134207-820le-mqxtj9jgpx51db', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340468765%2F45314516053', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
