INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52056012274', 'RADIO MP3 PLAYER 7 CORES BLUETOOTH LIKE 521', 'Descrição do Produto Principais Características e Funcionalidades Conectividade e Mídia: Reproduz MP3/WMA/APE/WAV via USB e slot para cartão TF (microSD), além de entrada AUX (3,5 mm). Bluetooth e Mãos-Livres: Conexão sem fio para streaming de música e chamadas telefônicas (microfone embutido). Carregamento USB: Porta USB dedicada para carregamento de dispositivos móveis, com corrente de 5V/2.1A. Rádio FM: Receptor estéreo com sintonia PLL e capacidade de armazenar até 18 estações predefinidas. Potência de Saída: Máxima de 50 Watts x 4 canais. Áudio e Visor: Equalizador predefinido (EQ), controle de graves/agudos/balanço/fader. Visor LCD e exibição de relógio digital. Extras: Controle remoto sem fio, seletor estéreo/mono e função Local/Distant (LOC/DX). Tensão: 12V Conteúdo Da Embalagem 01 Radio Mp3 Player Bluetooth 01 Controle Remoto 02 cabos', 74.9, 74.9, NULL, 'Audio > Media Players > MP3 & MP4 Players', 'https://cf.shopee.com.br/file/br-11134207-81ztx-mkmts46ahqtf9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379659661%2F52056012274', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
