INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899424168', 'Casaco Feminino Suede Com Bolsos Marialícia Preto', 'O Casaco Marialícia é a escolha perfeita para composições elegantes com um toque urbano. Feito em suede estruturado, que oferece uma textura macia, ele possui comprimento alongado e modelagem reta com caimento alinhado ao corpo. Sua abertura frontal sem fechamento permite sobreposições versáteis, enquanto os bolsos trazem praticidade e estilo ao visual. Ideal para um office look ou compromissos casuais com elegância, invista nessa peça-chave para elevar seu closet com atitude e charme.Detalhes da peça: • Feito em suede estruturado • Comprimento alongado • Modelagem reta • Possui bolsos • Ideal para um office look ou compromissos casuais', 259.9, 155.94, NULL, 'Women Clothes > Jackets, Coats & Vests > Winter Jackets & Coats', 'https://cf.shopee.com.br/file/sg-11134201-8257u-mr1tuxjzk2de6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F22899424168', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
