INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20898472568', 'Supreendido pelo Temor | Natha', 'Sei muito bem o que você está pensando, porque isso sempre acontece comigo. Eu pego um livro na mão porque gostei da capa, e logo começa o debate: "Devo ler este livro? Será que vale a pena?". Estas "perguntas frequentes" lhe darão uma visão geral do livro, e em 2 minutos você saberá se ele é para você. 14x21cm 290 Páginas', 32.9, 23.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7qvdh-lg4kh0raeapvfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F20898472568', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
