INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58012819361', 'Areia Higiênica Biodegradável 2Kg Mandioca E Milho P/ Gatos Controle De Odores Torrão Rápido', 'Areia Higiênica Miau Fresh Clean Max 2kg – Natural, Econômica e Eficiente!Mantenha a caixa de areia do seu gato sempre limpa e livre de odores com a Miau Fresh Clean Max. Produzida com ingredientes naturais, possui grãos finos de alta absorção que formam torrões firmes, facilitando a remoção diária e garantindo mais praticidade para você e conforto para o seu pet. Neutraliza odores indesejadosForma torrões firmes e resistentes Alta absorção de líquidos Maior rendimento e economia Produzida com ingredientes naturais Ideal para gatos de todas as idades e portes. Especificações:Marca: Miau Fresh Linha: Clean Max Peso: 2kg Tipo: Areia higiênica para gatos Granulometria: Grãos finos Composição: Milho e mandioca Indicação: Uso veterinário Ofereça mais higiene, conforto e bem-estar para o seu gato com uma areia de alta qualidade que ajuda a manter o ambiente sempre agradável.', 39.9, 18.9, NULL, 'Pets > Litter & Toilet > Cat Litter & Boxes', 'https://cf.shopee.com.br/file/br-11134207-820lv-mqnpr92rg2ki75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F790605924%2F58012819361', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793730657', 'Capacete Aberto Azul Personalizado Tartaruga 46 Viseira Fumê Adesivado Osascorte', 'Capacete Adesivado ( Sem verniz ) New Tree Este capacete aberto oferece conforto e sensação de liberdade a cada quilômetro percorrido. Graças ao seu desenho, você terá um amplo campo de visão e audição, o que lhe permitirá manter-se atento a fatores externos. Visual clara e sem inconvenientes Com sua viseira simple você desfrutará de passeios agradáveis na moto, pois evitará o ingreso de qualquer elemento do ambiente que possa prejudicá-lo. Rigidez e durabilidade É fabricado com materiais de alta qualidade que absorvem energia e proporcionam grande dureza. Em caso de impacto o golpe se concentrará num só ponto, para amortecer o movimento e evitar contusões. Suavidade em sua caminhada Seu material interno de Nylon é acolchoado e elástico, permitindo maior absorção de impacto quando o capacete para. Sinta conforto e segurança ao longo do seu percorrido!', 179.9, 159.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgi0ekg2jbpc4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F695489389%2F23793730657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22096202692', 'Papel de Parede Contact Amadeirado 065 Adesivo 10m X 45cm - Leo Tack', 'Papel de Parede Amadeirado Adesivo c/ 10Metros X 45CM - Papel contact de madeira Pedidos Feitos até 12:00 (MEIO DIA) Serão Enviados no MESMO DIA!!! Papel de Parede Autocolante, pode também ser utilizado em Móveis para Envelopamento, material plástico adesivo podendo ser molhado ! DESCRIÇÂO - 80 Micra - Não precisa de cola ( ADESIVO ) - Comprimento de 10 metros - Largura padrão de 45 centímetros - Lavável (água, sabão neutro e pano macio) Ideal para aplicação em paredes ou qualquer superfície lisa. Pode molhar (lavável) e ser aplicado em paredes de cozinha (próximo a fogões), dentro do box de banheiro etc. *Compre o rolo que tenha o comprimento igual o superior á altura da sua parede, assim não terá emendas na altura, somente na largura da parede (indicado). COMO APLICAR O PLÁSTICO AUTOADESIVO: 1 - Limpe e seque a área de aplicação. 2 - Corte o material um pouco maior do que a medida necessária. 3 - Descole uma ponta de 5 cm do papel protetor e aplique o produto a partir dos cantos da área a ser revestida. 4 - Com uma mão, descole aos poucos o papel protetor em diagonal. Com a outra, fixe o produto do centro para as bordas utilizando uma flanela. 5 - Para evitar bolhas pressione bem ao aplicar. 6 - Caso o material fique torto, descole o adesivo com cuidado e reinicie a aplicação. 7 - Pressione bem o produto aplicado para maior fixação. Para eliminar bolhas, faça pequenos furos com uma agulha fina. 8 - Não aplique esse produto em superfícies porosas, ásperas, oleosas, ou áreas expostas a forte calor. O produto apenas adere em paredes emassadas, ou seja, que tenham acabamento com massa corrida seguida de pintura. Pode-se aplicar em vidros, sobrepor azulejos, madeiras lisas e sem texturas, mesas, móveis. A aplicação do produto em paredes apenas rebocada, lixada o produto não adere e não tem garantia. Perguntas frequentes: P: E fácil de aplicar? R: Super fácil, qualquer pessoa com um pouco de pratica e vontade consegue P: Quantos metros eu preciso para cobrir uma parede? R: Me mande no chat a metragem que irei te mandar quantos metros será preciso', 100.0, 19.96, NULL, 'Home & Living > Decoration > Wallpapers & Wall Stickers', 'https://cf.shopee.com.br/file/sg-11134201-7qvfb-lj61hmb6etqle0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F721033344%2F22096202692', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
