INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198648814', 'Caneca Chubby 330 ml Oxford Menta', 'Seja para tomar um bom chá ou servir aquele cafezinho especial, as canecas são essenciais no dia a dia. O novo modelo Chubby tem formato bojudo, de alça larga e design empilhável, superprático de armazenar. As cores transitam entre os alegres tons pastéis menta e rosa e as variações contemporâneas de cinza e preto. O acabamento das canecas é acetinado, oferecendo uma experiência sensorial completa durante o uso. Conteúdo da embalagem: 1 Caneca Chubby de 300 ml de capacidade, 7,5 cm de diâmetro e 9,3 cm de altura - Garantia: 3 meses para defeitos de fabricação - Marca: Oxford - É apto para lava-louças: Sim - Tipo de embalagem: Papelão pardo - Material: Cerâmica - Cor: Verde - Linha: Canecas - Forma: Redondo - Modelo: Chubby - Formato de venda: Unidade - Linha/Decoração: Chubby - Unidades por kit: 1 - É kit de fábrica: Não - Tipo: Caneca - Capacidade: 330 ml - Decoração: Monocromática - Uso: Resistente a micro-ondas, resistente a lava-louças - É Apto para micro-ondas: Sim - Quantidade de peças: 1 - É kit: Não - Condição do item: Novo - Código universal de produto: 7891361439775 - Diâmetro: 7,5 cm - É termossensível: Não - Altura: 9,3 cm - Fabricante: Oxford - SKU: 151070 ATENÇÃO: Para compras de pessoa jurídica, cadastre os dados exatamente como constam em seu cartão do CNPJ', 54.9, 54.9, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-7raso-maydd090tiz58a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1075271269%2F23198648814', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19897988617', 'Ainda Fazendo o Impossível | Oral Roberts', 'Por mais de 50 anos, oral roberts levou as boas-novas de jesus cristo aos confins da terra, dedicando-se totalmente a propagar a plenitude do poder curador do altíssimo para todos. Tudo o que o dr. Roberts falou e realizou teve o toque de seu grande amor e zelo para com o povo de deus. nesta obra, escrita ao final de uma vida que tocou milhões de pessoas ao redor do mundo, ele revela, apaixonadamente, as alavancas que mudaram a sua própria história e despertaram a igreja de seu tempo. A partir da presença do deus invisível, roberts apresenta as chaves que liberarão o poder e o amor do senhor sobre você. 16x23cm 352 Páginas', 49.9, 44.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rfi8-m38l7lg4ec9pa5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F19897988617', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794614252', '201 Atividades | 6 ANOS | Brochura', 'Uma coleção elaborada para crianças de 3 a 6 anos de idade, a qual objetiva desenvolver habilidades cognitivo-motoras e de raciocínio lógico, por meio de atividades lúdicas e diversificadas. 26,9x20 cm 104 páginas', 28.9, 25.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8259t-mg89utm6no5m51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23794614252', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998798611', 'Jogo de 4 canecas 350ml Oxford Flat Gray', 'A linha Flat chega para complementar as cerâmicas da Oxford agregando versatilidade e beleza ao servir. Tigelas e canecas completam a coleção trazendo ainda mais possibilidades de uso para as peças, que vão do ambiente doméstico ao profissional. Com formas retas e funcionais, as peças da linha são fáceis de armazenar até mesmo em armários mais compactos. A caneca Chumbo Acetinado combina com a decoração Gray. A caneca Flat Chumbo Acetinado tem capacidade para 350 ml.Peças com acabamento acetinado podem apresentar marcas superficiais de uso. Para removê-las, recomenda-se a limpeza com o lado abrasivo da esponja, com movimentos suaves e detergente neutro. Conteúdo da embalagem: 4 Canecas 350Ml - Garantia: 3 Meses para Defeitos de fabricação - Marca: Oxford - Tipo da embalagem: Papelão pardo - Material: Cerâmica - Cor: Cinza - Forma: Redondo - Tipo: Canecas - Linha: Flat - Modelo: Gray - Unidades por kit: 4 - É apto para lava-louças: Sim - É Apto para microondas: Sim - Formato de venda: Kit - Utilizações Seguras: Resistente ao micro-ondas, Resistente a lava-louças - Condição do item: Novo - Unidades por kit: 4 - Tipo de garantia: Garantia do fabricante - País de origem: Brasil - Duração de garantia: 3 meses ATENÇÃO: Para compras de pessoa jurídica,cadastreosdados exatamente como consta em seu cartão do CNPJ', 179.96, 179.96, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-7rdvs-md50b6ye633w99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1075271269%2F22998798611', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22391499021', 'ENCORDOAMENTO VIOLÃO NYLON GIANNINI GENWB MÉDIO BOLINHA', 'ENCORDOAMENTO VIOLÃO GIANNINI GENWB EM NYLON MÉDIO C/ BOLINHAModelo: GENWB A consagrada Linha Canário Giannini destaca-se por sua pureza tonal, durabilidade e por possuir medidas especialmente desenvolvidas pela Gianinni, sendo totalmente únicas e originais. A linha Canário Giannini oferece encordoamento para Cavaco, Viola, Violão Aço, Violão Náilon, Bandolim, Guitarra e Contrabaixo. Selo de Qualidade ISO 9001 Toda a linha de encordoamentos Giannini conta com a aprovação do selo de qualidade ISO 9001. Mas o quê é o selo ISO 9001? ISO 9001 é uma série de normas e regras que buscam garantir a qualidade final do seu encordoamento. Estes procedimentos englobam desde a escolha da matéria-prima e seus fornecedores, passando por todo o processo de produção dos encordoamentos, capacitação da mão-de-obra envolvida na produção, sua distribuição, até o produto chegar ao lojista e às mãos do consumidor. Estes processos e todos os envolvidos nele passam por auditorias todos os anos, para verificar se estão sendo seguidos de acordo com a norma estabelecida, para que o selo seja renovado. Desde 2007 a Giannini conta com o selo ISO 9001 em sua linha de encordoamentos, sendo renovado anualmente e comprovando a qualidade de cada encordoamento que chega à suas mãos e aos seus instrumento CARACTERÍSTICAS Aplicação: Violão Tensão: .028 -.043 - Média Material: Nylon Revestimento: Cobre Prateado Acabamento: Bolinha OUTROS Informação adicional: Conserto / Troca: Análise Garantia: 12 meses Pesquisa:encordoamento|corda|cordas|medio|nylon|canario|genwb|giannini', 36.99, 33.3, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7qvfd-lhzb0nsiwqm2f7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1006271683%2F22391499021', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56607512196', 'Subúrbios da Galáxia | Antologia Poética | Geraldo Carneiro', 'Embarque em uma viagem poética através do cosmos com Subúrbios da Galáxia, uma coletânea que abrange quatro décadas da notável obra do autor. Explore a evolução da poesia ao longo das décadas, enquanto Geraldo Carneiro compartilha sua jornada criativa. Cada poema é uma janela para sua alma poética. Este autor multifacetado é poeta, letrista, escritor, roteirista, teatrólogo e tradutor, e essa coletânea abrange sua diversidade literária, oferecendo uma experiência única de exploração criativa. Os poemas foram cuidadosamente selecionados pelo próprio autor, garantindo que cada palavra e verso sejam verdadeiras joias poéticas. Geraldo Carneiro é uma figura notável na literatura, e esta coletânea é uma oportunidade de apreciar e celebrar seu legado poético. Esta é uma jornada literária que o levará por quatro décadas de criação poética, proporcionando uma visão única da mente de um mestre das palavras. 20x13 cm 128 Páginas', 14.9, 10.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-825zz-mm3iomkn1xqb8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F56607512196', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297439017', '3 palavrinhas - Cores do amor', 'Prepare-se para se divertir e louvar a Deus com Três Palavrinhas! Será muito mais divertido colorir os desenhos deste livro com essa turminha. 20x26cm 8 Páginas', 9.0, 4.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rcdv-ltq177o2a3c3d7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23297439017', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205867082', 'Copo de treinamento Buba com Alça Removível Rosa 250ml', 'Copo de treinamento Buba com Alça Removível 250ml É perfeito e ideal para a transição da mamadeira pro copo. Possui alças para facilitar que a criança segure o copo, é antivazamento, permitindo à criança beber o líquido sem derramamentos, com bico super macio de silicone também ajuda a evitar que o palato e gengiva da criança sejam machucados e tampa para manter o bico protegido de insetos e impurezas. - Marca: Buba - Capacidade: 250ml - Tamanho do Copo - 14 cm x 12 cm - Pode ir a lava louça - Livre de BPA - Produto 100% Atóxico', 35.02, 35.02, NULL, 'Mom & Baby > Feeding Essentials > Utensils', 'https://cf.shopee.com.br/file/sg-11134201-8262t-ml6dcmv6nv9k18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F58205867082', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299564561', 'Aconselhamento Redentivo | Wadislau Gomes Martins', 'O aconselhamento cristão não deveria ser considerado como uma área separada do aspecto pastoral e da comunhão cristã na igreja. Para o pastor, as habilidades para o aconselhamento são tanto parte do preparo e da entrega de sermões quanto da prontidão para responder aos seus ouvintes após a mensagem. É preciso que o pastor seja hábil intérprete da Palavra e hábil intérprete de pessoas, se ele quiser ser eficaz no ministério. Há lugar para o especialista, como em todas as outras áreas ministeriais. Contudo, em geral, o aconselhamento cristão deve ser visto como a habilidade relacional de ajuda mútua para o conhecimento de Deus e do homem. 16X23CM 262 Páginas', 57.9, 56.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rff4-m3mqzej31wsu11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F19299564561', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993613738', 'Moedor de Grãos E Cereais 700ml 37cm Bestfer', 'O Moedor de Grãos e Cereais Manual Bestfer 700ml 37cm é uma solução prática e sustentável para quem busca moer grãos em casa. Com capacidade de 700ml e fabricado em materiais resistentes como aço inoxidável e alumínio, este moedor garante durabilidade e resistência à corrosão. Seu design manual oferece controle total sobre a granulometria dos grãos, ideal para quem aprecia um toque artesanal na cozinha. Com estrutura robusta e acabamento em metal, o moedor Bestfer proporciona estabilidade durante o uso. A tigela de aço inoxidável facilita a colocação e visualização dos grãos, tornando o processo simples e intuitivo. Vantagens: - Durabilidade garantida pelo uso de aço inoxidável e alumínio. - Controle total da granulometria com sistema de moagem manual. - Estrutura robusta que assegura estabilidade durante a operação. - Tigela de aço inoxidável para fácil colocação dos grãos. - Manivela de madeira que proporciona conforto ao manuseio. - Não necessita de eletricidade, sendo uma opção econômica e sustentável. Especificações técnicas: Marca: Bestfer Modelo: Máquina de Moer Grãos e Cereais Capacidade: 700ml Dimensões: 37cm de altura Material: Aço inoxidável e alumínio Conteúdo da embalagem: 1 Moedor de grãos Bestfer Garantia: - 3 meses de garantia', 198.9, 172.9, NULL, 'Home Appliances > Kitchen Appliances > Food Processors & Meat Grinders', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m4upnslbh2nmd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F23993613738', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207682358', 'Fita Dental Hillo 100m', 'A Fita Dental Hillo 100m foi desenvolvido com o intuito de proporcionar mais saúde e proteção bucal, de forma prática e rápida. A fita dental ajuda a resolver problemas da gengiva, pois age na prevenção da cárie, tártaro e das placas bacterianas, causadora do mau-hálito. Graças a sua embalagem prática você pode leva-lo na bolsa, na mochila ou até mesmo no bolso para qualquer lugar, tais como, trabalho, academia, escola, faculdade, festas, entre outros. Recomendamos seu uso da seguinte forma: Corte aproximadamente 45cm da fita dental, introduza entre os dentes e movimente a fita para cima e para baixo, penetrando de forma delicada a gengiva. Para melhor efeito usar creme dental', 12.79, 11.32, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-825zr-mmaeunqroirs5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F58207682358', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397727357', 'Guarda Roupa Solteiro 3 Portas e 2 Gavetas Wind Branco/Rosa - Demóbile', 'Guarda Roupa Solteiro 3 Portas e 2 Gavetas Wind Flex Branco/Branco ou Rosa - Demóbile Marca: Demóbile Dimensões(Cm): Comprimento(Profundidade): 47cm x Largura: 80cm x Altura: 181cm Material de Estrutura - Estrutura 100% MDP Tipo de Pintura - Ultravioleta Tipo de Acabamento da Pintura - Semi Brilho Diferenciais dos Móveis de Quarto - Color Flex Material dos Cabideiros - Cabideira Metálico Tipo de Dobradiças - Dobradiças Metálicas Quantidade de Portas - 3 Portas de Abrir Tipo de Corrediça - c/ Corrediças Metálicas Quantidade de Gavetas - 2 Gavetas Tipo dos Pés - ABS/PVC Quantidade de Prateleiras - 3 Montagem do Produto - Desmontável Garantia - Garantia de 90 Dias Imagens Meramente Ilustrativas. Não nos responsabilizamos pela montagem/instalação dos produtos. Todas as informações divulgadas são de responsabilidade exclusiva do fabricante/fornecedor. -Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades - Confira as dimensões do produto e analise se irão passar normalmente por elevadores, portas, escadas e corredores, pois não nos responsabilizamos caso o produto necessite durante a entrega de: Desmontagem, subir escadas ou ser transportado por guincho, cordas para apartamentos. A entrega limita-se ao descarregamento em local que tenha e ofereça total facilidade de acesso normal; - Só fazemos entregas por transportes rodoviários. Não realizamos entregas por transportes fluviais, aéreos e outros diferente de rodoviário. Não realizamos entregas na região norte: Amapá, Amazonas, Pará, Roraima e Acre; - Temos áreas com restrição e dificuldades que os transportadores rodoviários não atendem. Área de difícil acesso, área de risco, área rural, áreas fluviais, estradas não pavimentadas; - Sendo assim, caso seu endereço esteja em área restrita de entrega, a retirada de sua compra deverá ser realizada no CD do transportador ou indicar no momento da compra um endereço entrega fora da área restrita; - Caso realize pedido com entregas em locais de difícil acesso ou áreas com restrição e dificuldades que os transportadores e proprio correios não atendem, a compra sera cancelada pela Costa Rica Colchões, com a devida comunicação e estorno do pagamento ao cliente.', 459.91, 436.92, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-823pq-mp589cwdboxs36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1235923910%2F23397727357', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58263119340', 'Kit 2 Und Cetaphil Loção Hidratante 473ml', 'Cetaphil Loção Hidratante 473ml Rosto e Corpo | Pele Sensível, Normal a Seca Clinicamente comprovada que restaura a barreira cutânea em apenas 1 semana • Fortalece a barreira cutânea em 24 horas • Textura leve • Clinicamente comprovado para hidratar a pele sensível sem irritar • Redução imediata do ressecamento A Loção Hidratante Cetaphil foi especialmente reformulada e aprimorada com um complexo de ingredientes com niacinamida, pantenol e glicerina hidratante para manter a pele sensível hidratada. Clinicamente comprovada. Protege contra os 5 sinais da pele sensível: Aspereza, desconforto, repuxamento, ressecamento e barreira cutânea enfraquecida.', 212.43, 188.99, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/br-11134207-820m1-mpuytxzi9s0388', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F58263119340', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197912358', 'Copo Medidor Graduado Com Base Emborrachada 5 Medidas 500ml Arthi', 'Copo Medidor com Base Emborrachada 500 ml - 5 Medidas Diferentes - Arthi Descrição: Facilite suas receitas com o Copo Medidor da Arthi, projetado para medir líquidos e ingredientes secos com precisão. Com capacidade de 500 ml e cinco medidas diferentes indicadas no corpo do copo, ele é ideal para quem gosta de cozinhar com exatidão. A base emborrachada oferece maior estabilidade e segurança durante o uso, evitando deslizamentos. Características: - Capacidade: 500 ml, com marcações de 5 medidas diferentes para precisão em cada receita. - Material: Plástico resistente e transparente, facilitando a visualização das medidas. - Design: Prático e moderno, com escala de medidas bem visível para líquidos e ingredientes secos. - Base: Emborrachada para evitar deslizamentos e proporcionar maior estabilidade durante o uso. - Uso Versátil: Pode ser usado para medir líquidos, farinhas, açúcares, arroz e outros ingredientes. Benefícios: - Permite medições precisas, garantindo o sucesso das suas receitas. - A base emborrachada oferece maior segurança, evitando que o copo escorregue durante o uso. - O design transparente com marcações visíveis facilita o uso, ideal tanto para cozinheiros iniciantes quanto para os mais experientes. - Fácil de limpar e armazenar, sendo uma ferramenta essencial em qualquer cozinha. Com o Copo Medidor da Arthi, medir ingredientes para suas receitas ficou ainda mais prático e preciso. A base emborrachada proporciona segurança e conforto, enquanto as marcações claras garantem que cada ingrediente seja medido com exatidão. Ideal para quem valoriza praticidade e precisão no dia a dia da cozinha!', 43.99, 43.99, NULL, 'Home & Living > Kitchenware > Measuring Glasses & Spoons', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9px4hyo045ea5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402450553%2F22197912358', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898483306', 'Cooktop 4 Bocas de Indução e a Gás Electrolux Híbrido 2 de Indução e 2 a Gás (IE62H)', 'O Cooktop a Gás e Indução Electrolux Expert com Power Boost e Chama Vertical IE62H oferece versatilidade, potência e mais controle no seu dia a dia com duas opções: gás e indução! O Cooktop Electrolux permite que você aproveite as vantagens de ambos os mundos, descobrindo o desempenho avançado da indução e utilizando o cooktop a gás ao mesmo tempo. Tudo isso sem a necessidade de abrir mão das suas panelas e da forma como você já está acostumado a cozinhar. A tecnologia PowerBoost no cooktop de indução proporciona mais agilidade no preparo das suas receitas, você consegue, por exemplo, ferver a água até 2X¹ mais rápido com a tecnologia de Indução. Já a chama vertical do cooktop à gás, proporciona mais eficiência na hora de cozinhar, além de possuir um design diferenciado que facilita a limpeza, e peças que podem ser lavadas em lava-louças. A mesa de vidro é lisa e plana, que além de dar estabilidade às panelas, facilita a limpeza, pois não possui cantos ou frestas. As grades, que são as peças que ficam sobre os queimadores e resistem à altas temperaturas, possuem o formato ideal para as panelas e podem ser lavadas na máquina de lavar louça, assim como os queimadores. Além disso, para obter melhores resultados, o Cooktop Expert IE62H Electrolux tem 9 velocidades, garantindo um controle preciso da temperatura durante o preparo das suas receitas. As grandes do cooktop à gás são de ferro fundido, trazendo mais robustez e estabilidade para as panelas. ¹Testes internos com 1L de água quando comparada a tecnologia de indução com o sistema a gás do modelo Continental FC4IB. Tudo pensado para você. Para uma experiencia Electrolux completa durante a compra de seu novo produto, sugerimos que leia cuidadosamente as especificações, guias e manuais do produto para a instalação correta. Caso haja uma dúvida específica, por favor, entre em contato conosco por meio dos Canais de Atendimento oficiais.', 3699.0, 3449.0, NULL, 'Home Appliances > Kitchen Appliances > Stoves, Hobs & Gas Regulators', 'https://cf.shopee.com.br/file/sg-11134201-7rffh-m9yioo0icweub6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1526836548%2F22898483306', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198979525', 'Geladeira Electrolux Frost Free 320L Duplex Inox Look (TF38S)', 'A Geladeira Electrolux Frost Free 320L Gaveta Hortifruti Duplex Inox Look (TF38S) tem a exclusiva Gaveta HortiFruti: organizar e visualizar suas frutas e legumes nunca foi tão fácil. Esse espaço dedicado previne o desperdício e mantém seus alimentos frescos por mais tempo. O novo design é robusto e garante que esse refrigerador seja não apenas durável, mas também prático, adaptando-se perfeitamente à sua rotina e às suas necessidades de armazenamento. E, para aqueles momentos em que você precisa de resfriamento rápido, o Turbo Freezer é a solução ideal, perfeito para festas ou para quando você chega em casa com as compras e precisa refrigerar algo rapidamente. A conveniência continua com a Bandeja de Ovos, que oferece espaço organizado para até 12 ovos, enquanto a Forma de Gelo mantém suas bebidas sempre geladas com capacidade de até 30 cubos de gelo. A iluminação de LED interna não só proporciona uma visão clara do interior da geladeira, como também economiza energia. Para completar, você pode melhorar ainda mais sua experiência com a Geladeira Electrolux Duplex (TF38S) utilizando acessórios exclusivos1 que facilitam o seu dia a dia Precisando de mais gelo? O IceStock é um recipiente extra para armazenar cubos de gelo, ideal para celebrações. Já a inovadora linha de Vacuum Food Pres preserva os nutrientes e prolonga a vida útil dos seus alimentos em até 5 vezes (Com base em testes internos que compararam abacates e maçãs armazenados em pote hermético a vácuo com um recipiente aberto na geladeira), promovendo mais saúde e ajudando a reduzir o desperdício, um benefício para você e para o meio ambiente. Todos os acessórios são vendidos separadamente.', 2899.0, 2649.0, NULL, 'Home Appliances > Kitchen Appliances > Refrigerators', 'https://cf.shopee.com.br/file/sg-11134201-824ie-mfe4phfv3mkuf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1526836548%2F22198979525', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22692807227', 'Violao Eletroacustica Takamine Gd20ce Kit Capa + Acessorios', 'Desfrute com este violao Takamine da conexao com a musica. Ele e projetado para amadores e profissionais. Com este instrumento voce vai descobrir novos acordes, cantar suas cancoes e vai desfrutar da vida musical. ACOMPANHA: -01 CAPA REFORCADA EM NYLON 600 -01 CABO DE 5 METROS -01 CORREIA -01 CAPOTRASTE -03 PALETAS Um modelo para cada guitarrista A tampa de cedro oferece um tom calido, muito sonoro e uma resposta rapida conseguindo um som mais duro, aspero, forte e direto. Qualidade se destaca As cordas de aco sao caracterizadas pelo seu baixo alongamento e resistencia a corrosao e a abrasao. Elas sao mais duraveis, solidas e geram um som brilhante e claro.', 4363.0, 4363.0, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/sg-11134201-7rblm-lqnqs91qkb6jc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F22692807227', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
