INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22692933526', 'Kit Sortido 2 Peças de Roupas Masculino Infantil Inverno – 1 blusa casaco + 1 calça de 1 ao 10 – Kit 1 Conjunto Moletom', 'Conjuntos de Moletom para Meninos! 🧥❄️ Perfeito para garantir conforto e estilo ao seu pequeno durante o outono e inverno! ✅ Conjunto Completo: 1 casaco e 1 calça. ✅ Tecido Confortável: 60% algodão e 40% poliéster, garantindo maciez e conforto. ✅ Ajuste Perfeito: Ribana nos punhos e na barra para maior proteção contra o frio. ✅ Moletom Peluciado: Conforto e aquecimento extra nos dias frios. ✅ Estampas variadas e encantadoras: Muita praticidade e estilo em uma única compra. Sugestão de Tamanho por Idade: Tamanho 1: Indicado para 6 meses a 1 ano Tamanho 2: Ideal para 1 ano Tamanho 3: Ótimo para 2 anos Tamanho 4: Excelente para 3 anos Tamanho 6: Ideal para 4/5 anos Tamanho 8: Perfeito para 6/7 anos Tamanho 10: Excelente para 8/9 anos Os tamanhos podem variar de acordo com o biotipo/tamanho de cada criança. 👉 Consulte a tabela de medidas nas imagens, ou na guia de tamanho da Shopee. IMPORTANTE! ⚠️ Não há opção de escolha dos modelos. ⚠️ Os modelos enviados serão sortidos conforme a disponibilidade em estoque. ⚠️ Na compra de 11 conjuntos do mesmo tamanho, pode haver repetição de cor ou estampa. Envios em 24 horas 🚛 - Para todos os pedidos realizados antes das 13h. Garanta já o seu kit e proporcione o máximo de conforto e estilo para seu príncipe!', 62.9, 27.9, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/br-11134207-820lk-mqxma4c9ryfa3d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341167297%2F22692933526', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52952648962', 'Kit 6 Peças de Conjunto Cropped Infantil Menina Moda Praia Verão Roupa Infantil Feminina de Carol Fresquinha', 'Conjunto Verão Menina Cropped e Shorts – Estilo, Frescor e Alegria KIT 6 PEÇAS: Receba 3 Conjuntos - 3 Blusas + 3 Shorts O Conjunto Verão Menina Cropped e Shorts foi criado para deixar a rotina mais leve, colorida e confortável. Produzido em suplex de alta qualidade, ele proporciona toque macio, excelente caimento e uma estampa fofas que trazem todo o charme e delicadeza que as pequenas adoram. Benefícios e Funcionalidades O cropped estampado entrega leveza e sofisticação, enquanto o short com cadarço decorativo acrescenta um toque moderno ao visual. Com tecido leve e respirável, o conjunto é perfeito para os dias quentes, oferecendo conforto o dia inteiro. Suplex leve, macio e confortável Estampa vibrante e durável Short com cadarço que completa o look com estilo Look pronto em segundos, combinando perfeitamente Aplicações e Uso Indicado para passeios, viagens, brincadeiras ao ar livre, praia e dias de verão. Perfeito para meninas de 1 a 9 anos que gostam de conforto e estilo em todas as ocasiões. Garanta já esse kit de conjunto encantador e deixe o verão da sua pequena ainda mais especial!', 100.0, 67.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj46rw4pi8ea68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341167297%2F52952648962', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
