INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23199191739', 'Pelúcia Cute Pet Unicórnio Interativo E Musical - Toys Import J24587', 'Descubra a Pelúcia Cute Pet Unicórnio interativo e musical J24587, um companheiro encantador que traz alegria e diversão para crianças e adultos. Com 22 cm de altura, este unicórnio é feito de pelúcia macia e plástico, proporcionando uma experiência tátil agradável e segura. Este unicórnio interativo não é apenas um brinquedo, mas um amigo que se movimenta e emite sons, estimulando a imaginação e a criatividade. Ideal para momentos de brincadeira, ele se torna um elemento essencial no quarto das crianças, promovendo o desenvolvimento emocional e social. A Pelúcia Cute Pet Unicórnio é perfeita para presentear em aniversários ou ocasiões especiais, encantando a todos com seu design adorável e suas funções interativas. Adicione um toque mágico ao dia a dia com este unicórnio que promete sorrisos e momentos inesquecíveis.', 249.9, 179.9, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh98ctu3wg071a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F567914216%2F23199191739', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
