INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899199081', 'Patrulha Canina Chase Patrol Cruiser - Sunny 2717', 'Com Os Bonecos Dos Personagens Patrulha Canina Patrol Cruise A Diversão É Garantida! Os Cachorrinhos Da Patrulha Canina São Os Membros Mais Amigáveis Da Comunidade. Sempre Prontos Para A Ação, Possuem Uma Mistura Única De Habilidades Para Resolver Problemas. Chase É Um Pastor Alemão Policial, Um Líder Nato. Marshall, O Bombeiro, Nunca Se Deixa Abater, Animando A Todos. Rocky É Um Entusiasta Da Reciclagem E Tem Sempre O Material Necessário Em Sua Mochila. Já Zuma É Um Lindo Labrador Chocolate Que Gosta De Dar Risadas E Surfar. Rubble Está Sempre Pronto Com A Sua Escavadora De Construção, Ele É Um Bulldog Inglês Que Adora Skate E Pranchas De Snowboard. Skye É A Única Filhote Fêmea Do Grupo, Ela É Uma Cockapoo Que Possui Um Helicóptero Adorável. Juntos, Esses Filhotes Defendem E Cuidam Da Comunidade Onde Moram, Sem Perder O Bom Humor Canino! Marca: Sunny Linha: Patrulha Canina Modelo: 2717 Dimensões do Produto na Embalagem: 28 x 20 x 13 cm Peso: 320g Garantia do Fabricante: 3 meses Garantia do Vendedor: 7 dias Produto Novo, Original, Lacrado e Acompanhado de Nota Fiscal.', 142.99, 119.99, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/br-11134207-820lk-mmj82ytcpnnocd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1162387686%2F18899199081', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
