INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21999827179', 'Fluído Lubrificante para Corrente Moto Bike Chain Lub City Sieger SL110 400ml', 'Chain Lub City SL110 400ml CARACTERÍSTICAS: Chain Lub City SL110 é uma graxa adesiva especialmente formulada para atender às necessidades de motocicletas utilizadas diariamente, proporcionando uma manutenção rápida e conveniente. Com sua excelente aderência e capacidade de lubrificação, oferece proteção eficaz aos componentes da moto, garantindo um desempenho confiável mesmo nas condições mais exigentes do uso urbano. APLICAÇÕES: Correntes, cabos, alavanca de câmbio e freio, rolamentos, cavalete lateral, haste do pedal de câmbio e freio etc. MODO DE USO: - Para melhores resultados, recomenda-se limpar a superfície com o Limpa Correntes Chain Cleaner SC110, removendo qualquer sujeira ou resíduo. - Antes de aplicar, agite vigorosamente o produto para garantir uma melhor distribuição. - Em seguida, direcione o spray para o ponto a ser lubrificado, garantindo uma cobertura completa. - Após a aplicação, deixe o produto secar por alguns minutos antes de retomar a atividade. Contém: Frasco 400ml Marca: Sieger .', 41.62, 41.62, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7ratj-max6kkdpowwg4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F552700125%2F21999827179', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20497811989', 'Capa Anti Impacto Gocase Clear Style - Galaxy A55', 'Capa Anti Impacto Gocase Clear Style desenvolvida para A55 de 6,6 polegadas. • Bordas de TPU de alta qualidade e parte traseira em policarbonato, garantindo um toque emborrachado e confortável. • Design confortável e leve. • Se encaixa perfeitamente no celular, com recortes precisos que garantem fácil acesso a todos os botões e funcionalidades do smartphone. • Botões responsivos e fáceis de apertar. • Possui bordas elevadas para ajudar na proteção da tela e das câmeras do celular. As cases da Gocase estão entre as melhores do mundo.Não utilize produtos químicos abrasivos para higienizar a capa, inclusive álcool!', 78.99, 71.1, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7rdvs-m091dk3tir3u7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1338070754%2F20497811989', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
