INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893338007', 'Cooler para Notebook Dell Part Number CN-02X1VP', 'Cooler compatível com Dell Part Number Interno Este é um Cooler bringIT compatível com o notebook Dell Part Number . Os coolers para notebook da bringIT são a solução definitiva para possíveis problemas de ventilação e resfriamento do seu equipamento. Também conhecidos como “fans”, “ventiladores” ou “resfriadores”, os coolers são responsáveis pela retirada do máximo de calor gerado pelo processador e por outros componentes eletrônicos. Para evitar problemas de compatibilidade, compare as fotos deste anuncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu cooler. Atenção: Esse é um cooler bringIT, portanto não é um produto original da fabricante Dell. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Quantidade de vias: 4 vias Corrente (Amperagem): 0.5A Tensão (Voltagem): 5V Garantia: 3 meses de garantia contra defeitos de fabricação Referência: CL200-DE-0004', 62.28, 62.28, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-82598-mqstvtm45dl9f9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F392651618%2F22893338007', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
