INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21999033501', 'Mangueira Respiro Óleo Vw Santana 1996 a 2001 - 195062 - 2137', 'Mangueira Respiro Óleo Vw Santana 1996 a 2001 195062 2137 Defletor Óleo 1.6/1.8 - Essa mangueira serve para aliviar a pressão de dentro do cárter pelo vazamento dos gases dos anéis. Isso é normal e chama-se ventilação positiva. Esse gás é reabsorvido junto com o vapor do óleo pelo motor para ser queimado dentro da camara de combustão, por isso ela fica ligada logo na entrada de ar do motor, ou seja, junto do filtro de ar. Isso foi desenvolvido para não poluir o ar com esses gases.', 37.42, 37.42, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/br-11134201-820mb-mqxp9ghcbp520e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21999033501', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997072062', 'Rosquinhas Leite Integral Vitao 110 g', 'As Rosquinhas Integrais de Leite são ideais para quem busca um lanche leve e saudável. Com uma fórmula vegana e sem lactose, atendem a diferentes restrições alimentares, promovendo bem-estar sem comprometer o sabor. Elas são uma excelente opção para servir como acompanhamento em cafés da manhã ou sobremesas simples. Uma dica: Combine as rosquinhas com a geleia sem açúcar da Vitao para um lanche delicioso. INGREDIENTES: Farinha de trigo integral, óleos vegetais (soja, milho e algodão), açúcar demerara, farinha de trigo especial enriquecida com ferro e ácido fólico, farinha de centeio, farinha de aveia, fibra de polidextrose, farinha de arroz, sal, edulcorante maltitol, fermentos químicos bicarbonato de sódio, bicarbonato de amônio, pirofosfato ácido de sódio e fosfato monocálcico, antioxidante lecitina de soja, acidulante ácido cítrico e aromas. ALÉRGICOS: CONTÉM DERIVADOS DE TRIGO, SOJA, CENTEIO E AVEIA. PODE CONTER AMÊNDOA, CASTANHA-DO-PARÁ, CASTANHA-DE-CAJU, NOZES E CEVADA. CONTÉM GLÚTEN. NÃO CONTÉM LACTOSE. INTEGRAL, ZERO LACTOSE, VEGANO.', 11.89, 11.89, NULL, 'Food & Beverages > Snacks > Biscuits, Cookies & Wafers', 'https://cf.shopee.com.br/file/br-11134207-820lx-mmu9lrdh9wxu0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826485187%2F22997072062', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793235367', 'Kit Chocolate Cookies & Cream Zero Açúcar Marcante 70G - 6 Unidades', 'Com sabor intenso e cremosidade incomparável, ele derrete suavemente na boca, proporcionando uma experiência única. Sem adição de açúcares, é uma opção deliciosa sem culpa. A combinação perfeita entre biscoito e chocolate cremoso desperta os sentidos e deixa um gostinho de quero mais. Seja para desfrutar sozinho ou compartilhar, cada quadradinho do Chocolate Cookies and Cream é uma explosão de prazer. Para os apaixonados por combinações únicas, o Marcante Cookies and Cream é a escolha perfeita. Feito com chocolate branco de altíssima qualidade e pedaços crocantes de biscoito, ele entrega uma textura irresistível e um sabor equilibrado que agrada ao paladar. Além disso, é elaborado sem adição de açúcares, permitindo que você desfrute de cada mordida sem preocupações. Ideal para um lanche especial, uma sobremesa diferenciada ou um presente para quem você ama, esse chocolate transforma pequenos momentos em verdadeiras celebrações. INGREDIENTES: Chocolate branco zero adição de açúcares (manteiga de cacau, leite em pó desnatado, leite em pó integral, edulcorante maltitol, emulsificante lecitina de soja, estabilizante INS 476 e aromas) e cookies cacau sem glúten (fécula de mandioca, farinha de arroz, cacau em pó, fibra de polidextrose, fécula de batata, óleos vegetais (milho, soja e algodão), fibra de soja não transgênica, farinha de soja não transgênica, edulcorantes maltitol e sucralose, emulsificante lecitina de soja, estabilizantes INS 412 e INS 466, espessante goma xantana, sal, fermentos químicos bicarbonato de sódio e bicarbonato de amônio, acidulante INS 330 e aromas). ALÉRGICOS: CONTÉM DERIVADOS DE LEITE E SOJA E PODE CONTER AMÊNDOA, CASTANHA-DE-CAJU, AVELÃ, CASTANHA-DO-PARÁ E AVEIA (SEM GLÚTEN). NÃO CONTÉM GLÚTEN. CONTÉM LACTOSE. SEM GLÚTEN, ZERO ADIÇÃO DE AÇÚCARES.', 155.89, 129.39, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mkccl3bd8xdtf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826485187%2F23793235367', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
