INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209453708', 'Iogurte Morango Batavo Grego Light', 'O Iogurte Grego Morango Light da Batavo oferece sabor e leveza em perfeita harmonia, ideal para quem busca uma indulgência saudável. Experimente consumir com frutas ou grãos para uma experiência ainda mais completa. Ingredientes: Leite parcialmente desnatado e/ou leite parcialmente desnatado reconstituído, preparado de morango, leite em pó desnatado, concentrado proteico de leite, amido modificado, gelatina e fermentos lácteos.', 16.49, 14.01, NULL, 'Food & Beverages > Dairy & Eggs > Yogurt & Cultured Milk', 'https://cf.shopee.com.br/file/sg-11134201-8259e-mqneler052j1c5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1660302938%2F58209453708', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
