INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793093576', 'Kit 2 Pares Meia de Compressão Kendall 3/4 15-20mmHg', 'DESCRIÇÃO: Conforto, cuidado e elegância em cada passo. A Meia Kendall 3/4 15–20mmHg com ponteira ajuda na prevenção de doenças venosas, reduz o cansaço e melhora o retorno sanguíneo. Ideal para uso diário e viagens longas, alivia a sensação de peso e promove bem-estar. Com Tecnologia UltraPro, regula a temperatura, mantém o frescor e impede o aparecimento de odores. 🩵 Benefícios: compressão graduada, conforto térmico, alívio das pernas cansadas e longa durabilidade. COMPOSIÇÃO: 87% Poliamida e 13% Elastano. PAÍS DE ORIGEM: Brasil. INSTRUÇÃO DE LAVAGEM: Lavagem a mão/Temperatura máxima 40°C não alvejar não secar em tambor secagem em varal por gotejamento à sombra não passar não limpar a seco. INDICAÇÃO: Casos graves de insuficiência venosa Crônica como: varizes calibrosas sintomáticas, flebite crônica e casos de síndrome pós trombótica. Grandes inchaços e natureza renal cardíaca, renal ou hepática, Pós cirurgia de varizes, Edema de natureza linfática (linfedema), Síndrome pós traumática. CONTRAINDICAÇÕES: Insuficiência arterial. Gangrena. Infecções cutâneas, Enxertia de pele em processo de cicatrização nos membros inferiores. CONTÉM:02 pares.', 195.9, 195.9, NULL, 'Women Clothes > Socks & Stockings > Others', 'https://cf.shopee.com.br/file/sg-11134201-824hp-mfmblc0gcjyla6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F735725428%2F23793093576', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797030371', 'Cabo Embreagem Vw Gol 2000 a 2005 - 120074 - 1324', 'Cabo Embreagem Vw Gol 2000 a 2005 120074 1324 GIII MOTOR 1.0 AT 8V/16V/TURBO EFI (875mm) O processo se inicia quando o pedal de embreagem é pressionado, esse movimento é transmitido pelo cabo, ou varão de embreagem, até o garfo do rolamento, que pressionará a mola membrana, ou alavancas, do platô. Isso fará com que o disco de embreagem seja liberado e, dessa maneira, o torque do motor deixa de ser transmitido ao câmbio. Nesse momento, é criada uma diferença de rotação entre o motor do veículo e seu sistema de transmissão.', 58.95, 58.95, NULL, 'Automobiles > Automobile Spare Parts > Drivetrain, Transmission & Clutches', 'https://cf.shopee.com.br/file/sg-11134201-7repc-m8ggh81xi2ol03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22797030371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
