INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18897786167', 'Retentor Comando Válvulas Renault Sandero 2007 a 2014 - 1350120 - R570913V', 'Retentor Comando Válvulas Renault Sandero 2007 a 2014 1350120 R570913V Motor 1.6 16v K4M - (Altura - 5 mm) (Diâmetro do Alojamento - 42 mm) (Diâmetro do Eixo - 28 mm) São pequenas peças de borracha e metal, que tem como principal função vedar e reter óleos, graxas e qualquer outro tipo de fluído. Além disso, o retentor não permite que impurezas, como terra ou poeira, entrem no motor. A manutenção destas peças não tem um tempo certo estabelecido ou que possa ser programado, devendo ser feita a partir observação visual e tátil. Assim que você perceber algum vazamento de óleo no veículo, é a hora certa de trocar o retentor.', 29.53, 29.53, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd6p-lufaw87cg4g329', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18897786167', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28228674636', 'Colete Inflável Infantil Lagoa Azul - Intex 59663', 'Colete infantil Intex para maior segurança a seus filhos quando eles forem se divertir na água. O colete é de fácil de manuseio e fornece todo conforto e segurança para seu filho. Com cores vibrantes azul e amarelo, você pode ficar tranquilo enquanto seus filhos se divertem no verão. Produzido em vinil super resistente este colete te deixara muito mais à vontade nos passeios a praia e piscina sabendo que seus filhos estão em segurança. Características: • 40 x 30 Centímetros • Confeccionado de Vinil 9ga • Capacidade máxima de peso: 18 a 23 kg', 32.99, 32.99, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m70vv87kyp8nff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F947344701%2F28228674636', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19558100363', 'Caixa Térmica 12 Litros Cinza Bel', 'Caixa Térmica 12 Litros Bel - Frescor e Praticidade em Qualquer Lugar! A Caixa Térmica 12 Litros da Bel é a escolha ideal para tornar seus dias na praia, acampamentos, churrascos ou encontros familiares ainda mais especiais. Por que escolher a Caixa Térmica 12 Litros Bel? ✔️ Material Seguro e de Alta Qualidade: fabricada com polipropileno 100% virgem e livre de BPA, é atóxica e resistente a odores, garantindo armazenamento seguro para alimentos e bebidas. ✔️ Isolamento Térmico Avançado: revestida com Poliestireno Expandido (EPS), oferece excelente retenção de temperatura. ✔️ Design Funcional e Prático: tampa com trava de segurança e suporte para copos, além de uma alça ergonômica que facilita o transporte. ✔️ Capacidade Ideal para Todas as Ocasiões: comporta 7 garrafas PET de 600ml ou 13 latinhas de 350ml (sem gelo), perfeita para reunir família e amigos. ✔️ Fácil de Limpar e Super Resistente: desenvolvida com materiais duráveis que acompanham você em todas as aventuras. Praticidade e qualidade sempre ao seu lado!', 85.4, 85.4, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/sg-11134201-825aj-mgccdaiobxu509', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757094384%2F19558100363', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58158738448', 'Moto De Ferro Colecionável 1:64 Com 5 Tgcz008', 'A Moto de Ferro Colecionável 1:64 da Tag Toys é uma peça indispensável para os amantes de veículos em miniatura. Com uma escala de 1:64, este modelo da marca Crazy Cars traz detalhes impressionantes que encantam colecionadores e entusiastas. Embora não tenha abertura de portas, sua construção robusta e design autêntico garantem uma experiência visual única. Ideal para exibição em prateleiras ou para completar coleções, este modelo é uma verdadeira obra de arte em miniatura. A Moto de Ferro é perfeita para quem aprecia a combinação de estilo e qualidade. Adicione este item à sua coleção e destaque-se entre os aficionados por veículos em miniatura.', 47.99, 47.99, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/br-11134207-820mc-mn0620rrfsaq3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F947344701%2F58158738448', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292592622', 'Bóia Tanque Sensor Nível Gm Vectra 2005 a 2009 - 511556 - 2317', 'Bóia Tanque Sensor Nível Gm Vectra 2005 a 2009 511556 2317 Motor 2.0 8v /2.4 16v Flex O sensor de nível de combustível tem a função de medir a quantidade de combustível presente no tanque e informar a UCE (Unidade de Comando Eletrônico) que, por sua vez, controla a posição do marcador de nível no painel de instrumentos do veículo.', 106.3, 106.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-7rblq-lna4gr1cfmve02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22292592622', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192981973', 'Interruptor Óleo Ford Ranger 2005 a 2012 - 505427 - 3321', 'Interruptor Óleo Ford Ranger 2005 a 2012 505427 3321 3.0 Diesel - (Rosca - 1/4" x 18NPTF) (0,40 Bar) Indicar anomalia na pressão do óleo lubrificante. O interruptor de pressão do óleo é normalmente localizado no bloco do motor próximo a bomba de óleo, a pressão gerada pela bomba passa pelo interruptor acionando uma mola interna do mesmo fechando assim contato elétrico, enviando um sinal para o painel de instrumentos. Se a pressão for maior do que a especificada o interruptor libera a passagem do óleo de volta para o cárter. Vida Útil: Substituir a cada 40.000 Km (consultar manual do veículo)', 107.48, 107.48, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd5w-lugdbelgdv5p06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22192981973', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193094181', 'Sofá Retrátil Reclinável Zurique 2,30m Suede Velut Azul Marinho c/ Molas no Assento - King House', 'Dica Importante Gostou do produto, mas o tamanho não se encaixa em seu ambiente, ou então você tem preferência por outra cor ? Não tem problema, o sofá Zurique está disponível em 5 medidas e 7 cores diferentes para que se adapte a qualquer ambiente e agrade a todos os gostos :) Medidas: 2,10m, 2,30m, 2,50m, 2,70m, 3,00m. Material: Suede Velut Cores: Azul, Bege, Cinza, Marrom, Preto, Tabaco e Vermelho. Caso você tenha interesse em visualizar os anúncios de alguma das opções acima, basta efetuar uma busca de acordo com as opções descritas. Introdução ao Produto Sabe aquela sensação de felicidade e satisfação que você sente quando faz uma boa escolha ?! Pois bem, essa é a sensação de comprar um sofá Zurique. Um produto moderno, com design elegante que combina com qualquer ambiente e o deixa ainda mais lindo e aconchegante. Ele possui encosto reclinável em cinco posições, proporcionando-lhe mais conforto na hora do descanso. Não para por aí: seu assento retrátil conta com espuma D33 e molas espirais, transformando seu sofá em uma verdadeira cama para assistir seu filme preferido. Não perca mais tempo e garanta já o seu sofá Zurique Características - Capacidade: 2,30m, (4 pessoas). - Quantidade de assentos:( 2 assentos). - Quantidade de módulos: ( 2 módulos). - Peso real suportado: 120kg por pessoa - Encosto reclinável de 5 posições - Almofadas do encosto em fibra siliconada - Assento retrátil com molas espirais e espuma D33 - Braço com espuma D28 - Estrutura em madeira de reflorestamento, eucalipto e pinus Dimensões (Produto montado) - Altura: 1,05m - Profundidade: 1,21m - Profundidade aberto: 1,75m - Largura: 2,30m Montagem A montagem do produto pode ser feita facilmente seguindo o manual de instruções que acompanha a embalagem do produto. Não é necessário técnico especializado. Garantia: 90 dias Informações Relevantes - Não nos responsabilizamos pela instalação e montagem - Antes de efetuar a compra, verifique cuidadosamente as dimensões do produto, certificando-se de que o mesmo poderá ser transportado por portas, corredores e elevadores, evitando inconvenientes durante a entrega - Não nos responsabilizamos pelo transporte por escadas, elevadores, guincho ou içamento do produto. Todas as despesas associadas a esses serviços são de responsabilidade do cliente. - Não nos responsabilizamos por entregas em zonas rurais, fazendas, vias não pavimentadas ou sem endereço bem identificado e mapeado por equipamentos GPS, mesmo que a zona rural esteja inscrita em região metropolitana. As entregas nessas localidades estão sujeitas a cobranças adicionais para execução com operação dedicada, mediante prévia negociação com o cliente. Não há um valor fixo determinado, pois a dificuldade excessiva e custos podem variar caso a caso - As imagens são meramente ilustrativas, podendo ocorrer variações de tonalidades nos tecidos devido às variações nas configurações de monitores ou telas. - Os objetos decorativos nas imagens não acompanham o produto. - Não realizamos trocas por outros modelos ou medidas diferentes. Certifique-se de escolher o produto correto conforme suas necessidades - Prestamos assistência técnica exclusivamente para defeitos de fabricação.', 2331.89, 2325.98, NULL, 'Home & Living > Furniture > Sofas', 'https://cf.shopee.com.br/file/sg-11134201-7rd3y-lwof9f41ex9b99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F874507048%2F23193094181', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698957766', 'Usado: Galaxy S23 128GB Violeta Excelente - Trocafy - Samsung', 'Celular Seminovo Trocafy A Trocafy é especializada na venda de celulares Recondicionados (Seminovos). Aqui todos os aparelhos passam por revisão minuciosa de técnicos especializados e certificados pelos fabricantes para reparo. Condições: Excelente: Aparelhos com pouquíssimos sinais de uso, risco e/ou arranhões quase imperceptíveis tanto na tela quanto tampa traseira; Muito Bom: Aparelho com alguns sinais de uso como arranhões, riscos e/ou amassados na lateral perceptíveis, porém leves, tanto na tela quanto tampa traseira; Bom: Aparelhos com sinais de uso nítidos/visíveis tanto na tela quanto na tampa traseira como por exemplo: riscos, arranhões, pequenos amassados e manchas na tela. Bom Bateria 70%:Aparelhos com sinais de uso nítidos/visíveis tanto na tela quanto na tampa traseira como por exemplo: riscos, arranhões, pequenos amassados e manchas na tela. Mínimo da bateria é 70%. IMPORTANTE: - Trabalhamos apenas com PEÇAS ORIGINAIS. Não utilizamos peças alternativas ou paralelas; - Aparelhos DESBLOQUEADOS para todas as operadoras e homologados pela ANATEL; - IMEI verificado garantindo originalidade e procedência legal do aparelho; - Por serem usados, os aparelhos não são resistentes a água (IP68/IP67); - Não acompanha acessórios; - NOTA FISCAL - Emitida em nome do comprador; GARANTIA - Aceita devoluções por arrependimento em até sete (7) dias corridos após o recebimento do pedido. Oferece 90 dias de garantia contra defeitos técnicos. CONTEÚDO EMBALAGEM: Aparelho adquirido em uma caixa personalizada da Trocafy;', 2029.0, 1927.55, NULL, 'Mobile & Gadgets > Mobile Phones', 'https://cf.shopee.com.br/file/sg-11134201-824h4-mfl95pfd0kcr3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1608031728%2F23698957766', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19699678613', 'Sandália Vizzano Feminina Salto Alto Conforto 6292-200', '✨ Sandália Vizzano Feminina Salto Alto Conforto – Elegância e Versatilidade para Qualquer Ocasião ✨ A Sandália Vizzano salto alto conforto combina sofisticação, modernidade e estabilidade, perfeita para quem quer estar bem vestida em festas, casamentos, formaturas, mas também para momentos casuais e do dia a dia. Seu design minimalista com tira frontal e fechamento por fivela 🪝 garante um visual elegante, enquanto o salto grosso proporciona segurança e conforto ao caminhar. 🌟 Destaques 👠 Design clean e elegante que combina com diversos looks 💪 Salto grosso que oferece mais firmeza e equilíbrio 🪝 Fechamento por fivela lateral ajustável ☁️ Palmilha macia e anatômica para conforto prolongado 🛡️ Solado antiderrapante para maior segurança 📌 Ficha Técnica Marca: Vizzano Material externo: Sintético Material interno: Forro têxtil Solado: Borracha antiderrapante Fechamento: Fivela lateral ajustável Numeração: 33 ao 40 Altura do salto: Aprox. 12 cm (Meia Pata 2,5cm ) Indicação: Festa, casamento, formatura, balada, casual e dia a dia 📏 Tabela de Tamanhos 33 - 21,5 cm 34 - 22,0 cm 35 - 23,0 cm 36 - 23,5 cm 37 - 24,5 cm 38 - 25,0 cm 39 - 26,0 cm 40 - 26,5 cm 🛒 Garanta já a sua Sandália Vizzano salto alto conforto e arrase em qualquer ocasião!', 159.9, 120.0, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md1td54rp5pue4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F324536294%2F19699678613', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
