INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12937005347', 'Farol Dianteiro e Traseiro Absolute JY-267-2B1', 'Farol Dianteiro e Traseiro Absolute JY-267-2B1 Garanta sua segurança e visibilidade com o Farol Dianteiro e Traseiro Absolute JY-267-2B1. Possui ótima luminosidade, proporciona uma grande visibilidade para que o ciclista possa pedalar nas mais variadas modalidades. Fabricados para maior resistência e com baterias de maior durabilidade, o farol traseiro auxiliam na segurança dos seus pedais de forma prática e muito funcional. Em conjunto o Farol da Absolute é resistente à água, permitindo que seus pedais em qualquer ambiente e clima sejam mais seguros. Especificações do Farol Dianteiro e Traseiro Absolute JY-267-2B1 - Farol com potência ideal para cidade e trajetos com pouca luminosidade; - Resistência à água - pedale mesmo sobre chuvas fortes com tranquilidade de visibilidade; - Iluminação com 3 fases; - Alimentação via bateria cr2032; - Composição: borracha silicone.', 17.4, 17.4, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/bc5e4ec379c476a498d4f7afea6411e7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F12937005347', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
