INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23396925325', 'Macacao Ciclismo Feminino Forro Gel Macacão Preto Way Fresh Roupa Bike Pedal Mtb', 'Conheça o Macaquinho de Ciclismo: DETALHES DO MACAQUINHO: -Forro em Gel com densidade D100 que Diminui as Dores no bumbum e em toda a região da pelve durante o pedal curto ou longo (até 10hrs); -Tecido mais leve que mantém seu corpo refrigerado e mais fresco mesmo nos dias mais quentes; -Desenhado para facilitar o movimento ajudando a melhorar o seu desempenho; -Ziper com Trava Inteligente que não corre risco de abrir sozinho e causar constrangimento. Sobre o forro: Pensado por mulheres que pedalam, o Forro Way Comfort Gel tem uma tecnologia exclusiva que utiliza-se de nobre Espuma com bidensidade e Gel localizado, proporcionando maior conforto e proteção no bumbum e em toda a região da pelve. TECIDO POLIÉSTER DE COMPRESSÃO NÃO FICA TRANSPARENTE! PROTEÇÃO UV 50+ INDICAÇÃO DE TAMANHOS: P- 36/38 M- 38/40 G- 40/22 GG- 42/44', 169.9, 79.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Sets', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh6a4tnjg6iv02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379576060%2F23396925325', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
