INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23692533576', 'Filtro Ar Cabine Kia Sorento 2010 a 2015 - 179340 - AKX1985', 'Filtro Ar Cabine Kia Sorento 2010 a 2015 179340 AKX1985 (S) - 2.4 16V Gasolina - Automático - (Sem carvão) Os filtros do ar para cabine são produzidos com fibras carregadas eletrostaticamente. Este filtros possuem camadas protegidas de um lado por um pré-filtro para reter partículas maiores. Do lado oposto possui uma camada de proteção a danos ao filtro.A função do meio filtrante é remover a maior quantidade possível de contaminantes do sistema do ar, oferecendo o mínimo de restrição ao fluxo de ar.', 28.46, 28.46, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-823qw-moyao2brm9e3aa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23692533576', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
