INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093508987', 'Bóia Tanque Sensor Nível Fiat Uno 1998 a 2004 - 511610 - 2374', 'Bóia Tanque Sensor Nível Fiat Uno 1998 a 2004 511610 2374 Motor 1.0 8v MPI/SPI O sensor de nível de combustível tem a função de medir a quantidade de combustível presente no tanque e informar a UCE (Unidade de Comando Eletrônico) que, por sua vez, controla a posição do marcador de nível no painel de instrumentos do veículo.', 123.24, 123.24, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rblz-lndc3jupbfb633', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23093508987', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
