INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997997995', 'Pastilha Freio Fiat Punto 2009 a 2023 - 1109018 - N540', 'Pastilha Freio Fiat Punto 2009 a 2023 1109018 N540 1.4/1.8 - DIANTEIRO - TEVES As pastilhas de freio são essenciais para a frenagem do automóvel, pois, são responsáveis por 70% desse trabalho. Elas fazem as rodas pararem, ao entrarem em contato com o disco de freio. É bom verificar a espessura das pastilhas a cada 5 mil quilômetros, mas recomenda-se determinar a periodicidade de troca adequada manual do veículo. Importante lembrar a substituição delas pode variar de acordo com o uso do veículo. A vida útil das pastilhas é de 25 a 35 mil quilômetros rodados, em média.', 103.66, 103.66, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd70-lxb56iqz818of8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20997997995', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297911321', 'Kit Cueiro Bebê Menina Incomfral Bercinho - 03 Peças 80cmX60cm', 'Kit Cueiro Incomfral Bercinho - 03 Peças O kit Cueiro incomfral linha é ideal para bebês de 0 á 12 meses. Com 03 peças no modelo flanelado estampado. O Cueiro é indispensável no enxoval, pois pode ser usada para forrar berço, carrinho, moisés e onde mais o bebê for deitar, além de possuir estampa fofa e manter o bebê quentinho. Informações Adicionais:Tamanho: Único Cores: Rosa Referência: 228008001 Dimensão aproximada: 60cm x 80 Marca: Incomfral', 29.7, 29.7, NULL, 'Mom & Baby > Nursery > Mattresses & Bedding', 'https://cf.shopee.com.br/file/sg-11134201-822ys-mhw2hefv6qrk96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F22297911321', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
