INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797845016', 'Chupeta New Baby Glitter Silicone Assimétrico Fase 1', 'Chupeta New Baby Glitter Silicone Assimétrico Fase 1 A Chupeta New Baby é uma escolha segura e confortável para bebês de 0 a 6 meses. Equipada com bico de silicone assimétrico e livre de BPA, essa chupeta combina estilo com conforto. O toque brilhante de glitter adiciona um charme adicional ao acessório. A chupeta é um acessório de conforto para bebês, oferecendo alívio através da sucção não nutritiva. Disponível em variados designs e materiais seguros, ela pode acalmar e tranquilizar os pequenos em momentos de necessidade. É importante escolher uma chupeta adequada para a idade e observar os hábitos do bebê. Informações Adicionais: Tamanho: Único Cores: Azul Referência: 113631 Marca: New Baby', 16.9, 16.9, NULL, 'Mom & Baby > Feeding Essentials > Pacifiers', 'https://cf.shopee.com.br/file/sg-11134201-7rdxm-m0lmnzhzzchw79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F22797845016', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
