INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593548411', 'O LIVRO DA LUA 2025', 'O LIVRO DA LUA 2025 Descubra a influência do astro no seu dia a dia e a previsão anual para seu SignoTem dias em que acordamos dispostos, com a fé renovada, a inteligência afiada e produzimos com uma insaciável energia e há dias em que desistimos de começar.O Efeito Lua faz com que tenhamos dias mágicos e outros, infernais. Alguns em que tudo dá certo, mas também aqueles em que temos a sensação que uma força misteriosa conspira secretamente para contrariar cada um de nossos atos.O Livro da Lua 2025 apresenta uma análise detalhada do astral de cada dia, já que grande parte de nossos acertos depende de um bom timing. Com este livro, você descobrirá quais são as oportunidades diárias para melhorar as chances de êxito em qualquer área da vida.Aqui, você encontrará Influências da Lua para cada dia do ano. Previsões dos Signos para 2025. O que os astros dizem a respeito do Brasil e do mundo em 2025.. Informações Adicionais Autor: MARCIA, MATTOS Data Publicação: 06/11/2024 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: O LIVRO DA LUA 2025 Idioma: INDEFINIDO Páginas: 400 Edição: 1 ISBN-13: 9786555665680 ISBN-10: 6555665688', 69.9, 69.9, NULL, 'Books & Magazines > Books > Horoscopes', 'https://cf.shopee.com.br/file/sg-11134201-7reqh-m2wgizgdyz2ec8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23593548411', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58213981912', 'KIT COM 2 PNEU ARO 14 175/70R14 84T POWERCONTACT 2 CONTINENTAL', 'O Pneu Continental PowerContact 2 175/70R14 84T foi desenvolvido para oferecer segurança, conforto e excelente desempenho no uso diário. Sua banda de rodagem conta com tecnologia que proporciona maior aderência em pisos secos e molhados, melhor estabilidade em curvas e frenagens mais eficientes. Além disso, apresenta baixa resistência ao rolamento, contribuindo para a economia de combustível, redução do desgaste e uma condução mais silenciosa e confortável. Com a qualidade reconhecida da Continental, é uma excelente escolha para quem busca durabilidade e confiabilidade.', 938.9, 938.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-8258t-mqgevqjtzf2m89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1703459619%2F58213981912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50259763343', 'Sandália Melissa Wave Sandal II AD Feminino Original', '***ENVIO IMEDIATO APÓS A CONFIRMAÇÃO DO PAGAMENTO*** SEJAM BEM VINDOS À KROKODILUS SURF! DESCRIÇÃO: A sandália Melissa combina design moderno, leveza e conforto para acompanhar sua rotina com muito estilo. Com linhas minimalistas e acabamento sofisticado, o modelo traz tiras largas em material flexível que proporcionam excelente ajuste aos pés e segurança ao caminhar. Seu formato versátil permite combinações com vestidos, saias, shorts, jeans e produções casuais para diversas ocasiões. A palmilha macia e o solado leve garantem conforto prolongado durante o uso no dia a dia. ESPECIFICAÇÕES: - Marca: Melissa; - Tipo: Sandália rasteira; - Material externo: Melflex / PVC exclusivo Melissa; - Fechamento: Fivela ajustável; - Solado: Leve e antiderrapante; - Estilo: Casual / Fashion / Moderno. TABELA DE TAMANHOS: 33/34 - 22cm 35 - 23cm 36 - 24cm 37 - 25cm 38 - 25,5cm 39/40 - 26cm', 199.9, 179.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/sg-11134201-820lm-mnoh26t4l5oh56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F324536294%2F50259763343', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
