INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19799713630', 'Sandália Rasteira Mormaii Bico Quadrado Rosa - Feminino', 'Conforto e praticidade para todos os seus passos! Sandália Rasteira Mormaii Bico Quadrado Rosa - Feminino Ficha Técnica: Marca: Mormaii Cor: Rosa Cabedal: PVC com aplicação em injeção no estilo salomé Gênero: Feminino Palmilha: PVC confortável Sola: Material expandido com leveza e flexibilidade Fechamento: Fivela Bico: Quadrado Indicação: Dias quentes e momentos de lazer Detalhes: Logo da marca em destaque aplicado no cabedal; pespontos nas tiras e palmilha A sandália rasteira Mormaii foi feita para quem valoriza conforto sem abrir mão de estilo. Com design moderno e estrutura leve, ela combina perfeitamente com a rotina dos dias mais quentes. Porque investir: Seu cabedal estilo salomé com aplicação em injeção destaca o logo da marca com charme, enquanto a sola em material expandido garante uma pisada suave. Ideal para acompanhar você nas mais diversas ocasiões, essa sandália é o equilíbrio entre praticidade e elegância Conteúdo da embalagem: 1 par de Sandália Rasteira Mormaii Bico Quadrado Rosa - Feminino', 39.99, 39.99, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/sg-11134201-7repd-m90bcpujfvkhfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F19799713630', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
