INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19897804459', 'Churrasqueira Elétrica Philco PCQ1500D', 'A Churrasqueira Elétrica Philco PCQ1500D tem poderoso antiaderente Maxx Gold, ele é durável, resistente e fácil de limpar, grelha os alimentos sem grudar. É ideal para ser utilizada dentro de casa, a gordura dos alimentos vai direto para a bandeja coletora, impedindo que entre em com contato com a superfície aquecida, evitando a fumaça. Saia do convencional, faça uma refeição diferente e mais saborosa com a PCQ1500D. Surpreenda a todos! Características: Grelha de alumínio com revestimento antiaderente dourado Revestimento antiaderente base água Alças laterais com toque a frio (Baquelite) 40 chapa Lisa e 60 Grelha Acompanha Bandeja de água/ Coletor de gordura Grelha removível Baixa emissão de fumaça Seletor de temperatura Termostato removível Pés antiderrapantes Base/Suporte de plástico Sistema de segurança: Só liga se estiver montado na base Formato da chapa60 grelha e 40 chapa lisa Potência (W): 1500W Dimensões: Altura: 7,7 cm Largura: 50 cm Profundidade: 34,5 cm Peso: 2,05 Kg Garantia do fornecedor de 12 meses.', 399.9, 359.9, NULL, 'Home & Living > Kitchenware > Grills & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rdw9-lzos8f6x4v7r70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F19897804459', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993217784', 'NUDGE COMO TOMAR MELHORES DECISÕES EDIÇÃO AMPLIADA E DEFINITIVA', 'NUDGE COMO TOMAR MELHORES DECISÕES EDIÇÃO AMPLIADA E DEFINITIVA Edição ampliada e definitiva de um dos maiores clássicos sobre tomada de decisão, escrito por Richard H. Thaler, ganhador do prêmio Nobel de economia, e Cass R. Sunstein, professor de Harvard. Best seller do New York Times Mais de 2 milhões de cópias vendidas Com base em décadas de pesquisas em ciência comportamental e usando diversos exemplos reveladores, os autores mostram que nenhuma opção nos é apresentada de forma neutra, e que estamos todos suscetíveis a tomar decisões ruins.Desde a primeira edição deste livro, a palavra nudge entrou para o vocabulário de executivos, formuladores de políticas públicas e consumidores. A inovadora discussão sobre como todos nós respondemos a determinados empurrões (nudges) na hora de tomar decisões relacionadas a saúde, vida pessoal ou dinheiro conquistou uma multidão de leitores.Os nudges estão em toda parte podem ser uma imagem, um formulário, uma disposição de produtos, listas brancas próximas na estrada. Trata se de qualquer aspecto que altera (ou empurra) o comportamento das pessoas em uma determinada direção, sem envolver alguma proibição, multa ou obrigação.Durante o isolamento social imposto pela covid 19, os autores decidiram revisitar o conceito e atualizar exemplos no campo da saúde, meio ambiente e finanças. Sem perder o tom leve e bem humorado, trazem ferramentas valiosas sobre tomada de decisão para indivíduos, empresas e governos.Poucos livros mudaram o mundo. Nudge é um deles – Daniel Kahneman, autor de Rápido e devagar. Informações Adicionais Autor: RICHARD H.; SUNSTEIN, CASS R. Data Publicação: 30/12/1899 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: NUDGE COMO TOMAR MELHORES DECISÕES EDIÇÃO AMPLIADA E DEFINITIVA Idioma: INDEFINIDO Páginas: 336 Edição: 2 ISBN-13: 9788539007431 ISBN-10: 8539007436', 78.68, 62.94, NULL, 'Books & Magazines > Books > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdvw-lz21wjgnz9k8ab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23993217784', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
