INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58212673476', 'Chinelo Infantil Ipanema Guerreiras do K-POP', 'O Chinelo de Dedo Infantil Guerreiras do K-POP Ipanema traz toda a estética vibrante da animação que virou fenômeno global. Inspirado no universo das Guerreiras do grupo Huntrix, o modelo destaca as personagens em uma palmilha colorida cheia de elementos gráficos que remetem ao show, à fantasia e à energia do K-pop. O cabedal em jelly com glitter adiciona brilho na medida certa, enquanto o enfeite central prateado e a estampa lateral da sola completam um visual moderno, divertido e cheio de atitude — perfeito para fãs da série. *Pedidos realizados atráves de CNPJ não serão faturados.', 39.99, 39.99, NULL, 'Baby & Kids Fashion > Girl Shoes > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-824hk-mpkvhshxznr47d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1012616199%2F58212673476', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998897128', 'Sandália Rasteira Feminina Adulta Grendha Envolver', 'A Rasteira Envolver Grendha chega para ampliar a consagrada linha anatômica, unindo design moderno e bem-estar em cada detalhe. As ondulações massageadoras e a taloneira em EVA garantem uma experiência de conforto ainda mais acolhedora. O destaque fica por conta da joia contemporânea em formato bold, que traz uma releitura sofisticada dos metais, conectando com delicadeza as tiras do modelo e revelando toda a essência elegante da Grendha.', 59.99, 59.99, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flat Sandals', 'https://cf.shopee.com.br/file/sg-11134201-824i8-mer5lv8p47ia04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1012616199%2F23998897128', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23700181011', 'FINISHER LP - MULTIUSO ALCALINO CANELINHA - GALAO 5 LITROS', 'Limpe superfícies encardidas e remova marcas de gordura com o Canelinha APC Flotador Multiuso Finisher 2L. Este limpador multifuncional concentrado conta com ação flotadora de alta tecnologia, ideal para desprender gorduras, óleos e sujeiras pesadas sem agredir o material. Perfeito para o interior e exterior do veículo, deixando um aroma agradável após a aplicação. Ação Flotadora Potente: Desprende a sujeira da superfície, facilitando a remoção em plásticos, carpetes e tecidos. Alta Versatilidade: Pode ser utilizado em borrifadores, tornadores, extratoras de estofados e equipamentos de espuma (snow foam). Fórmula Concentrada: Rende muito mais, permitindo diluições de até 1:50 conforme o nível da sujeira. Uso Seguro: Limpa profundamente mantendo a integridade das superfícies cuidadas. Modo de Uso Rápido: Diluição: Dilua uma parte do produto em até 50 partes de água, dependendo do grau de sujidade. Aplicação: Pulverize sobre a área. Se necessário, esfregue levemente com uma escova de cerdas macias ou pincel de detalhamento. Remoção: No motor ou exterior, enxágue com água. No interior (bancos e painéis), remova completamente o resíduo com uma flanela de microfibra úmida. (Nota: Evite borrifar diretamente sobre botões e componentes eletrônicos do veículo).', 112.49, 112.49, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Degreasers', 'https://cf.shopee.com.br/file/br-11134207-820ld-mol52awh9erp19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369458625%2F23700181011', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43403500408', '1x Mini Quebra-Cabeça de Madeira Sortido Disney Princesa Pais e Filhos Jogo Educacional Infantil', '*Produto Sortido e unitário, será enviado de acordo com a disponibilidade em estoque. Quebra-cabeça das princesas da disney, com a Rapunzel, Bela, Tiana, Ariel, Moana, Branca de Neve, Cinderela e Jasmine. Com um design inovador e cores vibrantes, este quebra cabeça proporciona a sensação de superação quando nossos pequenos conseguem montar. As crianças vão testar sua capacidade de concentração encaixando as pecinhas. Contém 10 peças. Imagens sortidas. Especificações: - Idade: +4 - Medida Unit.(cm): 8,6x3,5x4,0 - Composição: Papel cartão e Madeira (MDF) - Número de Peças do Mini Quebra-Cabeça: 10 peças Características: - Marca:PAIS E FILHOS - Modelo:811076-1 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01x Mini Quebra-Cabeça Disney Princesa Madeira (sortido)', 12.78, 11.71, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rav8-maonylvrel5cd9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F43403500408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
