INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209720205', 'Creme Para o Corpo Natura Tododia Manga Rosa e Água de Coco', 'Hidratação com efeito geladinho que refresca e acalma a pele.Sinta seu corpo com o novo creme sorbet desodorante nutritivo tododia manga rosa e água de coco. Uma combinação balanceada de ingredientes naturais com ação prebiótica, que alimenta e fortalece a flora da pele e efeito geladinho, que refresca e acalma a pele aliviando a sensação de calor. Para um toque ainda mais refrescante, coloque na geladeira e use em seguida. Este creme é indicado para todos os tipos de pele, pois se adapta às necessidades que cada uma tem. BENEFÍCIOS: Testado dermatologicamente Família olfativa: floral Fragrância: manga rosa e água de coco Tipo de pele: todos os tipos de pele Subfamília: frutal Textura: creme Zona de aplicação: Corpo', 78.9, 78.9, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-820l7-mnkhyz7qlqmdde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1785523344%2F58209720205', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
