INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9162846325', 'Barra Maciça Dúctil 40cm Anatômica com Presilhas Equilíbrio 40cm ( Unidade )', 'A Barra Dúctil da Equilíbrio, é uma barra maciça totalmente recoberta por material resistente a corrosão. Possui ganchos para prender anilhas. Ideal para treino de fortalecimento muscular. OBS.: Não acompanha anilhas. Diferenciais e Benefícios : Resistente: barra maciça totalmente recoberta por material dúctil, resistente a corrosão; Presilhas: emborrachadas que facilitam o manuseio. Indicações : Fortalecimento muscular. Conservação : A limpeza deve ser feita apenas com panos limpos levemente umedecidos com água e sabão neutro; Não deixar exposto ao sol ou chuva. Contraindicações : Todo exercício deve ser orientado por um profissional da área. Especificações Técnicas : Barra maciça totalmente recoberta; Resistente a corrosão; Conteúdo da Embalagem: 01 un. Barra Maciça Dúctil 40cm Anatômica com 02 Presilhas Equilíbrio Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 89.0, 89.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/4e021b1e197b309e50dc17b177ea0964', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F9162846325', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
