INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58212000423', 'Kit 20 Sachê Premier Gourmet Cães Adultos Pequeno Frango 85g', 'Kit 20 Sachê Premier Gourmet Cães Adultos Pequeno Frango 85g Combinando peito de frango e arroz integral, traz proteínas de alta digestibilidade, fibras que promovem saúde intestinal, antioxidantes que protegem, gorduras que cuidam da pele e pelos e energia balanceada para cães pequenos. A Ração Úmida Sachê PremieR Gourmet Peito de Frango e Arroz Integral para Cães Adultos de Raças Pequenas é nobre, nutritiva e natural, pois não contém corantes e aromatizantes artificiais, conservantes e nem ingredientes transgênicos. Feita com peito de frango e arroz integral, é rica em proteínas, contém um molho de sabor incomparável e tem a vantagem de conter baixas calorias, promovendo uma refeição deliciosa e naturalmente saudável. Seu pet vai amar! Composição básica: Água, carne de frango (peito de frango – 37%), arroz integral (1,5%), goma guar, acetato de DL-alfa-tocoferol, acetato de retinol, ácido ascórbico monofosfato, ácido fólico, ácido pantotênico, biotina, bissulfito de menadiona nicotinamida, cianocobalamina, cloreto de colina, colecalciferol, niacina (ácido nicotínico), piridoxina, riboflavina, tiamina, selenometionina hidroxi análoga. Contém: 20 unidades de 85g cada', 169.9, 157.94, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/sg-11134201-823op-mp3tonjmam1b08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F954075933%2F58212000423', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
