INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20497993825', 'RELOGIO TEMPERATURA CABO 2 METROS MB 1113 1313 1513 60MM 40 A 110 GRAUS', 'RELOGIO INDICADOR MARCADOR TEMPERATURA MOTOR MB MWM WILLTEC PRODUTO NOVO MARCA: WILLTEC CÓDIGO FABRICANTE: W01125P Descubra a excelência em peças e acessórios para veículos pesados na RIALAN LITORAL AUTO PEÇAS, a sua principal escolha para garantir qualidade e confiabilidade em cada compra. Com um vasto estoque de mais de 50 mil itens, nossa loja oferece uma extensa variedade de opções para atender às necessidades específicas do seu caminhão. Na RIALAN LITORAL AUTO PEÇAS, comprometemo-nos em fornecer produtos de alta qualidade, garantindo a segurança e a eficiência do seu veículo pesado. Nossa equipe especializada está pronta para ajudar a encontrar as peças certas, oferecendo conhecimento técnico e atendimento personalizado. Além disso, destacamos nossa dedicação à satisfação do cliente, proporcionando uma experiência de compra fácil e transparente. Entendemos a importância de manter seu caminhão em ótimo estado de funcionamento, e é por isso que nos esforçamos para ser a sua escolha número um quando se trata de peças e acessórios automotivos. Não comprometa a performance do seu veículo pesado. Escolha a RIALAN LITORAL AUTO PEÇAS e experimente a diferença que a qualidade faz. Seja para manutenção preventiva ou reparos emergenciais, estamos aqui para oferecer soluções confiáveis e duradouras. Sua satisfação é a nossa prioridade.', 208.0, 208.0, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9osx61r9iyh5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1408271217%2F20497993825', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8938981380', 'Lampada Led P21w 2 Polos 5w 6000k 45 SMD Leds 12v', 'Lâmpada Automotiva 1034 2 Polos - Iluminação LED de Alta Performance para seu Veículo Ilumine seu caminho com a Lâmpada 1034 2 Polos da ASX, a escolha perfeita para quem busca alta performance, segurança e estilo em iluminação automotiva! Tecnologia e Eficiência: 45 LEDs SMD de alta qualidade: Proporcionam iluminação intensa e uniforme, garantindo excelente visibilidade em qualquer condição de condução. 6000K Branco Frio: Emite uma luz branca brilhante que melhora a visualização de placas, sinalizações e obstáculos, aumentando a segurança na estrada. 900 Lumens: Potência luminosa ideal para uma iluminação eficiente sem causar ofuscamento. Tecnologia CANBUS: Elimina erros no painel do veículo, garantindo compatibilidade com diversos modelos. Versatilidade para uso em carros, motos e caminhões. Durabilidade e Economia: 50.000 horas de vida útil: Longa durabilidade, reduzindo a necessidade de substituições frequentes. 5W de potência: Baixo consumo de energia, contribuindo para a economia de combustível. Corrente de 0.23A: Eficiência energética otimizada. Design e Praticidade: Encaixe P21 BAY15D: Fácil instalação e compatibilidade com diversos modelos de veículos. 2 Polos: Conexão segura e confiável. Marca ASX: Qualidade e confiabilidade em iluminação automotiva. Especificações Técnicas: Modelo: 1034 2 Polos LEDs: 45 SMD Cor: Branco Frio (6000K) Lúmens: 900 Voltagem: 12V Potência: 5W Corrente: 0.23A Encaixe: P21 BAY15D Vida Útil: 50.000 horas Marca: ASX Conteúdo da Embalagem: 2 Lâmpada 1034 2 Polos ASX Observações: Verifique a compatibilidade com o modelo do seu veículo antes da compra. A instalação da lâmpada deve ser realizada por um profissional qualificado.', 64.99, 64.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md3z07fv6arl33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F388765779%2F8938981380', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22597687691', 'Chá Leão Amora, Mirtilo e Baunilha 2 Caixas Com 10 Sachês.', 'Garanta o seu momento diário de relaxamento com o Kit de 2 Caixas de Chá Leão Amora, Mirtilo e Baunilha. Esta combinação exclusiva une a leveza da amora com o aroma envolvente do mirtilo e a doçura suave da baunilha, proporcionando uma infusão delicada, equilibrada e muito reconfortante. Perfeito para acalmar a mente antes de dormir ou para fazer uma pausa relaxante no meio do dia. Ficha Técnica: Marca: Leão Alimentos (Linha Frutas e Flores) Sabor: Amora, Mirtilo e Baunilha Conteúdo do Kit: 2 caixas com 10 sachês cada (Total: 20 sachês individuais) Peso Líquido: 16g por caixa (Total: 32g) Modo de Preparo: Ferva 200 ml de água. Coloque 1 sachê na sua xícara favorita. Despeje a água quente e deixe em infusão de 5 a 7 minutos.', 32.9, 32.9, NULL, 'Food & Beverages > Beverages > Tea & Tea Bags', 'https://cf.shopee.com.br/file/br-11134207-820lz-mqqn71uvaio358', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F520921300%2F22597687691', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
