INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252924479', 'Caneca Mini Tina Mickey Mouse - Disney', 'Depois de um dia cheio de aventuras e novas descobertas, você precisa de uma mãozinha para a hora daquele cafezinho? Com 100ml de capacidade, vai ser a melhor companhia possível para as idas ao salão principal! Não importa se é chá ou café, essa caneca te acompanha em todas as suas aventuras! A caneca é importada, possui detalhes incríveis que vão fazer você se apaixonar! Com 100ml de capacidade, é a companhia perfeita para quem ama a hora do café da tarde! Feita em cerâmica, com uma base empilhável perfeita que te ajuda na hora de organizar as suas minis tinas! Não importa se o cafezinho é na cafeteria ou não, essa caneca te acompanha em todas as suas aventuras! Especificações: Altura: 5,5cm| Largura: 5cm| Comprimento: 5cm| Material: Cerâmica| Capacidade: 100ml Cuidados e recomendações de uso: Lavar com água, esponja macia e detergente neutro. Não vai ao micro-ondas, nem a lava-louças. Não utilizar químicos e abrasivos. Choques ou quedas podem trincar ou quebrar o produto, pois trata-se de um produto de Cerâmica', 29.9, 29.9, NULL, 'Home & Living > Dinnerware > Tea Pots & Sets', 'https://cf.shopee.com.br/file/sg-11134201-82582-mqnpo10b00zm52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F58252924479', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22424975672', 'Kit 2 Areias Higiênica Biodegradável Limpeza Plena Viva verde', 'Kit 2 Areias Higiênica Biodegradável Limpeza Plena Viva verde. - Indicado para gatos; - Areia biodegradável; - Eliminação imediata e duradoura do odor da urina; - Torrões em cor clara; - Forma torrão sólido instantâneo; - Pode ser descartado em vaso sanitário; - Areia com melhor rendimento. Areia Higiênica Limpeza Plena Viva Verde! é a mais nova inovação da PetFive. Areia Limpeza Plena é ideal para eliminar o odor desagradável do xixi dos gatinhos, mantém a casa sempre cheirosa. A Viva Verde! Limpeza Plena elimina o odor da urina instantaneamente, já que sua formulação absorve a umidade de forma ainda mais rápida. É ideal para lares com mais de um gatinho. Usamos apenas matérias-primas de origem vegetal e de fontes renováveis (milho e mandioca). Modo de usar 1- Coloque uma camada de pelo menos 5cm de Viva Verde! Areia Higiênica em uma caixa alta. 2- Para limpar, remova os torrões e as fezes diariamente. 3- Os torrões podem ser descartados no vaso sanitário - basta aguardar que eles dissolvam na água antes de dar descarga. 4- Reponha a areia para manter a altura de pelo menos 5cm.', 145.9, 145.9, NULL, 'Pets > Litter & Toilet > Cat Litter & Boxes', 'https://cf.shopee.com.br/file/sg-11134201-7rceu-lrssimpinlm061', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F645931940%2F22424975672', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
