INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254361207', 'Vichy Normaderm - Gel de Limpeza Facial 300g', 'Gel de limpeza profunda para peles oleosas ou acneicas.O Gel de Limpeza Profunda Normaderm da Vichy é a solução para peles oleosas e acneicas. Desenvolvido por especialistas, ele oferece uma limpeza eficaz que desobstrui os poros e controla a oleosidade, convidando você a sentir sua pele renovada e purificada todos os dias. Diga adeus à oleosidade excessiva e aos poros obstruídos. O Gel de Limpeza Profunda Normaderm foi formulado especificamente para combater as imperfeições da pele oleosa e/ou acneica. Sua tecnologia combina a eficácia esfoliante do Ácido Salicílico e do Ácido Glicólico com a ação calmante da Água Termal Mineralizante de Vichy. Os principais benefícios incluem a redução do brilho, a desobstrução profunda dos poros e a eliminação de impurezas sem agredir a pele. O resultado é uma pele visivelmente mais limpa, fresca e suave ao toque, com uma sensação de conforto duradouro e a oleosidade sob controle. Benefícios do Gel de Limpeza Profunda Normaderm: ▸Gel de limpeza profunda de 300g que remove impurezas e controla a oleosidade excessiva da pele com eficácia.▸Enriquecido com Ácidos Salicílico e Glicólico, desobstrui os poros e renova a pele sem causar agressões.▸Sua ação de limpeza profunda deixa a pele imediatamente mais fresca, suave e com uma sensação de pureza.▸Controla o brilho e a oleosidade ao longo do dia, mantendo a pele com um aspecto matificado e saudável.▸Conquiste uma pele livre de impurezas e oleosidade, com poros desobstruídos e uma textura visivelmente melhorada. Ingredientes principais: Ácido Salicílico, Ácido Glicólico e Água Termal Mineralizante de Vichy. Adicione o Gel de Limpeza Profunda Normaderm de Vichy à sua rotina e sinta a transformação de uma pele limpa e sem oleosidade. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 121.9, 121.9, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/sg-11134201-8260l-mk4001gqws1ybe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58254361207', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
