INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50007180448', 'Escorredor De Louça Com Porta Talheres E Saída De Água Liv Bege Ou', 'Escorredor de Louças com Direcionador de Água Linha Liv – Organização e Praticidade para sua Cozinha O Escorredor de Louças Linha Liv foi desenvolvido para deixar a rotina da cozinha mais prática, organizada e higiênica. Com capacidade para até 12 pratos, ele também conta com espaço para copos, jarras e diferentes tipos de louça, mantendo tudo bem distribuído e seguro durante a secagem. Seu direcionador de água ajustável conduz a água diretamente para a cuba da pia, evitando acúmulo na bancada e mantendo o ambiente sempre limpo e seco. O escorredor de talheres modular pode ser posicionado conforme a necessidade e possui fundo removível, facilitando a higienização e trazendo mais praticidade para o dia a dia. Com design minimalista bicolor, cantos arredondados e estética contemporânea, ele combina perfeitamente com diferentes estilos de cozinha, unindo funcionalidade e elegância. Destaques do Produto: Capacidade para até 12 pratos Espaço para copos, jarras e louças diversas Direcionador de água ajustável que drena direto para a cuba Escorredor de talheres modular com fundo removível Design moderno bicolor com cantos arredondados Estrutura resistente e ideal para o uso diário Informações Técnicas: Altura: 9,5 cm Largura: 33,5 cm Comprimento: 43,5 cm Peso: 0,88 kg Material: PP + Aço Linha: Liv Cuidados: Higienizar com sabão neutro e esponja macia Evitar produtos abrasivos na limpeza Conteúdo da Embalagem: 1 Escorredor de Louças com Direcionador de Água Linha Liv', 189.99, 189.99, NULL, 'Home & Living > Kitchenware > Kitchen Racks', 'https://cf.shopee.com.br/file/br-11134201-820lz-mqyf06v7smis09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F775496126%2F50007180448', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15084314011', 'CAPACETE FECHADO EBF 7 MODELO SOLID PRETO FOSCO + VISEIRA FUME', 'CAPACETE MODELO EBF 7 + VISEIRA FUME ORIGINAL Principais características: - Viseira transparente em policarbonato, com proteção anti-risco; - Capacete com faixas refletivas, para maior segurança; - Casco aerodinâmico em resina termoplástica; - Cinta jugular com engate micrométrico; - Testado e aprovado pelo INMETRO; - Sistema de troca rápida da viseira; - Peso aproximado: 1300 gramas; - Viseira cristal de 2 milímetros; - Entradas e saídas de ar; - Produto 100% nacional; - Forração anti-alérgica; - Fabricante: EBF Capacetes;', 183.9, 183.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/33e0ebb0d78326aa854322a47f79f736', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F509931028%2F15084314011', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57009329149', 'Bolsa Feminina Pequena Flap Monograma BG Marrom', 'Bolsa Feminina Pequena Flap Monograma BG Marrom A Bolsa Feminina Pequena Flap Monograma BG Marrom é a escolha ideal para quem busca um acessório elegante, versátil e atemporal para o dia a dia. Com design sofisticado e acabamento refinado, essa bolsa feminina bege se destaca pelo visual com estampa monograma, que transmite modernidade e identidade ao look. Seu formato estruturado oferece praticidade na organização dos itens essenciais, enquanto a alça transversal ajustável proporciona mais conforto e liberdade para diferentes ocasiões. Perfeita para compor produções casuais ou mais arrumadas, a Bolsa Feminina Monograma BG Bege combina facilmente com diversos estilos e se torna uma excelente opção para quem valoriza beleza e funcionalidade em uma só peça. Aposte na Bolsa Feminina Monograma BG Bege para adicionar charme, praticidade e sofisticação à sua rotina. Amplo espaço interno: Amplo compartimento Interno A mochila conta com divisórias simples, ideais para manter seus itens organizados. Além disso, ela possui amplo espaço interno. Especicações: Marca: Bagaggio Atributos: Alça Removível Gênero: Feminino Faixa Etária: Adulto Material: PVC Marca: Bagaggio Capacidade (L): 4,7 L Peso (kg): 0,425 Kg Garantia: 90 Dias', 199.9, 149.9, NULL, 'Women Bags > Crossbody & Shoulder Bags', 'https://cf.shopee.com.br/file/sg-11134201-820n0-mnagjfr93coy3b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1462563752%2F57009329149', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
