INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693816251', 'Perfume Body Splash Meu Banho Premium Labpop Labotrat 190ml', 'Oii, é um prazer ter você aqui! Pronta para brilhar e conquistar? O Body Splash Labpop Labotrat 190ml é o segredo para você deixar sua marca com um toque de glamour, frescor e suavidade. Mais do que uma fragrância, é uma experiência que te envolve e ilumina! Atenção: Antes de finalizar a sua compra, verifique qual foi o aroma escolhido, para que assim, evite transtornos futuros. O que ele é: - 1 Body Splash Glitter com 190ml. - Marca: Labotrat. - Linha: Meu Banho Premium. - Não testado em animais. O que ele tem: - Alta fixação. - Efeito Shimmer. - Ativos Hidratantes. - Fragrância Marcante. O que ele faz: - Sensação de bem-estar. - Proporciona pele macia e perfumada. - Alta fixação. - Auxilia na hidratação. - Melhora a elasticidade da pele. - Realça a pele com um brilho sutil. Onde usar: - Pescoço. - Punhos. - Dobras dos cotovelos. - Atrás das orelhas. Como usar: - Aplicação: Borrife o body splash em áreas como o pescoço, pulsos ou até mesmo sobre a roupa para um aroma sutil e duradouro. Precauções de uso - Evitar contato com olhos e mucosas. Caso isso ocorra, enxaguar abundantemente com água. - Não utilizar sobre a pele irritada ou lesionada. Em caso de irritação, suspender o uso e procurar orientação médica. - Não ingerir. Relembre o que torna o Body Splash tão especial: frescor, brilho e uma fragrância inesquecível. Garanta já o seu e adicione um toque de glamour ao seu dia a dia! Surgiu alguma dúvida? Entre em contato com a gente! Boas Compras :)', 58.9, 53.52, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-7rd6j-m7b7w0bn3ilr34', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371678536%2F23693816251', NULL, NULL, '2026-07-28T02:1