INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41927759039', 'Kit 4 Peças de Conjunto Cropped Bebê Menina Moda Praia Verão Roupa para Bebê Feminina de Calor', 'Conjunto Verão Menina Cropped e Shorts – Estilo, Frescor e Alegria KIT 4 PEÇAS: Receba 2 Conjuntos - 2 Blusas + 2 Shorts O Conjunto Verão Menina Cropped e Shorts foi criado para deixar a rotina mais leve, colorida e confortável. Produzido em suplex de alta qualidade, ele proporciona toque macio, excelente caimento e uma estampa fofas que trazem todo o charme e delicadeza que as pequenas adoram. Benefícios e Funcionalidades O cropped estampado entrega leveza e sofisticação, enquanto o short com cadarço decorativo acrescenta um toque moderno ao visual. Com tecido leve e respirável, o conjunto é perfeito para os dias quentes, oferecendo conforto o dia inteiro. Suplex leve, macio e confortável Estampa vibrante e durável Short com cadarço que completa o look com estilo Look pronto em segundos, combinando perfeitamente Aplicações e Uso Indicado para passeios, viagens, brincadeiras ao ar livre, praia e dias de verão. Perfeito para meninas de 1 a 9 anos que gostam de conforto e estilo em todas as ocasiões. Garanta já esse kit de conjunto encantador e deixe o verão da sua pequena ainda mais especial!', 65.0, 45.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Sets', 'https://cf.shopee.com.br/file/br-11134207-820md-mr4jbr389b0l45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341167297%2F41927759039', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
