INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18796932998', 'Chave Punho Partida Emergência Xtz 125 E 2003 2004 2005 2006 2007 2008 2009 2010 2011 2012 a 2016', 'Aplicação da Chave Punho Partida e Emergência: Compatível com: Motos Yamaha: Xtz125 E 2003 a 2016 Obs: Considerar o ano modelo de sua moto. Exemplo: ano fabricação 2009 / ano modelo 2010 - Equivale ao ano 2010. Especificações técnicas: Código do fabricante: 3MTB100347 Código Original: 5RM-H3975-00 A Marca: A Zouil Moto Parts desenvolve peças de reposição para motos, com rigoroso controle de qualidade, linha de produtos complexa em sistema de ignição e energia, sendo uma excelente opção em peças para reposição. Prazo de Garantia: 3 meses para defeitos de fabricação. Importante: - Para a instalação correta do produto, leve ao mecânico de sua confiança! - Não nos responsabilizamos pelo uso indevido do produto ou vícios de instalação.', 67.64, 67.64, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7qvd5-lgmqmqkonugn2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369066095%2F18796932998', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
