INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8638405266', 'Filtro De Ar Sentra 2013 Em Diante March 2016 AL4032', 'filtro de ar sentra 2013 em.dianre e filtro de ar match 2016 em diante Filtro de ar de motor Sujeira pode comprometer a força do motor ao alterar a queima do combustível O filtro de ar impede que as impurezas existentes na atmosfera entrem e fiquem incrustadas dentro do motor. Essa sujeira pode comprometer a sua força, danificar seus componentes e piorar o consumo. Quanto mais limpo for o conteúdo aspirado, mais eficiente será a queima de combustível. Qual a função do filtro de ar do motor? O filtro de ar serve para evitar que as partículas de impureza do ar cheguem à câmara de combustão do motor. Com ele em dia reduz-se o desgaste em componentes como pistões e bielas, além de reduzir o consumo de combustível.', 49.99, 49.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-820lu-mozhq6ipgp37b4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414229824%2F8638405266', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
