INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19898992963', '4 Cristalizadores de Vidros ON-148 100ml Original Onyx Plus', 'Este anúncio contém: 1 (um) Cristalizador de vidros ON-148 original da marca Onyx. Código do Fabricante: ON-148; Código Universal: 7898927473488. O Cristalizador de Vidros Onyx foi desenvolvido especialmente para reduzir o ofuscamento sob chuva, lubrificar as palhetas e facilitar o escoamento de água. Modo de uso: 1 - Aplique no parabrisa seco, com um pano em movimentos circulares; 2 - Aguarde de 1 a 2 minutos e reaplique; 3 - Retire o excesso com outro pano limpo e seco. Evite contato com a lataria do veículo. Dúvidas frequentes: 1 - Trabalhamos apenas com produtos novos, e com garantia; 2 - Produto a pronta entrega; 3 - Seus produtos serão enviados em até 24 horas úteis após a confirmação do pagamento. Sobre a empresa: Somos uma Auto Peças fundada em 1980, atuamos no mercado varejista de peças e acessórios, tendo como principais clientes oficinas mecânicas e consumidor final. Não achou o que procura? Ficou com alguma dúvida sobre o produto? Fale conosco através do campo de perguntas.', 63.38, 59.58, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98r-lmdbj5gt0my3b5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F519603839%2F19898992963', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194330662', 'Máscara Intense One Curls C.Kamura Nutrição Intensa 250g', 'Máscara Nutrição Intense One Curls C.Kamura 250g Tratamento nutritivo desenvolvido especialmente para cabelos cacheados e ondulados. Hidrata profundamente, melhora a definição, reduz o frizz e devolve a elasticidade natural dos fios, mantendo os cachos macios, soltos e com movimento. Modo de Usar Com os cabelos limpos e úmidos, aplique a máscara do comprimento às pontas. Massageie mecha a mecha e deixe agir por 5 a 10 minutos. Enxágue completamente. Use semanalmente ou conforme a necessidade dos seus cachos. Resultado Cachos nutridos, definidos e com brilho, livres do ressecamento e com toque suave. Conheça a Marca C.Kamura é a marca profissional criada pelo renomado hairstylist Celso Kamura. Com tecnologia de ponta e alta performance, seus produtos entregam resultados de salão no cuidado diário dos cabelos.', 69.99, 59.49, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rdxy-mdb4yg24knymc9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1577811878%2F22194330662', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798903243', 'Cola Quente Pistola Para Artesanato Enfeite Decorar Bestfer', 'DISTRIBUÍDO POR CJAU FERRAMENTAS PISTOLA DE COLA QUENTE 6W BFH0003 BIVOLT BESTFER Para derretimento de bastões de adesivo termoplástico. Recomendado para utilização em artesanato, reparos rápidos, madeira e materiais diversos. - Aguarde aproximadamente 5 minutos, após conectar na tomada, para que a resistência interna derreta a cola. - Não toque no bico aplicador, nem na cola derretida, pois estará extremamente quente. - Mantenha afastado de crianças, isto não é um brinquedo. - Quando não em uso retire da tomada. - Potência: 6W - Tensão de funcionamento: 127 / 220 V, bivolt automático. - Cabo 80cm - Tamanho 10,5cm X 11 cm - Suporte de metal Na loja C-JAÚ, você encontra sempre as melhores ferramentas e acessórios para elevar o padrão do seu trabalho, com qualidade, tecnologia e confiança. E o melhor: tudo isso com atendimento especializado e envio rápido para todo o Brasil. Aproveite!', 34.0, 34.0, NULL, 'Stationery > School & Office Equipment > Glues', 'https://cf.shopee.com.br/file/br-11134207-81z1k-merk48q6qt4z94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380456261%2F23798903243', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498544477', 'Pneu Pirelli Rally Cross 24x1.95 - Arame', 'O Pneu Pirelli Rally Cross 24x1.95 foi desenvolvido para oferecer estilo e durabilidade, possui desenhos mais arrojados e estrutura mais reforçada e também muito mais duradoura. A Pirelli lança a linha premium de pneus de bicicleta, que foi desenvolvida especialmente para todos os segmentos disponíveis no mercado brasileiro. Os novos produtos contam com a mais avançada tecnologia em termos de compostos e processo produtivo que, alinhada à tradição da marca Pirelli, culmina em um pneu que acompanha o desempenho das bicicletas mais sofisticadas do mercado nacional. Especificações do Pneu Pirelli Rally Cross 24x1.95 Modelo: Rally 50-507 Medida: 24x1.95 *** A T E N Ç Ã O *** ANTES DE COMPRAR NÃO SE ESQUEÇA: - Tire todas as duvidas - Verifique se seu cadastro está atualizado no site (Endereço, CPF e Telefone) PRODUTOS NOVOS E DE BOA QUALIDADE COM GARANTIA DE FABRICA DE 3 MESES **Acompanha Somente um Pneu** ***PRODUTO A PRONTA ENTREGA*** *Imagens Meramente Ilustrativas Aguardamos seu pedido!!! OGM BIKE', 53.96, 53.96, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rauy-ma50q353ef2ndd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F22498544477', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
