INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12658368793', 'Comentário Bíblico Vida Nova Capa Dura - D. A. Carson', 'Este comentário bíblico segue a mesma linha e tradição do Novo Comentário da Bíblia, obra publicada por Edições Vida Nova e reimpressa por mais de 40 anos. Trata-se de uma obra completa e atualizada, escrita a partir de uma perspectiva conservadora.É ferramenta indispensável para quem quer estudar as Escrituras, pois faz uma exposição sólida, clara e concisa de todos os livros da Bíblia em um só volume. Entre seus organizadores, o CBVN conta com acadêmicos de renome como D. A. Carson, R. T. France, J. A. Motyer e G. J. Wenham.Páginas 2176', 267.99, 267.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/7040d882d94669f0c610631bd72130d2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F12658368793', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
