INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203986030', 'Óleo Câmbio Manual 75w85 Sintetico Petronas Tutela Geartech API GL-4', 'Óleo de Transmissão Manual Petronas Tutela 75W85 Sintético – 1 Litro O Petronas Tutela 75W85 Sintético é um óleo de transmissão totalmente sintético, desenvolvido para atender transmissões modernas que exigem alta eficiência, proteção superior e menor perda por atrito. Sua formulação avançada proporciona excelente fluidez a frio, alta estabilidade térmica e proteção contra desgaste, garantindo trocas de marcha suaves, redução de ruídos e maior durabilidade dos componentes da transmissão. Principais Benefícios Óleo de transmissão 100% sintético Excelente proteção contra desgaste e oxidação Alta estabilidade térmica em condições severas Ótima fluidez em baixas temperaturas Contribui para trocas de marcha mais suaves Ajuda a prolongar a vida útil do câmbio Aplicações: Indicado para caixas de câmbio manuais e transmissões que exigem lubrificante SAE 75W85, conforme especificação do fabricante do veículo. Sempre consulte o manual do veículo para confirmar a viscosidade correta. Especificações Técnicas Viscosidade: SAE 75W85 Tipo: Sintético Conteúdo: 1 litro Marca: Petronas Linha: Tutela Aprovado: FIAT 9.55550 Conteúdo da Embalagem 01 Óleo de Transmissão Petronas Tutela 75W85 Sintético – 1L Garantia e Procedência Produto novo e original Enviado com nota fiscal .', 170.42, 170.42, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-8262z-mjvbjenbqcche7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F552700125%2F58203986030', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
