INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693485494', 'Gabinete Gamer Aquário Mancer CV100, Mid-Tower, Lateral De Vidro, Branco, MCR-CV100-WH', 'GABINETE GAMER MANCER CV100 BRANCO Prepare-se para as suas maiores batalhas com a chegada do Gabinete Gamer Mancer CV100! Criado com materiais reforçados de metal e vidro temperado, o CV100 é equipado com filtro de poeira magnético e USB 3.0, sendo o upgrade perfeito para o seu setup! A Linha Clear Vision ostenta um design que visa deixar todo seu setup visível e de forma clara. O CV100 é equipado com lateral e frontal de vidro temperado, além de lateral de metal vazada para uma perfeita circulação de ar no gabinete. ícone de espaço interno Monte sua máquina com espaço de sobra! O Mancer CV100 possui um ótimo espaço interno, contando com suporte para placas mãe no formato M-ITX e M-ATX, comporta placas de vídeo de até 320mm de comprimento e até 1x HDD 3.5” / 2x SSD 2.5” instalados. ícone de material Construído com materiais de qualidade, o CV100 possui suporte para até sete ventoinhas de 120mm instaladas, sendo sua estrutura feita de aço SPCC de 0.5mm e vidro temperado de 3mm de espessura. O Mancer CV100 tem uma durabilidade impar e se tornará seu maior companheiro de aventuras. Marca: Mancer Modelo: MCR-CV100-WH Formato: Mid-Tower Material: SPCC 0.5mm + Vidro Temperado 3mm Placa mãe suportada: M-ITX, M-ATX Baias: 1 x HDD + 2 x SSD Slots de expansão: 4 Entradas: - 1 x USB 3.0 - 2 x USB 2.0 - 1 x Áudio HD Ventoinhas suportadas: - Lateral: 2 x 120mm - Traseira: 1 x 120mm - Superior: 2 x 120mm - Inferior: 2 x 120mm Water cooler suportado: - Traseira: 120 mm - Superior: 240 mm Altura máxima do cooler do processador: 160 mm Comprimento máximo da placa de vídeo: 320 mm Radiador frontal + ventoinha (espessura): 125 mm Radiador superior + ventoinha (espessura): 125 mm Radiador traseiro + ventoinha (espessura): 125 mm Conteúdo da Embalagem: - Gabinete Gamer Mancer CV100 - Guia de Instalação - Kit de parafusos para instalação Dimensões: - Largura: 270 mm - Altura: 350 mm - Comprimento: 350 mm Sobre a Pichau Informática Com mais de 18 anos de atuação no mercado nacional de tecnologia, a Pichau se destaca por seu compromisso com a inovação, qualidade e a satisfação do cliente. Referência em performance e confiabilidade, a empresa segue evoluindo para entregar produtos de excelência em diversas áreas, incluindo o esporte.', 499.99, 159.43, NULL, 'Computers & Accessories > Desktop & Laptop Components > PC Cases', 'https://cf.shopee.com.br/file/sg-11134201-7ren7-m1r1f2ee4q8930', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F627750190%2F23693485494', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8133902843', 'Kit Som Carro Radio Mp3 Usb Bluetooth + Falantes Hurricane 6 e 6x9 Polegadas', 'Kit Alto Falantes Quadriaxial Hurricane 6 e 6x9 Polegadas 280W RMS 4 Ohms Bobina Simples Preto e Azul: Chega de sofrer com chiado dos falantes do seu carro, adquira esse Kit Alto falantes fabricado pela Hurricane e dê um fim nesse problema! Esse kit é prático, pois vem com dois alto falantes de 6 polegadas e dois 6x9. Perfeito para ser instalado nas portas e no tampão do seu possante, esse kit dará conta de reproduzir as suas músicas com total nitidez e qualidade devido a sua potência total de 310W RMS e resposta de frequência de 80Hz a 22Khz. Especificações Técnicas: - Modelo: Kit Prático - Diâmetro Nominal: 6 e 6x9 Polegadas - Potência RMS: 280W RMS - Impedância Nominal: 4 Ohms - Modelo Quadriaxial - Resposta de Frequência: 80Hz a 22Khz - Sensibilidade: 89/90dB - Na Cor Preta com Azul - Bobina Simples - Cone Injetado em Polipropileno - Borda em Borracha Surround - Tweeters Piezo - Diafragma de Mylar - Carcaça Injetada - Fácil Instalação - Acompanha Grade de Acabamento - Dimensões Aproximadas AF 6” (DxA): 16,5x4,5cm - Dimensões Aproximadas AF 6x9” (CxAxP): 23,5x16,5x9,5cm Conteúdo da Embalagem: - 02 Alto Falantes 6 Polegadas - 02 Alto Falantes 6x9 Polegadas - 02 Grades de Acabamento ------------------------------------------------------------------------------------------------- MP3 Player Automotivo Rádio FM USB SD Entrada Auxiliar BLUETOOTH. Tela Led Painel Frontal 4 saídas de autofalante Função de relógio real Sintonização de rádio eletrônica Suporte para USB/ SD/ abertura para cartão MMc Compatível com formato de música MP3 Com Bluetooth Itens Inclusos 1 Radio Bluetooth MP3', 337.13, 306.11, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > GPS Navigators', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lrhg1kr5v0orb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F8133902843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
