INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210150387', 'Coqueiro Sardinha com Óleo', 'A Sardinha Coqueiro é uma ótima opção para incluir mais peixe na sua alimentação, de forma prática e deliciosa. Fonte de proteína, ômega 3 e vitamina D, tudo pronto para comer e sem conservantes. Combina com diversos pratos, como macarrão, cuscuz, lanches e saladas.', 7.49, 7.49, NULL, 'Food & Beverages > Food Staples > Dried Goods', 'https://cf.shopee.com.br/file/sg-11134201-82616-mj72nvxbfuo6c7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554792%2F58210150387', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253120923', 'TRUSS Frizz Zero - Tratamento Condicionante 30ml', 'Tratamento condicionante para todos os tipos de cabelos. TRUSS Frizz Zero pode ser usado como pré-shampoo ou máscara líquida. O Tratamento Condicionante TRUSS Frizz Zero é a solução definitiva para quem busca um cabelo livre dos arrepiados e com um alinhamento impecável. Sua fórmula ultraconcentrada, de fácil absorção, age profundamente nos fios, proporcionando hidratação intensa, selagem da cutícula capilar e um brilho radiante. Com o Frizz Zero TRUSS, você terá resultados imediatos e duradouros, recuperando a maciez, a maleabilidade e o movimento natural dos seus cabelos. A versatilidade do Frizz Zero TRUSS é um dos seus grandes diferenciais. Você pode incorporá-lo à sua rotina capilar de diversas maneiras: Como um tratamento pré-lavagem, potencializando a ação do shampoo; durante a lavagem, após o shampoo, para um boost de hidratação; ou como leave-in, para finalizar o penteado com proteção extra contra o frizz e agentes externos. Experimente o poder do Frizz Zero da TRUSS e diga adeus aos fios rebeldes, conquistando um cabelo impecável em qualquer ocasião! **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 26.9, 26.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8262j-mjyocori8b2acf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58253120923', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254053262', 'Tangle Teezer Ultimate Detangler Chrome Neo Gold - Escova de Cabelo', 'Escova de cabelo. Tangle Teezer Ultimate Detangler Chrome é ideal para potencializar os efeitos de produtos capilares. A Escova de Cabelo Tangle Teezer Ultimate Detangler Chrome une sofisticação e funcionalidade para uma rotina de beleza impecável. Desembaraça os fios com suavidade, remove os nós, reduz a quebra e potencializa a ação dos seus produtos favoritos, proporcionando cabelos mais saudáveis, hidratados e com uma aparência incrível. Seu design exclusivo é inspirado em uma temática futurista-chique. Como usar: É ideal para ser usada no banho, após piscina e praia para desembaraçar os cabelos molhados, facilitando também a distribuição de produtos. Não utilizar nos cabelos secos ou com fontes de calor. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 163.9, 163.9, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-8260l-mjyc76eioqva52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58254053262', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206603146', 'NIVEA Cellular Luminous 630 Antispot FPS 50 - Fluido 40ml', 'Fluido uniformizador de marcas para todos os tipos de pele.NIVEA Cellular Luminous 630 FPS 50 uniformiza o tom e previne marcas causadas pelo sol. Garante resultados em 4 semanas de uso. O Fluido Facial Protetor NIVEA Cellular Luminous 630 FPS 50 traz uma fórmula avançada capaz de reduzir as marcas existentes e evitar o seu reaparecimento, deixando a pele mais uniforme e luminosa. Com textura leve rapidamente absorvida e fator de proteção solar 50, também previne o fotoenvelhecimento enquanto hidrata a pele com a ação do Ácido Hialurônico e Vitamina E. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 121.9, 121.9, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-8262k-mlmis43j18gfb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58206603146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594743419', 'Mantecorp Epsiol Smart Color FPS 50 - Protetor Solar Facial com Cor 40ml', 'Protetor solar com cor para todos os tipos de pele. Mantecorp Smart Color FPS 50revela a cor ao ser espalhado na pele, se adaptando a todos os tons. O Protetor Solar Mantecorp Smart Color FPS 50 oferece alta proteção contra os raios UVA e UVB e ajuda a proteger contra a luz visível. Além disso, possui ação antioxidante, rejuvenescedora, deixando a cútis com toque seco e aparência mais saudável. Benefícios de Protetor Solar Facial com Cor Mantecorp Episol Smart Color FPS 50: ▸Protetor solar com cor para todos os tipos de pele;▸FPS 50 com alta proteção UVA e UVB;▸Protege também contra a luz visível;▸Cor inteligente que se adapta ao tom da pele;▸Ação antioxidante e rejuvenescedora;▸Textura leve e toque seco;▸Deixa a pele com aparência uniforme e saudável. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 96.9, 96.9, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-8261o-mlmga9vn9c011d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F23594743419', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256680678', 'Kit Phebo Mediterrâneo Nectarina da Andaluzia - Barra', 'Kit com sabonetes em barra para todos os tipos de pele. Kit Phebo Mediterrâneo Nectarina da Andaluzia hidrata e perfuma suavemente o corpo durante a limpeza. Com base vegetal, Kit Phebo Mediterrâneo Nectarina da Andaluzia tem uma fragrância frutal e fresca, que releva a suculência da nectarina, com um toque romântico floral. Dessa forma, torna o momento do banho mais revigorante e sofisticado. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 17.7, 17.7, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-82616-mlnznoypvaj3f8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58256680678', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
