INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58213454414', 'Protetor Auricular Carbografite CG 107 Tipo Concha 20dB Abafador Ruído Ouvido EPI Proteção Auditiva Amarelo', 'O Protetor Auricular Ouvido Abafador Ruídos Tipo Concha 20dB da marca Carbografite é ideal para quem busca proteção auditiva eficaz e conforto. Com conchas ovais de material plástico rígido e bordas almofadadas, este protetor garante um ajuste confortável e seguro. O arco tensor é feito de aço inoxidável e plástico de alta resistência, proporcionando durabilidade e ajuste perfeito. Com uma atenuação de 20dB, é perfeito para ambientes ruidosos. O modelo CG 107 não é eletrônico e não possui cordão, sendo uma opção prática e eficiente. Produto novo e sem validade, certificado de aprovação Nº 9.704. Imagens meramente ilustrativas.', 46.19, 46.19, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Gym Protective Gears', 'https://cf.shopee.com.br/file/sg-11134201-825aq-mq3xcughv7cw3b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380456261%2F58213454414', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
