INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497475430', 'Rotor Distribuidor Gm C10 1974 a 1984 - 106568 - 21558', 'Rotor Distribuidor Gm C10 1974 a 1984 106568 21558 TODOS COM DISTRIBUIDOR DELCO REMY (IGNIÇÃO PLATINADO) O rotor é um dispositivo do sistema de ignição que tem por finalidade, distribuir as centelhas de alta tensão para cada um dos pólos da tampa do distribuidor. Alguns rotores possuem uma resistência entre seu contato central e sua extremidade. Essa resistência serve para atenuar as interferências eletromagnéticas provocadas pela alta tensão do sistema.', 24.28, 24.28, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rd6v-lui9udeiitmyfb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23497475430', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23192971682', 'Tubo Água ESCORT 1997/2002 - 31563 - VC317B', 'Tubo Água ESCORT 1997/2002 (Conector Mangueira Bloco do Motor) O Tubo de Refrigeração do motor é um item de suma importância para o sistema de arrefecimento, a sua vida útil está ligada diretamente aos cuidados com a manutenção e troca do fluído (água + anticorrosivo) dentro do período recomendado. Quando não utilizado da maneira correta este tubo libera uma camada corrosiva que circula pelo sistema de arrefecimento danificando todos os componentes ligados ao sistema de arrefecimento.', 51.03, 51.03, NULL, 'Automobiles > Automobile Spare Parts > Radiators, Engine Cooling & Climate Control', 'https://cf.shopee.com.br/file/sg-11134201-7rasd-maiuzxlk8p5dfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23192971682', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993509174', 'Filtro Combustível Gm Omega 1992 a 1999 - 798797 - FCI1105A', 'Filtro Combustível Gm Omega 1992 a 1999 798797 FCI1105A Omega - (CD) - gasolina - automático / mecânico 3.0 12V O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 47.84, 47.84, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbkg-lmyolr0v50yr26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22993509174', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
