INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14649116496', 'Protetor solar tapa sol automotivo para-brisa metalizado luxcar', 'Somos a Go! Mec Auto Peças, estamos no ramo de autopeças para veículos nacionais e importados há quase duas décadas, nosso estoque conta com uma variedade de 45000 itens. Todos os nossos produtos são novos, originais e com garantia._x000D_ _x000D_ Para-Sol_x000D_ 1 unidade_x000D_ O Para-Sol Luxcar é confeccionado com materiais de alta qualidade, foi desenvolvido para proteger o interior do seu carro, bloqueando até 90% dos raios solares. Possui superfície refletiva e tamanho universal, adaptável na maioria dos carros nacionais e importados._x000D_ _x000D_ Vantagens:_x000D_ • Produto antitérmico_x000D_ • Bloqueia os raios solares em até 90%._x000D_ • Protege o interior do veículo._x000D_ • Fácil de guardar, dobrável._x000D_ _x000D_ Modo de usar:_x000D_ 1. Desenrole os elásticos, desdobre e localize as ventosas que estão dentro das dobras do para-sol._x000D_ 2. Encaixe a base das ventosas aos furos nos cantos do para-sol._x000D_ 3. Fixe as ventosas na parte superior do seu para-brisa, de forma que o seu para-sol fique bem esticado._x000D_ _x000D_ Validade Indeterminada', 39.0, 39.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Sun Shade', 'https://cf.shopee.com.br/file/cb2885e20a38703e369ece46d55ac7ba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549478150%2F14649116496', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598816485', 'Alto Falante Eros 15" Target XBass 5k 2500W RMS 4 Ohms 15 Polegadas Double Magnet Subwoofer Grave', 'Eros E-15 Target Xbass 5K O novo Target Xbass 5K entrega graves firmes e envolventes, combinando potência profissional com a robustez que você precisa em sistemas de paredão, trios elétricos e setups automotivos de alta performance. Com 2.500W RMS de potência, ele mantém a fidelidade dos graves mesmo nos volumes mais altos, graças ao design aprimorado e à tecnologia Eros. Principais características técnicas - Potência RMS: 2.500 W - Potência musical máxima: 5.000 W - Impedância nominal: 4 Ohms - Resposta de frequência: 37 Hz – 1.800 Hz - Sensibilidade: 95,5dB - Diâmetro: 15 polegadas - Diâmetro da Bobina: 4 polegadas - Bobina dupla de alta temperatura - Cone de celulose reforçada - Suspensão de alta excursão - Estrutura em alumínio injetado com sistema de ventilação otimizado Por que escolher o Target Xbass 5K? - Graves profundos e definidos, mesmo em volumes extremos - Construção robusta para maior durabilidade em todos os ambientes - Dissipação térmica eficiente que protege a bobina sob carga intensa - Resposta estendida, abarcando desde subgraves até médios sem distorção - Design pensado para fácil instalação em caixas seladas ou bass-reflex Aplicações recomendadas - Paredões e trios elétricos - Sistemas de som automotivo - Eventos ao ar livre - Palcos e estruturas móveis Transforme seu projeto de som com o verdadeiro grave. Sinta cada batida com o Eros Target Xbass 5K!', 1900.0, 1870.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mderdp9paua9e7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411081274%2F22598816485