INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898107825', 'Kit Jacques Janine 3 Óleos Reparadores Pontas Miracle Oils Cronograma Capilar 7ml', 'Os óleos Jacques Janine Miracle Oils são a combinação perfeita de tecnologia e ingredientes preciosos, proporcionando brilho, nutrição e revitalização para os cabelos. Disponível em três versões exclusivas: Ojon: Restauração e hidratação profunda, ideal para fios danificados. Baobab: Nutrição e fortalecimento, perfeito para cabelos frágeis e quebradiços. Monoi: Brilho intenso e maciez, indicado para todos os tipos de cabelo. Textura leve, não pesa nos fios Uso diário para resultados surpreendentes Frascos compactos de 7ml, ideais para levar na bolsa Transforme o cuidado com seus cabelos em um momento de luxo. Experimente o poder dos Miracle Oils!', 46.9, 39.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7ra1i-m4kdindoym3608', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1248946294%2F22898107825', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
