INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12637348968', 'Bomba pressurizadora 250 watts 4000L/H - BFL300 - Intech Machine', 'Produto: Bomba pressurizadora 250 watts 4000L/H - BFL300 - Intech Machine Marca: Intech Machine Descrição: A Bomba pressurizadora da Intech Machine é ideal para pressurização de casas, apartamentos, sistemas de ar condicionado, sistemas de aquecimento central a gás, pressurização de aquecedores solares e circulação de água. Ela proporciona um banho muito mais confortável e agradável através de um jato com maior pressão, sendo que pressuriza até 4 pontos de sua casa. A BFL300 é compacta e silenciosa. Seu fluxostato incorporado liga e desliga a bomba automaticamente quando a torneira, chuveiro ou outro ponto similar da casa é aberto ou fechado, melhorando o aproveitamento de água e economizando energia. Acompanham a BFL300 dois adaptadores de 3/4" para 1", que podem ser ligados na entrada e na saída da bomba caso sua instalação residencial seja de 1". Além disso, a BFL300 já vem com cabo elétrico e plug de tomada que tornam a instalação extremamente fácil e rápida. Eficiente, econômica e fácil de instalar. São muitas as razões para você ter esta excelente bomba pressurizadora da Intech Machine. Especificações: Potência: 250W (110v) - 300W (220V) Vazão: 4000 l/H (110V) - 4500 l/H (220V) Pressão Máxima: 16 mca Alimentação: Eletricidade Recalque de Sucção: 1" Fluxostato: Interno Rotação (RPM): 3450 RPM Temperatura máx. água: 60 °C. Itens Inclusos: 2 adaptadores de 1" para 3/4". Peso: 4.50 Kg', 519.78, 452.9, NULL, 'Home & Living > Tools & Home Improvement > Water Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-825b2-mr3b7y3iyy9te4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F12637348968', NULL, NULL, '2026-07-28T02:11:31.708458+