INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194656645', 'Macacão Bracelete da Amizade Manga Curta - All the Colors - TurmaTube', 'O Macacão Bracelete da Amizade é puro carinho e conforto para o seu bebê! Feito em suedine fio 40 de alta qualidade (100% algodão), ele é macio, leve e delicado, perfeito para a pele sensível dos pequenos. Ideal para os dias mais quentes, o modelo possui gola envelope, que facilita o vestir, e botões de pressão na área da fralda, tornando as trocas muito mais práticas e rápidas. A estampa traz as personagens Lara, Nina e Valentinha, celebrando a amizade e o universo encantado da TurmaTube em um design lúdico e cheio de ternura. ✨ Detalhes do Produto: 👕 Tecido: Suedine Fio 40 de alta qualidade – 100% Algodão 🧸 Toque suave e respirável – Ideal para a pele sensível dos bebês 👶 Botões de pressão – Facilitam a troca da fralda 🧵 Gola envelope – Facilita o vestir e o despir 🌤️ Manga curta – Leve e apropriado para climas quentes 🎨 Estampa exclusiva TurmaTube – Lara, Nina e Valentinha 🩷 Cor: Rosa 📏 Tamanhos: P, M e G 📦 Contém: 1 macacão 🌈 Coleção: All the Colors Conforto, amizade e afeto em cada detalhe — feito para acompanhar o seu bebê com amor em todas as fases. 💜 TurmaTube - Fazemos parte da sua rede de apoio, cuidando de você e do seu bebê em cada etapa da jornada materna.', 68.9, 49.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Bodysuits & Jumpsuits', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgh7jhwysjk45a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1245828786%2F22194656645', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
