INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197676831', 'Acabamento Moldura Rack Teto Traseiro Esquerdo Vw Spacefox', 'Produto: - Acabamento Moldura Rack Teto Traseiro Esquerdo - Peça 100% Original Volkswagen - Favor informar o chassi no campo de Perguntas para confirmar a aplicação da peça. Aplicação: SpaceFox 2006 - 2010 - Garantia: 90 Dias. - Enviando normalmente. Somos a Concessionária Faria Veiculos autorizada Volkswagen em São Paulo, SP', 279.9, 279.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdwr-lyfht6a515vf86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1291350746%2F23197676831', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21697924631', 'Limpador Multiuso Apc Alcalino Canelinha 2L Finisher', 'Limpe superfícies encardidas e remova marcas de gordura com o Canelinha APC Flotador Multiuso Finisher 2L. Este limpador multifuncional concentrado conta com ação flotadora de alta tecnologia, ideal para desprender gorduras, óleos e sujeiras pesadas sem agredir o material. Perfeito para o interior e exterior do veículo, deixando um aroma agradável após a aplicação. Ação Flotadora Potente: Desprende a sujeira da superfície, facilitando a remoção em plásticos, carpetes e tecidos. Alta Versatilidade: Pode ser utilizado em borrifadores, tornadores, extratoras de estofados e equipamentos de espuma (snow foam). Fórmula Concentrada: Rende muito mais, permitindo diluições de até 1:50 conforme o nível da sujeira. Uso Seguro: Limpa profundamente mantendo a integridade das superfícies cuidadas. Modo de Uso Rápido: Diluição: Dilua uma parte do produto em até 50 partes de água, dependendo do grau de sujidade. Aplicação: Pulverize sobre a área. Se necessário, esfregue levemente com uma escova de cerdas macias ou pincel de detalhamento. Remoção: No motor ou exterior, enxágue com água. No interior (bancos e painéis), remova completamente o resíduo com uma flanela de microfibra úmida. (Nota: Evite borrifar diretamente sobre botões e componentes eletrônicos do veículo).', 43.9, 43.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Degreasers', 'https://cf.shopee.com.br/file/br-11134207-820m1-mofv4crcg1l24c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F369458625%2F21697924631', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
