INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200061634', 'T-Shirt Feminina Summer Marialícia Branco', 'Sinônimo de leveza e modernidade, a T-Shirt Marialícia é aquela peça-chave cheia de estilo para completar o seu closet. Feita em meia malha, ela possui comprimento intermediário, mangas curtas e estampa frontal com tema de verão, transmitindo a vibe relaxante da estação. Invista nesse visual incrível e combine com shorts ou saias para compor looks alegres e descontraídos, ou até mesmo com calças para um office look moderno.Detalhes da peça: • Feita em meia malha • Possui comprimento intermediário • Possui mangas curtas • Possui estampa com tema de verão • Ideal para usar com shorts, saias e até mesmo calças', 79.9, 39.95, NULL, 'Women Clothes > Tops > Shirts & Blouses', 'https://cf.shopee.com.br/file/sg-11134201-825at-mr1toiaav75s86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F58200061634', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
