INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24171365505', '[MINI] Innisfree Green Tea Seed Intensive Hidrating Serum,, 15ml', '[MINI] INNISFREE Green Tea Seed Intensive Hydrating Serum, 15ml O segredo para trazer a pele úmida e otimizar a eficácia dos produtos para cuidados com a pele com poder de resfriamento instantâneo e fornecimento de água profunda do chá verde Jeju e 5 tipos de ácidos hialurônicos. Informações do Produto 1. Hidratante intensivo com extrato de chá verde orgânico Jeju Green Tea com extrato de chá verde orgânico e 5 ácidos hialurônicos: Aumente 710% da umidade da pele imediatamente após o uso. 2. Reduza a temperatura da pele e acalme a pele fraca com Pantenol e alanto a pele fraca com Pantenol e alantoína: acalma temporariamente 42,03 por cento da pele vermelha devido a irritação com fatores externos. 3. Aumente a eficácia dos passos de acompanhamento dos cuidados com a pele abrindo vias d''água, ajudando a circular e acumular a umidade na barreira da pele, ajudando a construir uma barreira cutânea mais saudável: Melhorar 92,3% da barreira cutânea em 30 minutos. Guia DE USO Depois de lavar o rosto, pegue uma quantidade adequada e aplique-o suavemente no rosto e pescoço. Sérum [Pedido usado] Sérum - Pele ou Essence-in-Loção - Loção da pele ao redor dos olhos - Soro - Pele ou Essência em Loção - Loção da pele ao redor dos olhos - Creme Observação DO USO 1. Apenas para uso externo. 2. Evite contato direto com os olhos. Lave imediatamente com água se isso acontecer.', 28.59, 28.59, NULL, 'Beauty > Skincare > Facial Serum & Essence', 'https://cf.shopee.com.br/file/sg-11134207-7rd4z-lwry5rkrinns01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F24171365505', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3777523081', 'Prato para Bolo com Pé de Vidro 32cm Linha Viena Modena Sobremesa Doces - Ruvolo', 'O Prato de Vidro com Pé Gourmet da Ruvolo é ideal para servir suas preparações culinárias em casa, eventos ou encontros familiares. Seu design elegante realça a apresentação de bolos, tortas, petiscos, frios e frutas, transformando qualquer ocasião em um momento especial e sofisticado. Fabricado com vidro de alta qualidade, combina durabilidade e estilo refinado, com um delicado relevo que valoriza cada prato. Versátil e elegante, o Prato de Vidro Gourmet também é uma excelente opção de presente sofisticado, perfeito para surpreender amigos e familiares que apreciam servir com requinte. Uso: Bolos, Tortas, Petiscos, Frios e Frutas. Material: Vidro. Diâmetro: 320mm. Altura: 80mm. Conteúdo da Embalagem: 1 Peça. - Peça medida com o volume máximo até a boca - Diâmetro é medido pela largura maior da peça. - Pode sofrer variação de até 10% de seu volume. Dica de uso e preservação: • Recomendamos que a limpeza da peça seja feita a mão para evitar quebras ou danos. • Limpe a sujeira utilizando uma esponja macia, tire o resíduo de sabão e seque bem. • Não utilize abrasivos ou utensílios pontiagudos. • Evite impactos e não exponha o vidro a mudanças bruscas de temperatura pois poderá causar choque térmico e danificar seu produto. • Para realçar ainda mais o brilho da peça, limpe-a com uma flanela que não solte fiapos, levemente umedecida com álcool.', 108.99, 108.99, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhkopffvxbltee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373594761%2F3777523081', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
