INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194320773', 'Lâmpada Led Corsa 2002 A 2012 H1 H3 H7 V10 - Efeito Xênon', 'Seja bem-vindo(a) à sua Loja! Produto: Kit Super LED V10 para Chevrolet Corsa 2002 a 2012 – Iluminação Branca com Efeito Xênon ILUMINAÇÃO PODEROSA E MODERNA – MAIS SEGURANÇA, ESTILO E VISIBILIDADE PARA O SEU CORSA Transforme a iluminação do seu Chevrolet Corsa com o Kit Super LED V10. Com potência de 20000 lúmens por par e tonalidade branca 6500K, esse kit proporciona um upgrade completo no sistema de iluminação, garantindo excelente visibilidade noturna, visual moderno e instalação prática. Destaques do Produto Iluminação de Alta Intensidade: 20000 lúmens (par) para máxima visibilidade Tonalidade 6500K (Branco Puro): Estilo xênon com iluminação limpa e sofisticada Tecnologia Alemã: Durabilidade, eficiência e dissipação térmica de alto desempenho Sistema Plug & Play: Instalação rápida e sem adaptações Kit Completo: Itens essenciais já inclusos para instalação imediata Conteúdo da Embalagem 2x Lâmpadas Super LED H7 (Farol Baixo) 2x Lâmpadas Super LED H1 (Farol Alto) 2x Lâmpadas Super LED H3 (Farol de Milha) 2x Lâmpadas Pingo LED Chicotes de Instalação Manual do Usuário Aplicações compatível com: Chevrolet Corsa 2002 Chevrolet Corsa 2003 Chevrolet Corsa 2004 Chevrolet Corsa 2005 Chevrolet Corsa 2006 Chevrolet Corsa 2007 Chevrolet Corsa 2008 Chevrolet Corsa 2009 Chevrolet Corsa 2010 Chevrolet Corsa 2011 Chevrolet Corsa 2012 Especificações Técnicas Tonalidade da Luz: 6500K (Extremamente Branca) Luminosidade: 20000 lúmens (par) Potência: 30W por lâmpada Voltagem: 12V Vida Útil: Até 2x maior que LEDs convencionais Material: Corpo e base metálicos Resistência: À prova d’água, calor e vibrações Dissipação de Calor: Cooler embutido em cada lâmpada Chip: Importado de alta potência Dimensões: 9 cm (altura) x 4 cm (comprimento) Benefícios Mais Segurança: Luz forte e clara, com maior alcance Eficiência Energética: Potência elevada com menor consumo de bateria Durabilidade Superior: Design robusto e vida útil prolongada Instalação Simples: Compatível com o sistema original do veículo Dicas de Instalação (Importante!) Os LEDs devem ser instalados na posição horizontal para foco ideal. Pequenos ajustes garantem o melhor desempenho da luz. Envio Imediato e Garantia! Produto à pronta entrega __________________________________________________ COMPRA GARANTIDA PELA PLATAFORMA MARKETING PLACE. __________________________________________________ Palavras-chave: Kit LED Corsa, Super LED V10, Lâmpadas H7 H1 H3, Iluminação Branca 6500K, Farol LED Corsa 2002 a 2012, Efeito Xênon, Upgrade de Iluminação Corsa, LED Automotivo Completo.', 167.9, 129.29, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rdxi-md4yy6fecagw67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339582052%2F22194320773', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
