INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594288476', 'Kit Transmissão 12V GTS 1x12 1x11 C/ Corrente + Cassete GTS 11x50 + Pedivela GTS 34D + Cubo C/ Blocagem + Mov Central', 'Seja Bem-Vindo(a) ao nosso canal de vendas de Peças de Bicicletas. Kit de Transmissão GTS 12V - Upgrade Completo para sua Bike! Transforme sua bike com o kit de transmissão GTS 12V, ideal para ciclistas que buscam desempenho, durabilidade e suavidade nas trocas de marcha. Este kit oferece máxima eficiência em qualquer trilha ou estrada. BENEFÍCIOS: > Trocas de marchas rápidas e precisas – Ganhe agilidade e eficiência nas pedaladas. > Durabilidade e leveza – Peças de alumínio e aço de alta qualidade para máximo desempenho. > Fácil instalação e compatibilidade – Adaptável a diversas configurações de MTB e XC. ️ Marca: GTS Itens do KIT: Câmbio Traseiro GTS 12V – Trocas rápidas e precisas, compatível com cassetes de até 52 dentes. Passador GTS 12V – Ação 100% no polegar, sobe até 4 marchas por vez. Corrente GTS 12V (126 elos) – Resistente e compatível com transmissões de 12 velocidades. Movimento Central 34.7x122mm selado com rolamento GTS. Cassete GTS 12V 11x50T – Ampla relação de marchas para encarar qualquer terreno. > Modelo: 12V 11x50t > 12 velocidades > 11x50d > Aço e Alumínio > Escalonamento: 11-13-15-17-19-21-24-28-32-36-42-50 > Peso aproximado: 780g Pedivela GTS Single 34D – Leve e resistente, compatível com movimentos centrais de ponta quadrada. > Modelo: Single 34 Dentes > Material: Alumínio > BCD: 104mm > Compatível com velocidades: 1x7v / 1x8v / 1x9v / 1x10v / 1x11v / 1x12v > Compatível com movimento central: Ponta Quadrada > Encaixe do pedal: 9/16" (rosca grossa) > Coroa: Fixa de 34 dentes > Tamanho dos braços: 170 mm > Peso aproximado: 654 g Par de Cubos GTS K7 – Alumínio, rolamentados e com blocagem rápida para maior eficiência. > Modelo: Cassete 8v a 12v > Furos: 36F > Material: Alumínio > Peso: 880g (par) > Eixo dianteiro: 3/8x100x108mm > Eixo traseiro: 10x135x145mm > Rolamento: Rolamentado ℹ IMPORTANTE: Compra Segura Com Garantia Shopee. Somos Vendedor Indicado Pela Shopee. Enviamos sua compra rápido.', 630.4, 630.4, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rdw3-mcw4z60dowzkb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F22594288476', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
