INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19169253249', 'Colchão Mini Cama Montessoriana + Protetor Capa 68x148x8CM BF Colchões', 'O Colchão Mini Cama Montessoriana Infantil foi desenvolvido pensando no bem-estar e segurança da criança. Para tanto, passam por testes de alta performance e segurança em laboratórios, garantindo o selo de qualidade INMETRO, certificando a densidade real e a durabilidade da espuma. Colchão macio e confortável, praticidade e qualidade em um só produto. o protetor de colchão é perfeito para aumentar a vida útil do seu colchão, evitando acidentes com líquidos que possam danifica-los. Os protetores de colchão são 100 impermeável, antialérgico, fácil de lavar, que garante qualidade para os seus momentos de descanso! Características Colchão: Espuma Selada/Certificada: Densidade 18 (D18) Suporte de Peso: Até 50 kg por pessoas Antialérgico Colchão mais baixo para a segurança da criança Tecido em metalassê para mais conforto Antialérgico para suas noites tranquilas Toque mais macio Características Protetor de Colchão: 100 Impermeável Fixação com alça elástica de vestimenta fácil Percal 140 fios Bordado Matelassê Fofinho Antialérgico Benefícios do Protetor: Maior Conforto, Maior Maciez, Toque Suave, Ajuda na sua saúde e Facilidade na hora de lavar Certificado de Qualidade: Pró-Espuma Selo Inmetro: 002930/2017 OCP: 0095 Este Kit Contém: 1 Protetor de Colchão Impermeável 1 Colchão Infantil Mini Cama D18 Dimensões: Altura: 8 cm Largura: 68 cm Profundidade: 148 cm Garantia do Fornecedor: 12 Meses Observações: Não fazemos entregas em locais de acesso apenas por estrada de terra, estrada de areia, por balsa ou barco. Não subimos produtos por escadas e elevadores. Não nos responsabilizamos por montagens, desmontagens e instalações. Confira as dimensões do produto no momento da compra e certifique-se que o item passará normalmente por elevadores, portas, escadas e/ou corredores, evitando assim futuros desagrados.', 409.37, 299.0, NULL, 'Home & Living > Bedding > Mattress Protectors & Toppers', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m1e5ljzqf6u8ef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412482669%2F19169253249', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18299653913', 'Par Batente Coxim Amortecedor Dianteiro Pálio 2001 Axios', 'PAR DE KIT BATENTES DE AMORTECEDOR DIANTEIRO ORIGINAL AXIOS CÓDIGO ORIGINAL 0441140 0441141 PRODUTO ORIGINAL,EMBALAGEM LACRADA O Kit Suspensão Axios vem com as peças ideias que a suspensão do seu carro precisa, com muita qualidade os itens vão te oferecer a melhor confiança e durabilidade. PRINCIPAIS CARACTERÍSTICAS - Codigo de Fábrica: 0441140/0441141 - Fabricante: Axios - Aplicação: Dianteiro - Lado: Direito/Esquerdo Aplicação: FIAT Idea 2006 / 2016 Todas Versões Palio 1996 ao 2017 Todas Versões Siena ... 1998 ao 2016 Todas Versões Palio Weekend 1997 ao 2017 Exceto Adventure CONTEÚDO DA EMBALAGEM - 02 Batentes - 02 Coifas - 02 Coxim Com Rolamento ATENÇÃO - Não nos responsabilizamos pelo mau uso ou instalação indevida do produto, sempre recomendamos que a instalação seja feita por um profissional especializado. - Imagens meramente ilustrativas.', 399.3, 399.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7rbn0-m5x3ingd9bx394', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1463823458%2F18299653913', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21997796439', 'Repelente Off! Gel Baby 117g', 'O Repelente Off! Baby protege os pequenos contra os os mosquitos transmissores de doenças e outros insetos. Indicado para bebês a partir de 3 meses, ele protege até contra os transmissores de dengue, febre amarela, zika e chikungunya. Sua fórmula suave à base de icaridina não agride a pele sensível das crianças e não contém perfume. A textura em gel garante uma aplicação delicada, proporcionando todo o conforto que seu bebê merece. O produto age por até seis horas, garantindo proteção prolongada.', 32.23, 32.23, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdxe-lzfmfr9ck0uy63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F21997796439', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593878398', 'Chave De Impacto 12v Tw141dz Makita 2bat Carreg Soquete', 'DISTRIBUIDO POR C-JAU FERRAMENTAS Chave De Impacto 12v Tw141dz Makita 2bat Carreg Soquete Chave de Impacto TW141DZ 12V CXT Com jogo de soquete Lynus é ideal para trabalhar em espaços reduzidos e aplicações em zonas elevadas. Possui velocidade variável (0-2.600 RPM e 0-3.200 IPM) para uma ampla variedade de aplicações. Design ultra-compacto com bateria para reduzir a fadiga do operador (não inclui bateria). Luz LED integrada ilumina a área de trabalho. Conveniente entrada de 1/2" para rápida mudança. Martelo e bigorna Makita criados com materiais como o aço da melhor qualidade e endurecidos com calor, para maior durabilidade da ferramenta. Empunhadura ergonômica, que adapta-se perfeitamente à mão para maior comodidade e controle. - Especificações Técnicas: - Tensão da bateria: 12 V - Tipo de bateria: CXT - Rotações por minuto: 0 - 2.600 Rpm - I.p.m: 0 - 3.200 ipm - Par máx. de aperto: 145 Nm - Capacidade máx. de parafuso: M6 - M12 - Inserção: 1/2" - Velocidade variável (interruptor) - Travão elétrico - Iluminação integrada - Dimensões (CxLxA): 168 x 66 x 224 mm - Peso: 1,1 Kg - Emissão de vibração: 7,50 m/seg² - Incerteza da vibração: 1,50 m/seg² - Pressão sonora: 93,00 dB(A) - Potência sonora: 104,00 dB(A) - Incerteza (k) sonora: 3,00 dB(A) Acompanha: Carregador Bateria de Lítio 12V Slide Bivolt Makita: 02 Baterias 12V bl1016b Características Bateria: Bateria de Lítio 12V Slide 1,5Ah BL1016b Makita. Bateria de íons de lítio; Encaixe tipo slide; Leve e compacta; Sem efeito memória.', 1028.0, 980.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m83bpf4fxhjlb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380456261%2F22593878398', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499237819', 'Adesivo Premium logo Oficial Motul para carro ou moto 14x4 cm', '🏁🔥 ADESIVO OFICIAL MOTUL: LEVE A PAIXÃO PELAS CORRIDAS COM VOCÊ! 🔥🏁 Transforme seu carro ou moto em uma verdadeira máquina de velocidade com o adesivo oficial da Motul! Com um design icônico que celebra a história de inovação e desempenho da Motul, este adesivo é o acessório perfeito para os verdadeiros aficionados por automobilismo e motociclismo. ✔️ Tamanho ideal de 14x4 cm para caber perfeitamente em qualquer superfície. ✔️ Material de alta qualidade e durabilidade para resistir aos elementos e permanecer vibrante por muito tempo. ✔️ Apresenta o logo oficial da Motul, símbolo de excelência e confiabilidade no mundo das corridas e lubrificantes automotivos. 📣 OBSERVAÇÃO IMPORTANTE: Este adesivo é um item exclusivo e não está disponível para venda. É uma peça de colecionador, oferecida apenas como parte de promoções especiais e eventos da Motul. Não perca a oportunidade de mostrar seu apoio à marca líder em desempenho automotivo!', 111.11, 100.0, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ltzcddep7edw66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1068060049%2F20499237819', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56358133092', 'Tênis Beira Rio Casual Napa Turim Preto - Feminino Casual Moderno Confortável Macio Leve', 'Conforto acolchoado e estilo urbano para todos os momentos! Tênis Beira Rio Casual Napa Turim Preto - Feminino Ficha Técnica: Marca: Beira Rio Cor: Preto com detalhes em prata Gênero: Feminino Indicação: Uso urbano, casual e esportivo retrô Cabedal: Sintético de alta qualidade Palmilha: Macia com espuma de alta densidade Sola: Borracha antiderrapante Entressola: EVA Fechamento: Cadarço tradicional Amortecimento: Macio Estabilidade: Neutro Tecnologias: Estrutura acolchoada para maior conforto Entressola: EVA leve Detalhes: Design casual com toque moderno e acabamento delicado Se você busca um tênis versátil que una estilo e bem-estar, o Beira Rio Napa Turim é a escolha ideal. Porque investir: Seu design casual com acabamento acolchoado proporciona conforto prolongado a cada passo. Produzido em material sintético resistente, ele garante durabilidade sem abrir mão da leveza. O forro têxtil favorece a ventilação, mantendo os pés frescos ao longo do dia, enquanto o solado antiderrapante oferece mais segurança ao caminhar. Um modelo perfeito para acompanhar sua rotina com charme e praticidade. Conteúdo da embalagem: 1 par de Tênis Beira Rio Casual Napa Turim Preto - Feminino', 189.99, 145.99, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-81zwg-mmkl885yqm10c9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F56358133092', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40422549053', 'Fantasia Halloween Infantil pra Menino Palhaço Assassino de Luxo com Chapeu Pierrot Palhacinho Circo de Terror', 'Itens inclusos:1x Macacão Jardineiro 1x Camisa manga longa 1x Gola de Babado 1x Chapéu Dimensões do produto: Tamanho P - Numeração de roupa 2 a 3, para crianças que tenham até 105 cm de altura, dos pés a cabeça. M - Numeração de roupa 4 a 6, para crianças que tenham de 106 a 117 cm de altura, dos pés a cabeça. G - Numeração de roupa 7 a 9, para crianças que tenham de 118 a 128 cm de altura, dos pés a cabeça. GG - Numeração de roupa 10 a 12, para crianças que tenham de 129 a 150 cm de altura, dos pés a cabeça. Ficou na dúvida de qual tamanho escolher ? Sempre indicamos a escolha de um tamanho maior pois é mais fácil fazer um ajuste, caso necessário. E por ser para criança, a fantasia irá durar por mais tempo conforme ela for crescendo. Especificações Técnicas Material: 100% Poliéster. Cor: Vermelho e Cinza. Produto a pronta entrega! Produto original! Respeitável público, o palhacinho mais divertido do circo chegou para a festa! Com a Fantasia de Palhacinho de Circo Infantil, seu pequeno estará pronto para muitas brincadeiras e travessuras com um visual completo, colorido e cheio de detalhes. Este traje super completo foi pensado para criar um look em camadas, cheio de estilo. O conjunto inclui uma camisa de manga longa com uma divertida estampa de losangos, um macacão estilo jardineira listrado com pompons, uma gola de babados que pode ser usada ou não, e para finalizar, um charmoso mini chapéu de festa. É a fantasia perfeita para o Halloween, festas de aniversário e eventos escolares! Kit Completo Rico em Detalhes Vermelho Preto e Cinza Gola removível Com Chapeu Estampa de Alta Qualidade Fecho de contato Leve e confortável', 176.9, 176.9, NULL, 'Baby & Kids Fashion > Boy Clothes > Costumes', 'https://cf.shopee.com.br/file/sg-11134201-824h5-mfb391ydhvrg4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064041628%2F40422549053', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9351875829', 'Modulo De Vidro Eletrico Logan E Sandero Tury Lvx 5.11 De', 'Tury PRO 1.11 DE Renault Renault Sandero e Logan Compativel com os veiculos: Renault Sandero De 2016 ate 2019 GT Line, RS, Stepway, Rip Curl, Dynamique e Expression Avantage com 4 vidros eletricos automaticos originais de fabrica. Renault Logan De 2016 ate 2019 Dynamique com 4 vidros eletricos automaticos originais de fabrica. Modulo que realiza o fechamento e abertura automatica dos vidros eletricos atraves do sistema keyless (controle remoto) original do veiculo. O fechamento dos 4 vidros ocorre ao travar as portas pelo controle remoto original do veiculo. A abertura somente dos 2 vidros dianteiros ocorre com 3 toques no botao de destrava do controle remoto original. Possui conectores originais para facilitar a instalacao. TEMOS TODA A LINHA DE MODULOS PARA TODOS OS VEICULOS, CONSULTE-NOS! Produto a pronta entrega A POSTAGEM SERA FEITA DENTRO DO PRAZO 24 HORAS UTEIS. GARANTIA 24 meses contra defeito de fabricacao A GARANTIA PERDERA SEU EFEITO SE: . A instalacao ou utilizacao do produto estiverem em desacordo com as recomendacoes do manual tecnico; . O produto sofrer qualquer dano provocado por acidente, queda, agentes da natureza, infiltracao de agua ou consertos realizados por pessoas nao credenciadas pela Tury do Brasil Ind. e Com. Ltda.; . Se houver rasuras, alteracoes ou for retirada a etiqueta com o numero de serie do produto. A GARANTIA NAO COBRIRA: . Transporte e demais despesas de envio para o conserto; . Desempenho insatisfatorio do produto referido a instalacao ou condicoes inadequadas do veiculo aonde o produto estiver instalado; . Se o consumidor desejar ser atendido na localidade que se encontra o veiculo, ficara a criterio da Tury do Brasil Ind. e Com. Ltda. A realizacao ou nao deste atendimento. Nestes casos havera cobranca de taxa de visita, que sera de responsabilidade do cliente. . Qualquer prejuizo do usuario, decorrente de impossibilidade de utilizacao do produto.', 319.92, 319.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Glass', 'https://cf.shopee.com.br/file/b2ede40c96d306135b757e3c5b13dace', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F332985667%2F9351875829', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14615237235', 'Poltrona Cadeira Decorativa Suede Varias Cores Pés Palitos Para Sala De Estar Recepções e Escritório', 'A poltrona Decorativa Opala proporciona um toque de charme e beleza em seu lar, feita com matéria prima de primeira qualidade, Revestida de Fibra e percinta no encosto e espuma no assento. ESPECIFICAÇÕES: - Estrutura: MDF e EUCALIPTO - Tecido: Suede - Pés: MADEIRA DIMENSÕES EXTERNAS: Altura : 88 cm largura: 78 cm Comprimento: 61 cm DIMENSÕES INTERNAS: Altura do chão ao assento: 48 cm Profundidade do assento: 45 cm Largura do assento: 43 cm Pés palito envernizados cor mel Peso Suportado: Até 100 Kg sem impacto garantia de fábrica 90 dias para somente defeito de fábrica. * Atenção *Consultar o frete antes de finalizar a compra pois este anuncio não tem frete grátis, O FRETE ESTÁ INFORMADO TAMBÉM NO ANUNCIO é para somente 1 poltrona. * Este produto é enviado através de transportadora dependo de cada região tem o seu prazo determinado pela a transportadora para ser entregue em dias úteis, em horário comercial. * Não nos responsabilizamos no ato da entrega por montagens, desmontagens, instalações de produtos, nem utilização de guinchos ou equipamentos similares para acesso a pisos superiores em apartamentos. - Confira as dimensões do produto no momento da compra e certifique-se de que passará normalmente por escadas, elevadores, portas e corredores. Observando as orientações acima, evita-se futuros desagrado ou imprevistos com a entrega do produto. Havendo despesas adicionais, serão de responsabilidade do cliente; *Instruções de Limpeza: Utilizar um pano limpo e seco. Não limpar com escovas ou produtos abrasivos, * No prazo de garantia não é permitido fazer impermeabilização, pois caso seja feita perde totalmente garantia. Obs: Este produto é recomendado para ambientes residenciais em áreas internas, por isso, não o deixe exposto à luz direta do sol, para que não sofra alteração na cor * Montagem é simples e dever do cliente ( somente rosquear os pés). * EM CASO DE DEVOLUÇÃO DO PRODUTO Aceitaremos a devolução nós seguinte termos. *O Produto deverá ser embalado da mesma forma que foi entregue, não deverá ter rasgos ou esteja com fissuras. * Deverá ser etiquetado de igual modo para que não haja extravio, deverá ter nota de devolução. * O produto não poderá estar danificado ou com marcas de uso * Deverá ser entregue a transportadora por agendamento de coleta a qual nós ficaremos responsável por agendar . * Informamos que o horário de coleta é horário somente comercial. Fica acordado que finalizar a compra estou totalmente de acordo com toda descrição a qual fui informado através do anuncio a qual afirmo no ato da finalização da compra ter lido. QUALQUER DUVIDA ESTAMOS A DISPOSIÇÃO.', 329.9, 188.05, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lsn4h5j835t02d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F306878488%2F14615237235', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11742341098', 'Espátula Multiuso de Aço Inox 80mm Série 790 - Castor', 'Essa espátula de Aço Inox 80 mm da Castor é multiuso, e ideal para o manuseio e aplicação de gesso, além de ser indispensável na limpeza, preparo, e revestimento de superfícies. Vale ressaltar que ela conta com uma chapa inteiriça, o que aumenta sua resistência. Você também pode utiliza-la para fazer efeitos espatulados com massas para textura. CARACTERÍSTICAS Material da chapa: Aço Inox Material do Cabo: Plástico Uso Indicado: Multifuncional, essencial para limpeza, preparo e revestimento de superfícies, manuseio e aplicação dos mais variados produtos como massas (corrida, grossa, fina), colas, resinas (acrílicas, vinílicas) e texturas. Vantagens: série disponível em diversos tamanhos, do mais estreito ao mais largo para uso de acordo com a necessidade – em locais pequenos, de difícil acesso, cantos, superfícies arredondadas ou maiores. Excelente para criar efeitos espatulados com massas para textura. Fabricada com lâmina de aço inox flexível e resistente. Indicações adicionais: Limpeza e raspagem de diversas superfícies, como grelhas de churrasqueira e pisos. Código do fabricante: 792 Limpeza e conservação: Logo após o uso, retirar os resíduos do produto utilizado. Produtos à base de água, lavar com água e sabão. Produtos sintéticos, lavar com solvente adequado e depois com água e sabão. Secar bem e guardar em local arejado. FERRAMENTAS QUE GARANTEM RESULTADOS PRECISOS Perfeição e versatilidade, tudo o que você precisa em uma só ferramenta. A Castor selecionou as melhores e mais resistentes espátulas para você. Tudo para facilitar a sua vida! SEGURANÇA Compre com segurança! Nossa equipe de suporte estará à disposição caso tenha algum problema ou dúvida. Aguardamos seu pedido!', 37.1, 37.1, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-7qvfi-leq4ry35qrv35c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524472372%2F11742341098', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997381159', 'Kit 4 Óleos Motul 510 2t (2 Tempos) - Trilha / Off-road 4l', 'MOTUL 510 2T - ÓLEO MOTUL SEMI-SINTÉTICO PARA MOTORES 2 TEMPOS. LUBRIFICANTE 2 TEMPOS – TECHNOSYNTHESE® – ESPECIALMENTE DESENVOLVIDO PARA MOTOS E CICLOMOTORES QUE UTILIZAM MOTORES 2 TEMPOS. - PROTEÇÃO AO MOTOR. - FORMULADO COM ANTI FUMAÇA. - PODE SER UTILIZADOS NA MISTURA COM A GASOLINA OU SISTEMA DE PRÉ MIX. - ADEQUADO PARA CATALISADORES. * APLICAÇÕES: LUBRIFICANTE PARA TODO TIPO DE MOTOS 2T: TRAIL, TODO TERRENO, ENDURO, CICLO MOTORES, EQUIPAMENTOS COM MOTORES DE 2T DE ELEVADO DESEMPENHO E REGIMES DE ALTAS ROTAÇÕES. PODE SER USADO EM EQUIPAMENTOS COM LUBRIFICAÇÃO AUTOMÁTICA OU COM SISTEMA MANUAL (PREMIX). OUTRAS APLICAÇÕES: SCOOTERS, QUADRICICLOS... * ESPECIFICAÇÕES: NORMAS: API TC - ISO -L-EGD HOMOLOGAÇÕES: JASO FD Nº 033MOT065 LUBRIFICANTE TECHNOSYNTHESE, COM SUPERIORES BÁSICOS QUE MELHORAM A RESPOSTA FRENTE AO DESGASTE E COM ALTO PODER DE COMBUSTÃO, REDUZINDO A QUANTIDADE DE FUMAÇA VISÍVEL ASSIM COMO A FORMAÇÃO DE DEPÓSITOS. A NORMA JAPONESA JASO PROPÕE A SUPERAÇÃO COM ÊXITO DE 4 ENSAIOS DE BANCADA COM MOTORES PARA QUANTIFICAR O RENDIMENTO DO LUBRIFICANTE QUANTO AO PODER DE LUBRIFICAÇÃO, DETERGÊNCIA, PROPRIEDADES ANTI-FUMAÇA E ANTI-DEPÓSITOS. O NÍVEL FD É O MAIS ELEVADO DA NORMA E É O QUE CONSEGUE ÓLEOS COM O MAIOR PODER DE LIMPEZA INTERNA DO MOTOR. MISTURA RÁPIDA E HOMOGENEA COM TODOS OS TIPOS DE GASOLINAS COMERCIAIS.', 586.66, 528.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134201-7r98o-llgecunta1x8e7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1068060049%2F18997381159', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
