INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42727958988', 'Tênis Reserva TYPE-R Preto - Masculino', 'Tênis Reserva TYPE-R Preto - Masculino Moderno e tradicional, esta é a mistura que compõe o Tênis Type-R Clássico Reserva. Relembrando os sneakers do anos 90, ele possui um visual todo elegante. A novidade fica por conta da sola feita em caixa de borracha no formato Szuck, cuja principal característica é ser mais alta na parte de trás, com um contorno violão. O cabedal é feito em couro supermacio e forrado de tecido esportivo poliéster. Além disso, possui palmilha produzida em EVA. Ideal para passear, trabalhar e sair, o Tênis Type-R Clássico é perfeito para quem deseja adotar um visual mais retrô com um toque contemporâneo. FICHA TÉCNICA: Gênero: Masculino Indicação: Social / Dia a Dia Cabedal: Couro Cor: Preto com detalhes em Bege Solado: Borracha Ajuste: Cadarço Marca: Reserva Conteúdo da embalagem: 1 par de Tênis Reserva TYPE-R Preto - Masculino', 649.99, 572.0, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-82624-mje9qze90ykg51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F42727958988', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298005468', 'Correia Poly V Alternador BOXER 98 99 - 14862 - 6PK900/905', 'Correia Poly V Alternador BOXER 98 99 Produto novo, com garantia e Nota Fiscal!_x000D_ _x000D_ Correia Poly V - 6PK900/905_x000D_ BOXER - 2.5 8V_x000D_ Anos: 1998 1999_x000D_ Utilização: Virabrequim / Alternador / Bomba D''Água As correias Multi V permitem a transmissão não positiva de binários. A sua função: O acionamento do alternador, ventoinha, bomba de água, compressor do ar condicionado e direção assistida nos motores modernos. As correias Multi V estão sujeitas a envelhecimento e desgaste. Por essa razão, têm de ser controladas e substituídas a intervalos regulares. Os intervalos de controle e de substituição são sempre estabelecidos pelo fabricante do veículo e devem ser respeitados.', 47.98, 47.98, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbl5-lmt8j889nujd4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23298005468', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55752607469', 'Livro Coquetel Picolé 21 com Palavra Cantada | Passatempos Educativos', 'Reduza o tempo de tela com os passatempos Coquetel! Quer promover momentos de diversão longe das telas para os pequenos? Deixa com a gente!O livro Picolé ― Passatempos educativos traz 32 páginas completamente coloridas e repletas de caça-palavras, cruzadinhas, figuras diretas e jogos dos erros, pensados para crianças de 6 a 9 anos:Desenvolvimento cognitivo: atividades que reforçam memória de trabalho, reconhecimento de padrões e interpretação de texto, ampliando o vocabulário sem perceber. Coordenação motora fina: colorir, circular palavras e encontrar diferenças fortalecem o controle do lápis e a destreza manual, fundamentais para a escrita. Concentração e paciência: desafios graduais promovem persistência e disciplina, criando hábitos de foco em cada página. Aprendizado divertido: design vibrante e níveis de dificuldade ajustados fazem do estudo um jogo prazeroso. Portátil e inclusivo: perfeito para casa, escola ou viagens, mantém as crianças próximas ao papel e longe das telas! Invista em um entretenimento educativo de qualidade: adicione agora mesmo Picolé ao carrinho e transforme o tempo de tela dos pequenos em horas de passatempos lúdicos e educativos!', 14.99, 13.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-82278-mhv673089vk36e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F55752607469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
