INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20497110454', 'Colar Cordão Ponto de Luz Vermelho Coração em Prata 925', 'Corrente Colar Ponto Luz Coração vermelho em Prata Pura 925 Lindo e delicado colar com pingente de ponto de luz, perfeito para usar casualmente, e combina com qualquer roupa. Sua corrente veneziana tem 45 cm, e o pingente 0.6 mm de largura. Isso faz dele elegante e discreto, podendo ser usado no trabalho, ou para ir em lugares comuns. Todas as nossas peças acompanham um certificado de garantia permanente do teor da prata Garantia: Não cobrimos oxidação, ou quebra do produto. Cobrimos apenas a prata 925. Como evitar o escurecimento da prata: 1. Evite utilizar a joia ao mexer com produtos químicos 2. Ao dormir, tire-a e enrole num papel higiênico 3. Armazene sua joia em um local seco e arejado 4. Não deixe a joia entrar em contato com cosméticos (perfumes, cremes, produtos ou procedimentos químicos do salão de beleza) Garantia Permanente da Prata Não cobrimos oxidação ou quebra do produto', 49.0, 35.9, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lilshbx7g6tb5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316436073%2F20497110454', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
