INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19568514148', 'Conjunto de Ciclismo Feminino - Camisa Way Fresh Preta e Bermuda Espuma Way', 'CONJUNTO DE CICLISMO - CAMISA WAY FRESH + BERMUDA INDICAÇÃO DE TAMANHO (de acordo com a sua numeração de calça jeans) P- 36/38 M- 38/40 G- 42/44 GG- 44/46 (Modelo da foto veste P de camisa e M de bermuda) Camisa Way Fresh: • Conforto e Performance: Tecido esportivo que mantém o corpo seco e a temperatura estável. • Proteção Completa: UV+, tratamento antibacteriano e antimicrobiano. • Alta Qualidade: Poliéster sublimado, cores vivas e durabilidade garantida. • Praticidade no Pedal: 3 bolsos traseiros para levar itens essenciais. • Design Funcional: Zíper de 15 cm e elástico na barra para melhor ajuste. • Modelagem Slim: Confira a tabela de medidas para escolher o tamanho ideal. Bermuda de Ciclismo com Forro em Espuma: • Forro em Espuma Densidade 70: Modelagem anatômica que reduz impactos e aumenta o conforto durante pedais curtos ou médios. • Tecido Tecnológico: Composição de 90% Poliéster e 10% Elastano, garantindo ajuste perfeito ao corpo e alta respirabilidade. • Proteção UV: Segurança extra contra os raios solares. • Secagem Rápida: Mantém o corpo seco e confortável mesmo nos dias mais quentes. • Costuras Reforçadas: Maior durabilidade, ideal para treinos e competições intensas. • Barras com silicone: Evita que a bermuda enrole durante o pedal. • Dois bolsos laterais: Praticidade para carregar pequenos objetos como chaves, suplementos ou smartphone. Benefícios do Forro em Espuma: • Maior Conforto: Reduz dores e desconfortos na região da pelve. • Indicado para pedais de até 6 horas: Suporte adequado para diferentes tipos de ciclismo. • Facilita o movimento: Melhora o desempenho e evita atritos indesejados. Sobre a Loja para Ciclistas: • Especialistas em artigos para ciclismo. • Produtos de qualidade e pronta entrega. • Atendimento de segunda a quinta, das 8h às 18h e sexta das 8h às 17h. LOJA PARA CICLISTAS – O que faltava para o seu pedal está aqui!', 119.9, 99.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Sets', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjikjkjujmrn8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379576060%2F19568514148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
