INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21971439704', 'Cobertura Top Chocolate Meio Amargo em Barra 1,01kg Harald', 'É o tamanho ideal para quem faz e vende bombons, trufas, pães de mel e ovos de Páscoa. Cada quadradinho da barra tem em média 105 g, para que você possa calcular as suas receitas sempre com um pouco de sobra. Durante o derretimento, controle para que a cobertura não ultrapasse os 50 °C, temperatura em que o açúcar começa a queimar, comprometendo a fluidez. Banhe pães de mel, trufas ou molde bombons e ovos de Páscoa com o Top entre 38 °C e 42 °C. Depois, leve as peças à geladeira até que sequem ou até que o molde fique opaco, garantindo brilho e estabilidade. Utilize sempre um termômetro culinário para garantir que o manuseio foi correto e veja aqui a técnica para derreter a cobertura com facilidade! Derretimento: 45 °C a 50 °C Temperatura de uso: 38 °C a 42 °C ALÉRGICOS: CONTÉM DERIVADOS DE LEITE E DE SOJA. CONTÉM LACTOSE. NÃO CONTÉM GLÚTEN. Ingredientes: açúcar, gordura vegetal, cacau em pó, leite integral em pó, emulsificantes: lecitina de soja e ésteres de ácido ricinoléico interesterificado com poliglicerol e aromatizante. Informação Nutricional: Porção de 25g: Valor energético: 136kcal=545kj; carboidratos: 14g; proteínas: 0,8g; gorduras totais: 8,5g; gorduras saturadas: 8g; gorduras trans: 0,1g; fibra alimentar: 1,2g; sódio: 2,3mg. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor.', 61.99, 61.99, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lzz3b6809itx6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F21971439704', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
