INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14210365632', 'Kit com 3 potes de Esferas de Aço Rossi 6mm (Cada Pote com 100Un)', 'LOJA CORDILHEIRA SPORT! 300 UNIDADES DE ESFERA DE AÇO ROSSI 6MM Descrição: Esferas Aço 6mm (100 unidades) Rossi Essas são munições confeccionadas em aço e em formato de esfera. São compatíveis com Armas de cano sem raias de calibre 6mm. Opção perfeita para atiradores que procuram treinar utilizando munição de alta qualidade e excelente custo benefício. Características: Marca: Rossi Calibre: 6mm Material: Aço Formato da munição: Redonda Compatível com Armas de cano liso Quantidade por pote: 100 unidades Energia Cinética: 1 J Peso: 0.94g Itens Inclusos: 03 Pote de Esferas de Aço Rossi 6mm 100 unidades Garantia de 7 dias pelo Vendedor. NÃO NECESSITA CR PARA COMPRA! ATENÇÃO!!!!! O USO DO PRODUTO EXIGE TREINAMENTO E EQUILÍBRIO EMOCIONAL. DEVERÁ SER GUARDADO EM LUGAR SEGURO E FORA DO ALCANCE DE TERCEIROS. Todos os produtos anunciados estão em estoque a pronta entrega. Só comercializamos produtos NOVOS e com NOTA FISCAL em nome do comprador e com garantia. Prezamos muito o nosso comprometimento com o cliente, todas as perguntas são respondidas o mais rápido possível. COMPRANDO MAIS ITENS DA LOJA VOCÊ TEM DESCONTO NO FRETE!!! VER TODOS OS PRODUTOS DA LOJA EM: “VER MAIS ANÚNCIOS DO VENDEDOR” OU “PERFIL DA LOJA”', 55.0, 53.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mibsf7jeno5dc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443107548%2F14210365632', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19306286121', 'Linha Multifilamento Victoria 4x 100mts Azul - Maruri', 'Linha Multifilamento Victoria 4x 100m Azul – Maruri Desempenho superior e resistência garantida, a linha multifilamento Victoria 4x da Maruri é ideal para pescadores exigentes que buscam eficiência e durabilidade. Com estrutura trançada em 4 fios de polietileno 100%, ela oferece excelente resistência à abrasão e à tensão, mesmo em ambientes com estruturas rígidas ou pedras. Mais sensibilidade e controle a cada arremesso. Sua superfície extremamente macia proporciona menor atrito nos passadores, resultando em lançamentos mais longos e precisos. Além disso, o design da linha sem efeito memória permite que ela mantenha o desempenho mesmo após longos períodos de uso, evitando deformações e facilitando o manuseio durante as pescarias. Versatilidade com alta performance. A Victoria 4x está disponível na cor azul — ideal para águas claras ou ambientes com pouca iluminação — e também nas versões amarela e verde, adaptando-se a diferentes condições de pesca. Embalada em formato compacto com cinco carretéis, é perfeita para transportar com praticidade e repor sempre que necessário, garantindo preparo constante para os desafios da pesca esportiva. Especificações Marca: Maruri Modelo: Victoria 4x Tipo: Multifilamento (4 fios) Comprimento: 100 metros Material: 100% Polietileno Alta resistência à abrasão e tensão Sem efeito memória Superfície extremamente macia Resistência: 0,14mm: 22lbs 10kgs 0,18mm: 24lbs 11kgs 0,20mm: 29lbs 13,2kgs 0,24mm: 35lbs 15,9kgs 0,27mm: 39lbs 17,7lbs 0,30mm: 44lbs 20kgs 0,34mm: 48lbs 21,8kgs 0,40mm: 53lbs 24,1kgs 0,45mm: 65lbs 29,5kgs', 33.9, 33.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8lt1cqvw4xdb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F335160199%2F19306286121', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697314107', 'Organizador de Geladeira Porta Saladas Clear Fresh - Ou', 'Organizador Clear Fresh Com Cestos Natural - Ou O Organizador de Geladeira Clear Fresh proporciona frescor prolongado aos alimentos, promovendo uma rotina mais saudável e reduzindo desperdícios. Seu sistema de ventilação mantém o nível de umidade ideal para cada alimento, enquanto os cestos evitam que frutas, verduras e legumes fiquem molhados após a lavagem, aumentando a durabilidade. Experimente a sensação de frescor em uma vida leve, saudável e organizada. Sua transparência facilita a visualização dos alimentos, contribuindo para a organização do ambiente. Fabricado em material resistente (PS Transparente), o organizador garante durabilidade, praticidade e fácil higienização. Transparência, beleza e cuidado com o alimento definem a linha Clear Fresh, ideal para auxiliar na organização da geladeira e simplificar o dia a dia. Não levar ao micro-ondas, não levar ao freezer, não levar à lava-louças. BPA Free. Lavar com sabão neutro e esponja macia. Especificações Marca: Ou Material: Poliestireno e Polipropileno Modelo: Organizador Clear Fresh Tamanhos: 5L 3 Cestos: Medidas: 30 x 15 x 13cm Capacidade: 5 litros Peso Aproximado: 635g 2,2L 2 Cestos: Medidas: 20 x 15 x 9,5 cm Capacidade 2,2 litros Peso Aproximado: 333g 2,2L: Medidas: 20 x 15 x 9,5 cm Capacidade: 2,2 litros Peso Aproximado: 310g', 106.9, 49.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7mfrqmki81u8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F335160199%2F22697314107', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
