INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28879671355', 'Colar Cadeado com pingente de coração Vazado em Prata 925 45cm Feminino', 'Colar Feminino com Pingente Coração Vazado em Prata 925 - Corrente Cadeado 45cm Expresse seu charme e delicadeza com este lindo colar em prata legítima 925, acompanhado por um elegante pingente de coração vazado. A corrente modelo cadeado com 45cm é perfeita para uso diário ou em ocasiões especiais, garantindo um visual delicado e sofisticado. Principais Características: Material: Prata legítima 925 Pingente: Coração vazado, elegante e charmoso Corrente: Modelo cadeado com comprimento de 45cm Ideal para presentear quem você ama ou se presentear Inclui Certificado de Garantia Permanente do teor da prata Garanta já o seu colar de coração vazado em prata 925 e leve consigo a beleza clássica que nunca sai de moda! Não acompanha caixinha de veludo, mas a vendemos a parte :)', 69.9, 64.9, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7cc10w1ndccfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316436073%2F28879671355', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208161121', 'Tênis Feminino em Couro Confortável Casual Ajuste com Elástico Comfortflex 2565308', 'ATENÇÃO!!! POR FAVOR CONFERIR A TABELA DE MEDIDAS NO FINAL DA DESCRIÇÃO E NAS FOTOS DO ANÚNCIO! Tênis Feminino Couro Comfortflex Casual Elástico Confortável Praticidade, conforto e estilo para todos os momentos. Design moderno e funcional: Esse tênis Comfortflex traz um visual clean e versátil, com detalhe em elástico no lugar do cadarço, garantindo mais praticidade no calce e um ajuste confortável aos pés. Conforto que acompanha o seu dia: Confeccionado em couro, oferece maior durabilidade e sofisticação. A palmilha confortável proporciona maciez a cada passo, enquanto o forro bactericida ajuda a manter os pés mais frescos e protegidos. Praticidade no uso: O modelo com elásticos facilita o calce, sendo ideal para a correria do dia a dia sem abrir mão do estilo. Principais características: Couro legítimo de alta qualidade; Fechamento em elástico, prático e funcional; Palmilha confortável para maior bem-estar; Forro bactericida que auxilia na higiene interna; Solado leve e resistente; Design casual e versátil Perfeito para diversas combinações: Ideal para looks casuais, combinando com jeans, vestidos ou peças mais despojadas, sendo uma ótima escolha para o dia a dia. Dica de conservação: Limpar com pano macio levemente úmido e utilizar produtos específicos para couro para manter a aparência e durabilidade. Palavras-chave estratégicas: tenis feminino couro comfortflex, tenis feminino casual confortavel, tenis com elastico feminino, tenis branco comfortflex, tenis feminino dia a dia couro Um modelo que une praticidade, conforto e qualidade Comfortflex para te acompanhar em qualquer ocasião! MEDIDAS: 34 - 22,8 CM 35 - 23,5 CM 36 - 24,1 CM 37 - 24,8 CM 38 - 25,4 CM 39 - 26,1 CM 40 