INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394216200', 'Kit 2x Pré-Treino 300G - Diabo Verde - FTW', 'Seu treino insano Deixe seu treino insano com um poderoso #Pre-Workout com 200mg de cafeína. Em sua composição encontramos aminoácidos não essenciais como a alanina, a arginina e a taurina. Além de sua base, potente: a cafeína, que auxilia no aumento da performance no desempenho de exercícios físicos de resistência,. O que é o Diabo Verde #Pre-workout FTW Cada substância escolhida para o Diabo Verde Insano FTW, foi pensada exclusivamente para o melhor desempenho das vias metabólicas do nosso organismo. Diabo Verde Insano FTW é a combinação perfeita para o seu treino! Como tomar A melhor maneira de como consumir o Diabo Verde Insano FTW dependerá de cada caso. Por isso, é necessário consultar um profissional da saúde para acrescentar esse produto em sua rotina. Dessa forma irá depender da demanda do organismo de cada um. De qualquer forma em nossa embalagem recomendamos diluir 10g (2 medidas dosadoras) em 1 copo contendo 200ml de água gelada ou suco de preferência. Ingredientes Isomaltulose, Beta-alanina, L- arginina, L-tirosina, cafeína microencapsulada, fibra de beterraba, D-ribose, antiumectante fosfato tricálcico, acidulante ácido cítrico, edulcorantes sucralose e acesulfame potássico, corante e aromatizante idêntico ao natural. Sugestão de consumo Diluir 10g (2 medidas dosadoras) em 1 copo contendo 200ml de água gelada ou suco de preferência. Diferenciais Não contém glúten. Atenção Não ultrapassar a dose diária recomendada. Apresentação Pote com 300g', 209.0, 129.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhjfkam1rmkm5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1397772996%2F22394216200', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
