INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57951411191', 'Par/Un Farol Dianteiro Celta 2000 2001 2002 2003 á 2006 Cromado FAROLETE MILHA NEBLINA INFERIOR', 'Par/Un Farol Dianteiro Celta 2000 2001 2002 03 á 2006 Cromado DESCRIÇÃO DO PRODUTO Os faróis, sejam de luz baixa ou alta, tem como função iluminar o caminho de um veículo. Nesse sentido, é importante que os condutores saibam como fazer a regulagem correta dos faróis, pois um farol desregulado não ilumina adequadamente a rodovia ou ainda pode causar ofuscamento, perda de visão momentânea, no condutor do veículo que transita em sentido contrário. ESPECIFICAÇÕES DO PRODUTO: - Carcaça de Plástico Resistente - Cromado - Foco Simples - Lente Lisa - Encaixe da lâmpada H4 Compatível com: - Celta 2000 - Celta 2001 - Celta 2002 - Celta 2003 - Celta 2004 - Celta 2005 - Celta 2006 O QUE VEM NA EMBALAGEM Conteúdo da Embalagem: PAR: Conteúdo da Embalagem: • 01 Parabarro Dianteiro Direito • 01 Parabarro Dianteiro Esquerdo OU UNIDADE: • 01 Parabarro Dianteiro FINALIZAÇÃO As imagens representam o real estado de conservação dos produtos. Detalhes técnicos e funcionalidades podem ser obtidos no chat! Compare o produto anunciado com o seu modelo de referência. Postaremos a sua mercadoria dentro de algumas horas após a confirmação da compra Não esqueça! Tire todas as suas dúvidas conosco antes de comprar o seu produto. Auto Peças Nova Kennedy Agradece sua preferência!', 204.9, 140.95, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-81zto-ml23dz467d36b1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F494312426%2F57951411191', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
