INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255222478', 'Jogo De Brocas Aço Rápido 3,0 À 8,0mm Titânio Mtx', 'C-JAÚ FERRAMENTAS A QUALIDADE É A NOSSA MELHOR FERRAMENTA! ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ MERCADO LÍDER PLATINUM! QUALIDADE TAMBÉM NO SITE E NA LOJA FÍSICA. ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ CARACTERÍSTICAS: Brocas para metal feitas de aço de corte rápido da marca MTX, com revestimento de nitreto de titânio; Revestimento de nitreto de titânio aumenta a durabilidade da ferramenta; Superfície da broca tem dureza aumentada e coeficiente de fricção reduzido, que melhora consideravelmente caraterísticas da ferramenta; Para metais ferrosos e não ferrosos; Ângulo de afiação de ponta de 118º; CONTEÚDO: 01 Broca 3,0mm; 01 Broca 4,0mm; 01 Broca 5,0mm; 01 Broca 6,0mm; 01 Broca 8,0mm; Estojo de Armazenamento.', 25.8, 25.8, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81ztl-mko8ndds24n57b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380456261%2F58255222478', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298166307', 'Adesivo Araldite Hobby 16g Tekbond', 'O Adesivo Araldite Hobby 16g 10min Tekbond é uma cola epóxi versátil e de rápida secagem, indicada para uso profissional e doméstico. Ideal para reparos e colagens em pequenas superfícies lisas, porosas ou irregulares, como madeira, vidro, concreto, pedras, metais e a maioria dos plásticos rígidos. Resiste a temperaturas de até 70°C, com cura inicial em 10 minutos e total em 8 horas. Vantagens: - Secagem rápida, com tempo inicial de 10 minutos; - Alta resistência e durabilidade; - Versátil para diversos materiais e aplicações; - Fácil de aplicar com o misturador incluso; - Adequado para uso profissional e doméstico. Características técnicas: Marca: Tekbond Modelo: Araldite Hobby Tipo: Cola Epóxi Peso: 16g Cura Inicial: 10 minutos Cura Total: 8 horas Composição: Resina epóxi e endurecedor Modo de Uso: Limpe as superfícies, garantindo que estejam isentas de poeira, oleosidade e resíduos. Remova os lacres da seringa e pressione até liberar a quantidade desejada. Misture os componentes até obter uma solução homogênea. Aplique a mistura em até 5 minutos nas partes a serem coladas. Pressione as peças e aguarde a secagem completa de 8 horas. Observações: Não indicado para plásticos como polipropileno, polietileno e Nylon®. Armazene em local seco e seguro, mantendo a tampa na posição correta para evitar colagem. Garantia: - 3 meses contra defeitos de fabricação.', 55.9, 38.9, NULL, 'Home & Living > Tools & Home Improvement > Industrial Adhesives & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-7rcc8-m6ilk6yssh3v90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F23298166307', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
