INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207698324', 'Kit Com 30 Joelho 90° Soldável Com Rosca Lr 25Mm X 3/4" 484 Krona Conexão Hidráulica PVC', 'O Joelho 90° Soldável com Rosca LR Krona é utilizado em instalações hidráulicas para mudança de direção da tubulação com transição entre conexão soldável e roscável. Indicado para sistemas de água fria, oferece vedação eficiente e encaixe seguro. Características: • Conexão soldável com rosca fêmea • Mudança de direção em 90 graus • Indicado para água fria FICHA TECNICA: Marca: Krona Modelo: Soldável com Rosca LR Ângulo: 90 graus Material: PVC Aplicação: Instalação hidráulica Uso indicado: Água fria Tipo de conexão: Soldável e roscável Modelos disponíveis: 20mm x 1/2" – Cód. 483 25mm x 1/2" – Cód. 485 25mm x 3/4" – Cód. 484 32mm x 3/4" – Cód. 486', 207.0, 98.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/br-11134207-820lg-moprrx5fq2v446', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F58207698324', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
