:00 AS 18:18HR.', 235.25, 218.78, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lpb576lvgs5h59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F600316498%2F20997507674', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793492684', 'Chinelo Aramis Lines Masculino', 'FOOT ONE TAMANHOS DISPONÍVEIS 33/34 - Selecione 34 35/36 - Selecione 36 37/38 - Selecione 38 39/40 - Selecione 40 41/42 - Selecione 42 43/44 - Selecione 44 45/46 - Selecione 46 Lembre-se de que, geralmente, os chinelos tendem a ficar mais justos no início, e é recomendado escolher uma numeração um pouco maior do que a sua numeração habitual. Isso ajuda a garantir mais conforto e evitar problemas de tamanho. Caso tenha dúvidas sobre a numeração ideal, nossa equipe está à disposição para ajudar! DESCRIÇÃO DO PRODUTO: Chinelo Aramis Lines Masculino Chinelo confeccionado em borracha, possui sola em textura decorativa, logotipo contrastantes. ESPECIFICAÇÕES: Marca: Aramis Modelo: ARM1140 Cor: Preto Gênero: Masculino Indicação: Casual ITENS INCLUSOS: 01 - Par de Chinelo', 97.99, 97.99, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-7rbmd-m5k1x4ytg4u8bf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F396321395%2F23793492684', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
