INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43414298633', 'Prensa Térmica Canecas 11 A20oz Copo Sublimação 110v/220v Rosa Azul Prensa Térmica Sublimação Caneca', '☕ Prensa Térmica para Canecas Mecolour 350W – Tela Touch | 2 Canecas de 11oz ou 1 Copo de 20oz Transforme canecas e copos personalizados com qualidade profissional! Ideal para empreendedores, lojas de brindes, sublimação personalizada e trabalhos artesanais. ✅ Principais Vantagens ✔ Prensa 2 em 1: prensa duas canecas de 11oz simultaneamente ou um copo tumbler de 20oz ✔Certifique-se de que não haja espaços entre os dois copos, caso contrário, formarão bolhas de ar. ✔ Tela Touch Screen moderna e intuitiva ✔ Controle preciso de temperatura e tempo ✔ Aquecimento uniforme para estampas mais nítidas ✔ Estrutura reforçada em aço para maior durabilidade ✔ Ideal para iniciantes e profissionais 🔥 Alta Eficiência para Produção Com capacidade para prensar duas canecas ao mesmo tempo, a produtividade aumenta significativamente, reduzindo o tempo de produção e melhorando os resultados. Certifique-se de que não haja espaços entre os dois copos, caso contrário, formarão bolhas de ar. A função de contagem permite acompanhar a quantidade de peças produzidas, facilitando o gerenciamento do trabalho. Além disso, após 30 minutos sem operação, a máquina entra automaticamente em modo de espera para economia de energia. 🎯 Compatível com • Canecas de 11oz • Canecas de 15oz • Copos Tumbler de 20oz • Copos retos com diâmetro entre 7 e 8 cm • Altura máxima de até 23,5 cm 🌡 Controle Inteligente • Temperatura ajustável: 0°C a 200°C • Sistema Celsius e Fahrenheit • Temporizador: 0 a 999 segundos • Alarme automático ao término do processo • Controle digital de alta precisão ⚙️ Características Técnicas • Marca: Mecolour • Modelo: Prensa para Canecas Dupla • Potência: 350W • Tensão: 110V • Tela: Touch Screen • Tamanho da resistência: 22 x 23,5 cm • Comprimento do cabo: 180 cm • Cor: Verde • Material da estrutura: Aço reforçado 📏 Dimensões • Caixa: 45 x 36,5 x 27,5 cm • Peso líquido: 8,5 kg • Peso bruto: 9,25 kg 📦 Conteúdo da Embalagem • 1 Prensa Térmica Mecolour • 1 Cabo de alimentação • 1 Manual de instruções 🏆 Certificações ✔ CE ✔ ROHS ✔ FCC ⚠ Observações Importantes • Pequenas folgas mecânicas são normais e necessárias para garantir a pressão correta durante a prensagem. • Para copos tipo tumbler, recomenda-se reposicionar o copo e realizar uma segunda prensagem para obter cobertura completa da impressão.', 999.0, 699.0, NULL, 'Computers & Accessories > Office Equipment > Others', 'https://cf.shopee.com.br/file/br-11134207-820l6-mqhhqrex4c8z56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1049850872%2F43414298633', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892573943', 'Mangueira Radiador Fiat Uno 1991 a 1999 - 102774 - 908256', 'Mangueira Radiador Fiat Uno 1991 a 1999 102774 908256 Superior Radiador MTR 1.0/1.5/1.5 SPI O liquido entra no radiador pela "mangueira superior", em geral conectada na parte de cima do radiador. A medida que o liquido desce, ele passa por canais no radiador resfriados por meio de passagem do ar pelas aletas de refrigeração entre os canais. Depois ser resfriado, o liquido sai do radiador pela "mangueira inferior". Em geral, há uma mola dentro dessa mangueira para evitar que ela quebre quando a bomba de agua puxa o liquido do radiador.', 32.26, 32.26, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-823rh-moydnfbx3klddf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22892573943', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497475658', 'Regulador Freio Gm Prisma 2013 a 2017 - 203556 - 289', 'Regulador Freio Gm Prisma 2013 a 2017 203556 289 1.0/1.4 - (AUTOMATICO) (COM ACIONADOR) (1 RODA - TRASEIRA - LADO ESQUERDO) (SISTEMA VARGA) Compensa o desgaste das lonas, mantendo as sapatas sempre próximas ao tambor. Aplica nas rodas traseiras. Mas também nas rodas dianteiras, com freio a tambor dianteiro. Para regulagem automática, a peça fica entre as sapatas, presa por molas e com o auxilio (ou não) dos acionadores compensa o desgaste das lonas. Ocorre quando pedal de freio é acionado. Regulagem manual, ajuste deve ser feito manualmente por um mecânico. _x000D_ Fabricado em aço, com componentes em aço inox e materiais sinterizados.', 43.3, 43.3, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd6j-luja9fwx7ttf4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22497475658', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
