INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53061301165', 'Assadeira Redonda Brasil em Alumínio Antiaderente Bege (27805/333) - Tramontina', 'A Assadeira Redonda Brasil em Alumínio Antiaderente Bege (27805/333) - Tramontina, conta com revestimento interno e externo antiaderente Starflon Max bege 24 centímetros / 2,1 litros é uma boa auxiliar para tornar suas receitas ainda mais saborosas! Produzida em alumínio com revestimento interno e externo em antiaderente Starflon Max, ela garante que as receitas assem de maneira rápida e uniforme sem que grudem em sua superfície, é mais durável e não é prejudicial a sua saúde. É uma peça super prática em sua cozinha, podendo ser utilizada para preparar diversos tipos de receitas, doces ou salgadas, e ser lavada na máquina de lavar louças. Um item Tramontina perfeito para você preparar suas melhores receitas! Descrição do Produto: • Corpo de alumínio com espessura de 0,8 mm que proporciona cozimento rápido e uniforme. • Revestimento interno e externo de antiaderente Starflon Max que não gruda, é fácil de limpar, mais durável e não é prejudicial à saúde, pois é livre de PFOA. • Pode ir à máquina de lavar louças facilitando seu dia a dia. Referência: 27805/333 . Cód. de Fábrica: 27805/333. Marca: Tramontina.', 41.9, 39.3, NULL, 'Home & Living > Kitchenware > Bakewares & Decorations', 'https://cf.shopee.com.br/file/sg-11134201-823pi-mosbwzvj711dd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F53061301165', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
