INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21298522059', 'Parafuso Caixa De Luz 6X1.1/2" Caixa 200 Unidades Jomarca', 'Parafuso ideal para aplicação da caixa de luz por causa do seu corpo alongado, conseguindo chegar ao encaixe na sua caixa de luz com mais facilidade. O parafuso caixa de luz 69/64x3" é comumente utilizado na fixação de caixas elétricas ou caixas de passagem em estruturas de alvenaria, concreto ou madeira. Ele é especialmente projetado para fixar caixas elétricas em paredes, permitindo a instalação segura de tomadas, interruptores e dispositivos elétricos. Este tipo de parafuso é amplamente utilizado por eletricistas e profissionais da construção civil durante a instalação elétrica residencial ou comercial, pois é específico para fixar caixas elétricas em paredes estruturais, contribuindo para a segurança e estabilidade do sistema elétrico.', 53.9, 37.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qvg8-lgv04u3h4xsz28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F21298522059', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
