INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208037264', 'Sanduicheira Grill Elétrica Sumay 1200W Preto Para 4 Sanduíches Chapa Grande 220V Perfeita Para Sua Cozinha', 'A Sanduicheira Grill Elétrica Sumay 1200W é a escolha ideal para quem busca praticidade e sabor na hora de preparar sanduíches. Com 1200 watts de potência, ela aquece rapidamente e garante um grill perfeito para até 4 sanduíches ao mesmo tempo, permitindo que você prepare o lanche da família ou amigos de forma rápida e eficiente. A chapa grande oferece uma distribuição uniforme de calor, proporcionando uma crocância ideal por fora e um recheio quente e saboroso por dentro. Seu design elegante na cor preta combina com qualquer ambiente de cozinha, e a estrutura compacta facilita o armazenamento, economizando espaço. A voltagem de 220V é perfeita para quem deseja mais eficiência no aquecimento. Seja para o café da manhã, almoço ou lanche da tarde, essa sanduicheira é a ferramenta certa para transformar o simples em um saboroso momento. A facilidade de uso e a praticidade de limpeza tornam a Sanduicheira Grill Sumay 1200W um item indispensável em sua cozinha. Aproveite e experimente o sabor dos seus sanduíches favoritos com um toque profissional!', 284.28, 192.9, NULL, 'Home Appliances > Kitchen Appliances > Toasters', 'https://cf.shopee.com.br/file/br-11134207-820lj-mmixpz9xjqx026', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1720972248%2F58208037264', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
