INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44655622316', 'Colar Prata 925 Pingente Concha com Madrepérola Leve e Atemporal', 'A Gargantilha Concha Madrepérola em Prata 925 é uma joia delicada e elegante, inspirada na beleza natural do mar. O pingente em formato de concha com madrepérola traz brilho suave e sofisticado, criando um visual leve, feminino e atemporal, perfeito para composições refinadas ou com inspiração praiana. - Material: Prata 925 - Pedra: Madrepérola - Detalhe: Pingente concha - Estilo: Delicada e elegante - Tamanho: 45 cm - Fecho: Argola tradicional - Acompanha: Certificado de garantia de autenticidade - Observação: Não acompanha caixinha Uma peça charmosa e versátil, ideal para uso diário, ocasiões especiais ou para quem ama joias com inspiração no mar e elegância natural.', 253.0, 75.9, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/br-11134207-820m8-mmg12le3myo4c7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340468765%2F44655622316', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
