INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23992259320', 'CAIXA DIRECAO ESFERA BURGMAN 125 ATÉ 10', 'Caixas de Direção: As caixas de direção Danidrea são produzidas com um aço especial para rolamentos com altíssima durabilidade. O aço recebe tratamento térmico para alta resistência ao desgaste e o produto contém uma menor área de contato, o que proporciona uma direção mais leve. Suas esferas distribuem a força uniformemente dando ao conjunto o devido ajuste. A caixa de direção é instalada nas partes superior e inferior da caixaria de direção da motocicleta. O comando de direção dado através do guidão é levado a caixaria de direção, que por sua vez, movimenta toda a coluna de suspensão, roda e pneu possibilitando a direção da motocicleta. Aplicações: - BURGMAN 125 ATÉ 2010 BURGMAN 125 ATÉ 10', 68.8, 68.8, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lugryzz9v9lo84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F362325018%2F23992259320', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
