INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19098027465', 'Tiara De Anjo Vermelha Simples Com Plumas', 'Transforme-se em um anjo ousado com esta tiara vermelha decorada com plumas. Um acessório leve e charmoso para completar sua fantasia. A Tiara de Anjo Vermelha com Plumas é o acessório perfeito para quem deseja destacar sua fantasia com um toque especial. Seu design leve e confortável garante um uso prolongado em festas, eventos temáticos e até mesmo para brincadeiras. Combina perfeitamente com fantasias de anjo ou outras propostas criativas. Diferenciais Decorada com plumas macias para um visual delicado. Base confortável que se ajusta à cabeça. Ideal para festas temáticas e fantasias criativas. Dicas de Uso Combine com uma fantasia de anjo vermelho ou demônio para um visual impactante. Ideal para festas à fantasia, Carnaval ou Halloween. Use com maquiagem brilhante ou tons vermelhos para destacar o look.. Garantia: 30 Dias Genero: Unissex IDADE: adult GENDER: unisex Codigo do Produto: 91305 Itens Inclusos: 1 Tiara Descrição: Tiara de Anjo Branca Simples Tamanhos: Único', 19.99, 19.99, NULL, 'Fashion Accessories > Hats & Caps', 'https://cf.shopee.com.br/file/sg-11134201-7rbn7-m5u2ig1wukta21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F410794727%2F19098027465', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398141709', 'Estanho Cartelado 20gr 1,2mm 60 X 40 - Vonder - 74 38 604 020', 'Estanho Cartelado 20gr 1,2mm 60 X 40 - Vonder - 74 38 604 020 Indicado para soldar componentes eletrnicos. Possui fluxo RA composto por resina, solvente e ativadores agressivos para superfcies moderadamente oxidadas. O resduo de fluxo RA corrosivo e dever ser removido logo que possvel aps a refuso para evitar danos na sua montagem. O fluxo do tipo "RA" indicado para remover o filme de xido superficial do cobre, lato, bronze e bases estanhadas. ESPECIFICAES TCNICAS: Dimetro do estanho em fio:1,2 mm Composio do estanho em fio:60 x 40 Percentual de estanho:60% Percentual de chumbo do estanho em fio:40% Cor:Chumbo Comprimento aproximado:1 metro cada cartela 2 Cartelas com 10 g cada Imagem Meramente Ilustrativa', 22.22, 22.22, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7ra3v-m54fp5et7cs4a5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1096473040%2F23398141709', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298849477', 'Removedor de Fuligem de Freios em Spray Descontaminante ferroso Izer 500ml Vonixx', 'Removedor de Fuligem de Freios em Spray Descontaminante ferroso Izer 500ml Vonixx - 2011040 Izer Descontaminante Ferroso 500ml Vonixxé um descontaminante ferroso de pH neutro que remove fuligem de freio oxidado em rodas, age na eliminação de oxidação de material ferroso da pintura e demais partes externas do veículo e ajuda na remoção de pontos de ferrugem em partes cromadas. No motor, auxilia na remoção da oxidação de partes metálicas, deixando-o com aspecto renovado. O produto não é indicado para uso em superfícies zincadas. DILUIÇÃO: Pronto uso em ambas as versões. INFORMAÇÕES ADICIONAIS: Izer também pode ser usado para descontaminação de pintura, em diluição até 1:1.Ao descontaminar a pintura com Izer, não de dispensa a descontaminação com V-Bar e V-Lub.Izer também age na remoção de ferrugem.Não aplicar Izer em superfície aquecida ou sob o sol. PH NEUTRO REMOVE FERRO OXIDADOO DOR REDUZIDO Quantidade: 500ml Imagens Meramente Ilustrativas', 53.67, 53.67, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Degreasers', 'https://cf.shopee.com.br/file/sg-11134201-7rdxc-mdnox5gd4aahf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1096473040%2F22298849477', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
