INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794387778', 'Kit 2 Loção de Limpeza Leite de Colônia Original 200ml', 'LEITE DE COLÔNIA ORIGINAL Para todos os tipos de pele. Loção de limpeza. Adstringente. Limpa profundamente os poros. Limpeza adstringente que ajuda a controlar a oleosidade da pele, limpa profundamente os poros e facilita a respiração da pele. Resultado: Pele limpa e perfumada. Modo de usar: Agite bem antes de usar. Aplique sobre a pele, com algodão ou com as mãos. Não é necessário enxaguar.', 26.58, 26.58, NULL, 'Beauty > Skincare > Facial Cleanser', 'https://cf.shopee.com.br/file/sg-11134201-8258f-mqmp9jkt3j0s80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23794387778', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697579779', 'Kit 3 Creme Dental Close Up Tripla Proteção Hortelã 70g', '• O Creme Dental Closeup Tripla Proteção Hortelã proporciona dentes 10x mais fortes • Sua fórmula possui tripla proteção: anticáries, dentes brancos e hálito fresco • O flúor bioativo previne às cáries • O cálcio presente no Creme Dental Closeup Tripla Proteção Hortelã ajuda a fortalecer os dentes • Essa pasta de dente ajuda na remoção de manchas da superfície dos dentes, deixando-os mais brancos • Sabor refrescante de hortelã O Creme Dental Closeup Tripla Proteção Hortelã possui uma fórmula com cálcio e flúor bioativo que proporciona dentes 10x fortes. Além da tripla proteção que garante dentes brancos, proteção anticáries e hálito fresco. Sua fórmula promove uma limpeza eficaz, oferecendo um hálito fresco e duradouro. O flúor bioativo previne às cáries, enquanto o cálcio auxilia no fortalecimento dos dentes. Além disso, a pasta de dente Closeup Tripla Proteção Hortelã ajuda na remoção de manchas da superfície dos dentes, deixando-os mais brancos a cada escovação. O sabor do Tripla Proteção Hortelã apresenta notas de um tipo de hortelã (peppermint arvensis) acrescentadas de um toque de notas doces de baunilha. Essa combinação proporciona uma prazerosa sensação de frescor. Hálito fresco, dentes brancos, proteção anticáries e dentes 10x mais fortes para você ter confiança de chegar mais perto. O Creme Dental Closeup Tripla Proteção Hortelã está disponível no tamanho de 70 g. Experimente também as outras variedades de Closeup Tripla Proteção: Menta e Menta Americana. Ao escovar seus dentes todos os dias após as refeições com creme dental, escova de dentes e enxaguante bucal Closeup, você os protege contra as bactérias e o mau hálito. A Federação Dental Internacional reconhece que escovar os dentes duas vezes por dia com um creme dental com flúor como “Closeup Tripla Proteção Hortelã” é benéfico para a saúde bucal. Estudo in-vitro, após 21 dias de uso do produto, comparado com o primeiro dia de uso.', 10.47, 10.47, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-8261c-mmhnon8k6tqn61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23697579779', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19297684074', 'Locao Hidratante Facial Cetaphil com Acido Hialuronico 88ml', 'Hidratante facial diário, com o exclusivo ácido hialurônico Hyacare 50, que penetra nas camadas mais profundas da pele. Maior hidratação e revitalização da pele. Possui textura leve e rápida absorção, não oleosa. Garante hidratação imediata e prolongada por 24h. Apresenta fórmula exclusiva capaz de atuar nas camadas mais profundas da pele, promove revitalização intensa e pode ser utilizado antes da maquiagem.', 122.49, 122.49, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-7rd44-lvar3fzg2kxjf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F19297684074', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094307700', 'Vela de Ignição NGK TR5-1 Ford Mustang, Escort - Cód.126', 'As velas NGK necessitam de baixa tensão do sistema de ignição, grande ignibilidade e performance frente as velas convencionais, maior economia de combustível e menor emissão de poluentes, com desempenho superior. *Valor referente a unidade. Características Diâmetro da Rosca - 14 mm Comprimento da Rosca - 18 mm (.709") Sextavado - 16 mm (5/8") Gap - 1 mm (.039") Aplicação: Isuzu Hombre 2.2 (97...00) Ford Aerostar (86...87) / Escort (83...90) / Mustang (83...90) / Ranger (83...88)', 29.65, 29.65, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rdy6-mcv1fj6x3ihge4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F634548170%2F22094307700', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22891671632', 'Kit 2 Hydraporin AI Loção Hidratante 120ml', 'HYDRAPORIN AI LOÇÃO HIDRATANTE Peles Secas e Extrassecas Hipoalergênico Dermatologicamente e Oftalmologicamente testado. Hydraporin AI é um hidratante intensivo que repara a barreira cutânea e promove hidratação intensa para peles secas, extrassecas e sensíveis . A fórmula exclusiva de Hydraporin AI possui o Bioskin, ativo com ação probiótica que age diretamente no equilíbrio do microbioma da pele e o AI Complex, complexo de ativos com ação anti-inflamatória e calmante. O produto promove 24 horas de hidratação, com textura altamente hidratante e não pegajosa. Sem fragrância, corantes e parabenos. Hydraporin AI é um hidratante de uso corporal e facial , com ingredientes de ação calmante e reparador para peles secas e extremamente secas, melhorando ainda as manifestações características da pele irritada. Sua fórmula foi desenvolvida com os mais modernos e eficazes ingredientes que atendem as necessidades desse tipo de pele. Hydraporin AI hidrata e promove a reparação de barreira por até 24 horas, mantém o pH fisiológico e alivia rapidamente a coceira e descamação associadas ao ressecamento da pele. Não contém fragrância, corantes nem parabenos. Sua cosmética absorve rapidamente sem deixar a pele pegajosa. Modo de Usar: Aplicar o produto massageando suavemente sobre a pele limpa, de preferência após o banho, ou a critério médico. Precauções: Produto hipoalergênico (formulado de maneira a minimizar o possível surgimento de alergias), não acnegênico (não provoca acne) e não comedogênico (não provoca cravos). Em caso de irritação ou alergia, descontinuar o uso do produto, caso persista, procure assistência médica. Não ingerir. Em caso de contato acidental com os olhos, enxaguar abundantemente. Uso adulto e externo. Conservar em temperatura ambiente, proteger da luz, MANTER FORA DO ALCANCE DAS CRIANÇAS.', 218.98, 218.98, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-823p9-mojytzptocuk0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F22891671632', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893009601', 'Sabonete Liquido Protex Baby Glicerina Natural 400ml', 'O novo sabonete líquido para bebê da cabeça aos pés Protex Baby (400ml) , com glicerina de origem natural, é ideal para o cuidado dos pequenos graças a sua fórmula com ingredientes naturais. Além disso, não contém álcool, corantes e parabenos. Este sabonete glicerinado, com PH balanceado e fragrância biodegradável, ajuda a hidratar a pele e o cabelo do seu bebê de maneira natural, mantendo sua barreira protetora para uma pele saudável e macia. Proteja a pele na hora do banho do bebê com esse sabonete líquido Protex Baby Glicerina ideal para o cuidado da pele dos pequenos. Testado por pediatras e dermatologistas.', 34.39, 34.39, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7rd6m-lvawso32hb6m06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F22893009601', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53900176411', 'Lixadeira De Cinta 1000w Liv1200 Lixa Para Madeira Vonder', '***PRODUTO PRONTA ENTREGA COM ENVIO IMEDIATO*** PRODUTO ORIGINAL COM NOTA FISCAL 1 Lixadeira de cinta. Acompanha: 1 coletor de pó e 1 lixa de cinta. Possui cabo emborrachado para maior conforto e motor com dupla isolação, que proporciona mais segurança. Indicada para lixar madeiras em geral. Garantia legal: 90 dias + Garantia contratual: 9 meses (Para locadoras, garantia única e exclusiva de 90 dias) Modelo:LIV 1200 Potência:1.000 W Dimensões da lixa:100 X 610 mm Velocidade:450 m/min Coletor de pó:Sim Tensão:127 V~ Frequência:50 Hz / 60 Hz Segue norma:ABNT NBR IEC 60745-1 e ABNT NBR IEC 60745-2-4 Massa aproximada.:6,2 kg Massa aproximada (peso):6,2 kg', 1019.9, 803.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-825ah-mga1sws25cem78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F53900176411', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
