INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798949543', 'Registro De Esfera Semi Plena 2 Polegada Em Alumínio Bremen', 'O Registro De Esfera 2 Polegada Em Alumínio Bremen é um produto de alta qualidade, projetado para atender às suas necessidades de controle de fluxo de líquidos. Com um design robusto e durável, este registro de esfera é feito de alumínio resistente, garantindo uma longa vida útil e desempenho confiável. Este produto é fácil de instalar e operar, tornando-o uma escolha ideal para uma variedade de aplicações. O Registro De Esfera 2 Polegada Em Alumínio Bremen é compatível com uma ampla gama de sistemas de tubulação, proporcionando flexibilidade e conveniência. O modelo 3460 da Bremen é conhecido pela sua eficiência e confiabilidade. Este registro de esfera é uma excelente escolha para quem busca um produto de qualidade superior que ofereça um excelente desempenho. Em resumo, o Registro De Esfera 2 Polegada Em Alumínio Bremen é um produto de alta qualidade que oferece durabilidade, facilidade de uso e desempenho confiável. É a escolha perfeita para todas as suas necessidades de controle de fluxo de líquidos. Garantia de fábrica: 3 meses', 152.0, 152.0, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf8cgr19tjbbbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380456261%2F22798949543', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
