INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093614619', 'Coleção Cute & Cute Coloring Book for Adults Especial - Kit com 3 Livros de Colorir', 'Se o seu hobby é pintar, a Coleção Cute & Cute Coloring Book for Adults Especial - Kit com 3 Livros de Colorir é a escolha perfeita para você! Este estilo de colorir, sucesso no TikTok, são 3 livros com 32 ilustrações encantadoras para preencher com lápis de cor ou marcadores. Um presente ideal para você, para familiares ou aquele amigo que também adora colorir. Destaques do Cute & Cute - Coloring Book for Adults: Cada livro traz 32 ilustrações originais: Cada página é desenhada à mão, pronta para colorir Desenhos amplos e de fácil preenchimento: Proporciona uma experiência relaxante e envolvente Tamanho confortável (21,0 x 21,0 cm): Perfeito para manuseio fácil e prático Alta resolução: Impressões nítidas e detalhadas para um resultado incrível. Deixe sua criatividade florescer e aproveite momentos de tranquilidade com o livro que une fofura e leveza em cada página, proporcionando uma experiência relaxante e inspiradora!', 89.7, 19.9, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/sg-11134201-7rfi9-m3v24aqi0k63d4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F22093614619', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
