INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492190825', 'Limpador Multiação Apc 1,5l Vonixx Limpa Banco Painel Teto', 'Limpador Multiação Apc 1,5l Vonixx Limpa Banco Painel Teto DESCRIÇÃO: Este produto é capaz de remover sujeiras de diversas naturezas, incluindo as mais difíceis. Sua fórmula permite limpar com segurança gorduras, manchas e encardidos de bancos, tetos, painéis etc. BENEFÍCIOS: Possui a capacidade de limpar diversos tipos de sujeiras difíceis de maneira segura. MODO DE USAR: 1- Diluir o produto conforme o nível de sujeira; 2- Aplicar o produto, já diluído, com aplicador de espuma; 3- Remover o excesso de produto com um pano de microfibra levemente úmido; 4- Se necessário, repetir a operação. DILUIÇÃO: Para sujeira pesada, a diluição recomendada é 1:1; Para sujeira leve, a diluição recomendada é 1:5.', 32.09, 32.09, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ly2qqt9lavf6de', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944273111%2F23492190825', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
