INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54507808433', 'Selim BMX GTS-K Tipo DDK C/ Carrinho + Par de Punhos Cores', 'O selim BMX GTS-K tipo DDK com carrinho, acompanhado de par de punhos, é ideal para quem busca conforto, resistência e estilo na montagem de bicicletas. Perfeito para uso urbano, freestyle e linha de montagem. Benefícios Principais Selim com design BMX que proporciona conforto e firmeza durante o uso. Estrutura resistente ideal para impactos e uso intenso. Acompanha carrinho para fácil instalação no canote. Punhos inclusos que garantem melhor pegada e controle. Excelente opção para montagem com ótimo custo-benefício. Compatibilidade e Aplicação Indicado para bicicletas BMX, MTB e urbanas. Compatível com canotes padrão com carrinho. Ideal para uso urbano, manobras e projetos de linha de montagem. Especificações Técnicas Produto: Selim + par de punhos Modelo: Tipo DDK Aplicação: BMX, MTB e urbano Fixação: Carrinho padrão Cor: Preto Uso: Linha de montagem e reposição Itens Inclusos 1 Selim BMX com carrinho 1 Par de punhos OGM BIKE: Qualidade e Confiança em Cada Pedalada Na OGM BIKE você encontra componentes selecionados para garantir resistência, conforto e excelente custo-benefício. Ideal para montagem e manutenção de bicicletas com eficiência.', 44.9, 44.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-8261k-mmbtmqgt3ea736', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F990966849%2F54507808433', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
