INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997611224', 'Corneta Curta Hl14-50 Trio Profissional Cromada Jbl', 'Corneta Curta JBL HL14-50 Trio Profissional Preta Com Cromado A Corneta Curta da JBL é o par perfeito para trabalhar com o Driver em Caixa Trio do seu sistema de som! Além de proporcionar áudio de excelente qualidade, agrega um visual mais moderno depois de instalada na caixa, pois apresenta um acabamento incrível nas cores preta com cromado. Esta Corneta Curta foi desenvolvida em alumínio rígido e resistente, para impedir a perda de volume devido a vibração vinda do driver. Possui bocal redondo e estrutura curta, ideal para projetos de som mais perto e garantindo melhor direcionamento do áudio. • Monitores de palco, preenchimento lateral e P.A. formulários. • Tamanho compacto, frente plana • Buzina exponencial de alumínio • Garganta de 50 mm (2") • Cobertura nominal de 45° x 45° • Material da buzina: Alumínio • Acabamento de chifre: Epóxi branco Dimensões (aproximados): • Altura da boca: 176 mm (6,93 pol.) • Largura da boca: 165 mm (6,49 pol.) • Comprimento: 134 mm (5,27 pol.) Conteúdo da Embalagem: • 1 Corneta JBL HL 14-50 • Folheto Técnico • Folheto Garantia', 156.17, 125.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-820lk-mm1t7e60n8quaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F329035577%2F22997611224', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
