INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44759391194', 'Caixa Cooler Térmico 20 Litros Rosa Termolar com Tampa Removível Porta Copos e coisas Integrado', 'Caixa Térmica Termolar SUV 20 Litros – Rosa O que está adquirindo 1 Caixa Térmica Termolar SUV 20L – Cor Rosa Descrição do Produto Caixa térmica prática, moderna e resistente, ideal para manter bebidas e alimentos frescos por longos períodos. Conta com tampa reversível, alça reforçada, pegas laterais e ótimo isolamento térmico, sendo excelente para praia, piscina, viagens, camping e uso diário. Especificações Técnicas Capacidade: 20L Cor: Rosa Conservação térmica: até 12h sem gelo / 24h com gelo Isolamento: Poliestireno Expandido (EPS) Acabamento: liso Material externo: plástico Livre de BPA e material atóxico Tampa reversível com passatempos Abertura deslizante Pegas laterais salientes Alça reforçada (transporte individual ou em dupla) Capacidade interna: 26 latas 350 ml 20 latas 473 ml 4 garrafas PET 1,5 L 2 garrafas PET 2 L Porta-copos: Ø 74 mm Dimensões (A x L x C): 33 x 26 x 43 cm Aplicações Recomendadas Praia, piscina, camping, viagens, churrasco, lazer, uso doméstico e transporte de bebidas ou alimentos. Manuseio e Manutenção Utilize gelo para melhor desempenho Prefira usar sempre a capacidade total Evite abrir a tampa repetidamente Não exponha ao sol por longos períodos Não usar com bebidas gaseificadas Não usar em micro-ondas, lava-louças ou com aquecedores Limpeza com pano úmido e sabão neutro Evite abrasivos ou produtos com cloro SKU: 10924 Garantia 90 dias contra defeitos de fabricação (componentes plásticos).', 199.99, 101.04, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-820mk-mne9jf2mmsjnd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F334741920%2F44759391194', NULL,