INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197452477', 'Magic Beauty Hydra Hero Máscara de Hidratação 200g', 'A Magic Beauty representa uma nova geração de tratamento capilar de alta performance que une inovação e responsabilidade em uma nova visão sobre beleza. Acreditamos no poder transformador da beleza livre e responsável e desejamos inspirar a nossa comunidade a celebrar a sua própria magia - assim como a das pessoas ao seu redor - ao ajudar a construir uma nova visão sobre a beleza pautada em empatia, amor-próprio e autenticidade. Somos todos feitos de magia. Isso é simplesmente extraordinário. * RESULTADO: Reequilibra; Hidratação; Maciez; Brilho * SUGESTÕES DE USO: 1. Aplique nos cabelos úmidos e lavados com shampoo, no comprimento e pontas; 2. Massageie delicadamente; 3. Deixe agir por 2 minutos e enxágue. * OBSERVAÇÕES: Imagem Meramente Ilustrativa * ITENS INCLUSOS: 1 Magic Beauty Hydra Hero Máscara de Hidratação 200g', 79.9, 79.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rbkv-llkr2gegbwdrd5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F22197452477', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45359746038', 'Phebo Perfumaria Flor De Maio Edp Perfume Unissex 100ml', 'Floral delicado inspirado nas flores de maio, mesclando frescor leve e bouquet romântico de pétalas.', 290.0, 290.0, NULL, 'Beauty > Beauty Sets & Packages', 'https://cf.shopee.com.br/file/sg-11134201-820mi-mnng00tw0glefb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F45359746038', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258027337', 'Colorindo a copa do mundo - Grandes jogadas e emoções do futebol', 'Uma leitura cheia de diversão! A Copa do Mundo é um dos momentos mais empolgantes do planeta — e agora as crianças podem entrar nessa torcida com muita diversão! A coleção Colorindo a Copa do Mundo apresenta quatro livros de colorir com atividades simples, pensados para envolver os pequenos no clima do futebol de forma lúdica, educativa e cheia de imaginação. Cada volume traz cenários e elementos típicos do universo da Copa, sempre em ilustrações em preto e branco para colorir, além de propostas de atividades que estimulam criatividade, coordenação motora e curiosidade. Nos livros, as crianças vão conhecer seleções, estádios, torcidas e jogadas marcantes, explorando o esporte mais amado do mundo enquanto pintam, decifram desafios e criam suas próprias cenas. Destaques do Produto: Ilustrações das seleções para colorir; Uniformes e símbolos inspirados em diferentes países; Atividades simples e educativas; Estimula o interesse por culturas do mundo; Acompanha cartela de cards com craques da Copa; Benefícios para os pequenos: Desenvolve coordenação motora fina; Estimula criatividade e percepção visual; Amplia o conhecimento sobre diferentes países; Incentiva o interesse pelo esporte; Promove momentos de diversão em família O que vem no livro? ✔️ 1 livro de colorir (formato padrão da coleção); ✔️ Ilustrações em preto e branco das seleções; ✔️ Atividades simples e divertidas; ✔️ 1 cartela exclusiva de cards com craques da Copa; Para quem é? Crianças a partir de 4 anos; Pequenos fãs de futebol; Famílias que gostam de acompanhar os jogos juntas; Educadores que desejam trabalhar diversidade cultural e esporte; Sobre a Coleção: A coleção Colorindo a Copa do Mundo foi criada para envolver as crianças no clima da maior competição de futebol do planeta. Cada volume explora um aspecto diferente da Copa, com ilustrações para colorir e atividades que unem aprendizado e diversão. Por que escolher a Editora Bicho Esperto? Conteúdo pensado especialmente para o público infantil; Projetos que unem diversão e aprendizado; Ilustrações atrativas e adequadas à faixa etária; Compromisso com qualidade editorial e educativa; Leve para casa essa diversão da copa do mundo! Uma coleção vibrante, acessível e divertida — perfeita para acompanhar grandes jogos, aprender sobre diferentes culturas e torcer com alegria! Acompanha uma incrível cartela de cards com grandes craques da copa.', 13.9, 13.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-82586-mqrz4zaqcrgj8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F626529639%2F58258027337', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498831711', 'Kit 02 Unidades Vinho Rose Seco Fino Panizzon Rosé 750ml', 'Experimente o Vinho Fino Rosé Seco Panizzon, um exemplar requintado de 750 ml que combina a suavidade do Pinot e a frescura do Merlot. Com uma graduação alcoólica de 14%, este vinho proporciona uma experiência intensa e vibrante, ideal para diversas ocasiões. Seus aromas cítricos se destacam, fazendo dele a escolha perfeita para um brinde especial ou um encontro casual. Produzido na charmosa região da Serra, este rosé seco não passa por envelhecimento em barrica, o que preserva suas características frescas e frutadas. A temperatura ideal de consumo é de 10 °C, garantindo que cada gole revele o frescor e a leveza que caracterizam este vinho. É uma opção versátil que pode ser apreciada sozinha ou acompanhada de pratos leves e saladas. A embalagem em garrafa combina com a elegância do produto, tornando-o uma excelente escolha para presentes ou para complementar sua adega. Com o Vinho Fino Rosé Seco Panizzon, descubra a harmonia de sabores que transforma cada momento em uma celebração. Se procure uma bebida que una qualidade e prazer, este vinho certamente atenderá suas expectativas.', 89.0, 69.9, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj7arqdvun7n29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1306254852%2F22498831711', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21099565964', 'Sensor Nível Combustível Bóia T010008 TSA Escort e Escort Sw', 'Este anúncio contém: 1 (um) Sensor bóia nível de combustível original da marca TSA. Código do fabricante: T010008; Código universal: 7898911773082; Conversão: BF7A9275AA/XS419275BA/XS419275BB. Dados técnicos: Cheio: 20 a 24; Meio: 82 a 92; Vazio: 140 a 150. Observações do produto: Bomba Marwal. Atenção: Fotos reais do produto. Compre apenas tendo certeza de que serve para o seu veículo. Aplicável nos seguintes veículos: Montadora: Ford; Veículo: Escort (Gasolina/Álcool); Ano de fabricação: 02-09-1996, 1997, 1998, 1999, 2000, 2001 a 01-11-2002. Montadora: Ford; Veículo: Escort SW (Gasolina/Álcool); Ano de fabricação: 1995, 1996, 1997, 1998, 1999, 2000, 2001, 2002 e 2003. Dúvidas frequentes: Trabalhamos apenas com produtos novos e com garantia; Produto à pronta entrega; Seus produtos serão enviados em até 24 horas úteis após a confirmação do pagamento. Sobre a empresa: Somos uma autopeças fundada em 1980. Atuamos no mercado varejista de peças e acessórios, tendo como principais clientes oficinas mecânicas e consumidores finais. Não encontrou o que procura? Ficou com alguma dúvida sobre o produto? Fale conosco através do campo de perguntas.', 127.3, 119.67, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m44lw8uziog16e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F519603839%2F21099565964', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20498293320', 'Livro As coisas que a gente fala', '&ldquo As coisas que a gente fala saem da boca da gente e v&atilde o voando, voando correndo sempre pra frente. Entrando pelos ouvidos de quem estiver presente.&Rdquo Assim come&ccedil a esse livro delicioso, todo escrito em versos rimados, sobre a mentira e suas consequ&ecirc ncias. Nele, a Ruth Rocha narra um acontecimento na vida da Gabriela, uma menina muito simp&aacute tica e levada, mas talvez levada demais. Um dia ela acabou quebrando o vaso de ouro e laqu&ecirc da m&atilde e e, com medo de tomar uma bronca, acusou o vizinho, Filisteu. O pai do Filisteu ficou danado da vida com o filho. O filho sabia que n&atilde o tinha feito nada e foi conversar com a Gabriela. Olha, foi uma baita confus&atilde o... &Nbsp', 87.05, 78.35, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-824hm-mej0rfbs2dc743', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1624754721%2F20498293320', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093502959', 'Massa de Modelar Play-Doh Liquidificador Smoothies Coloridos', 'Descubra a mágica da culinária imaginária com o incrível conjunto Massa de Modelar Play-Doh Liquidificador Smoothies Coloridos! Projetado para crianças a partir de 3 anos, este conjunto permite que os pequenos chefs criem uma variedade de frutas e vegetais em miniatura e depois os misturem em deliciosos smoothies coloridos usando o liquidificador de brinquedo.Com esta massa de modelar, as crianças podem soltar sua imaginação e criar smoothies divertidos e coloridos. Elas podem moldar frutas e vegetais, como morangos, bananas, maçãs e cenouras, usando os meios-moldes e ferramentas incluídas. Depois, basta colocar os ingredientes no liquidificador de brinquedo, girar a manivela e assistir enquanto a mágica acontece e os smoothies são criados!Uma vez que os smoothies estão prontos, a diversão continua! As crianças podem usar sua criatividade para decorar seus smoothies com chantilly colorido ou criar mais frutas e vegetais para enfeitar. Com dois copos incluídos, elas podem até servir seus smoothies de mentirinha para amigos e familiares. Este kit de cozinha criativa é o presente ideal para meninas e meninos que adoram brincar com objetos de cozinha e explorar sua imaginação. Além disso, as atividades com Play-Doh são uma excelente maneira de desenvolver habilidades motoras finas, criatividade e imaginação em crianças pequenas.O Massa de Modelar Play-Doh Liquidificador Smoothies Coloridos vem com 198g de Play-Doh em uma variedade de cores, incluindo verde claro, amarelo, rosa, azul claro e vermelho. Cada pote de Play-Doh é não tóxico e contém trigo, garantindo a segurança das crianças durante a brincadeira.', 59.99, 59.99, NULL, 'Mom & Baby > Toys > Slime & Squishy Toys', 'https://cf.shopee.com.br/file/sg-11134201-825au-mqlz68dik7b693', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F23093502959', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893391590', 'Taça para Sobremesas Baixa em Vidro Le Brulee 190ml 1 Peça', 'Ter utensílios que vão te ajudar a servir sua sobremesa com elegância, sofisticação e conforto aos seus convidados é ideal no dia a dia e em datas especiais. A Taça para Sobremesas Le Brulee é uma peça toda produzida em vidro incolor para levar charme e glamour à sua mesa. Com capacidade para 190ml é possível colocar o tipo de sobremesa que quiser. Seu design lembra o estilo clássico texturizado. Dicas de PreservaçãoPara lavar, utilize o lado macio da esponja e escolha detergentes neutros, evitando abrasivos, como palha de aço e saponáceos, ou produtos de limpeza com alto teor de soda. Isso evita pequenos arranhões que, com o tempo, deixam o vidro fosco e frágil. Evite riscos com o uso de materiais pontiagudos. Evite o choque térmico, nunca colocando as peças quentes em lugares frios ou em contato diretamente com a água. Pode ir lava-louças. Aumente o tempo de uso dos seus utensílios.', 24.99, 24.99, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-825a3-mqyswvb0tkb0a7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F23893391590', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21299199169', 'Short Academia Feminino Empina Bumbum Poliamida Fitness Elástico Verão 3RD SD998', 'Uma peça Linda e Estilosa, confortável e ideal para todas as ocasiões! Nada melhor que investir em looks casuais que vai bem para o dia a dia, ou até mesmo para aquele momento especial!! “Queremos que você seja a garota mais bonita e estilosa dessa estação” Garanta já o seu! ( Possui empina bumbum) Medidas P/M(36-38) Cinturar:62cm Comprimento:36cm G/GG(40-42) Cinturar:66cm Comprimento:38cm OBSERVAÇÕES 1) Não abre reclamações, contate-nos para que possamos resolver o seu problema o mais rápido e da melhor forma possível! 2) Consulte-nos no campo de perguntas caso tenha alguma dúvida! Muito obrigado pela sua visita! Espero que tenha gostado deste anuncio! Clique em ver todos anúncios e ver todos os nossos produtos. Prazo máximo para postagem, após de pagamento confirmado em 3 dias úteis.', 19.99, 19.99, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Bottoms', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m51evyw8rjphf5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F393568956%2F21299199169', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20299229437', 'Scanner de Mesa Canon Lide 300 A4 Colorido USB Bivolt', 'Scanner de Mesa Canon Lide 300 A4 Colorido USB Bivolt Digitalize documentos de forma rápida e eficiente com o Scanner de Mesa Canon Lide 300 A4 Colorido USB! Perfeito para casa ou escritório, o Scanner Canon Lide 300 é compacto, prático e com design elegante e sofisticado. Além disso, é um scanner de mesa A4 leve, que conta com 4 botões EZ de funcionamento que garantem uma simples utilização, e uma fácil digitalização de alta resolução. O CanoScan Lide 300 não necessita de tomada elétrica, pois pode utilizar a ligação USB do seu computador portátil ou PC. Realiza digitalização de documentos de forma rápida, um documento A4 de 300dpi leva aproximadamente 10 segundos para ser digitalizado. Oferece qualidade impressionante, e definições de digitalização corretas para documentos e fotografias com o toque de um botão graças à função de digitalização automática. Vantagens do Scanner de Mesa Canon Lide 300 A4 Colorido USB Bivolt - Scanner de mesa; - Alimentado por cabo USB; - Possui 4 botões (EZ): PDF, Copiar, Enviar e Digitalização automática; - Resolução ótica máx. de 2400 x 2400 dpi; - Profundidade de cores de 48 bits; - Tampa articulável Z-LID. Especificações Técnicas Tipo: Scanner plano (de mesa) Elemento de digitalização: CIS Fonte de luz: LED tricolor (RGB) Resolução óptica: 2400 x 2400dpi Resolução selecionável: 25 - 19 200dpi Interface: USB 2.0 de alta velocidade Mini-B Gradação de digitalização (a cores): Entrada de 48 bits - saída de 48/24 bits Gradação de digitalização (tons de cinzento): Entrada de 16 bits - saída de 8 bits Formato máximo de documento: A4/Carta (216 x 297 mm) Botões de digitalização EZ: 4 botões (PDF, AUTOSCAN (Digitalização automática), COPY (Copiar), SEND (Enviar)) Velocidade de digitalização (A4, 300dpi, a cores): Aproximadamente 10 segundos. Velocidade de digitalização (10 x 15 cm, 300dpi, a cores): Aproximadamente 5 segundos. Velocidade de pré-visualização: Aproximadamente 9 segundos Dimensões: 250 × 367 × 42 mm Peso: 1,7Kg Garantia: 12 meses.', 699.0, 619.46, NULL, 'Computers & Accessories > Printers & Scanners > Printers, Scanners & Photocopy Machines', 'https://cf.shopee.com.br/file/sg-11134201-7rcfc-lteao08rkxwyf5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318415041%2F20299229437', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201007150', 'Antena Externa Aquario Log 30 Elementos Digital Uhf', 'A Antena Externa Aquário Log 30 Elementos foi projetada para oferecer recepção superior de sinal digital, garantindo imagem limpa, nítida e estável mesmo em regiões de sinal fraco. Com ganho de 14 dBi, ela proporciona excelente desempenho na captação dos sinais UHF, HDTV e tecnologia 4K, entregando qualidade profissional para uso doméstico ou coletivo. Seu design com 30 elementos aumenta a sensibilidade e reduz perdas, tornando-a ideal para instalações externas em casas, edifícios, condomínios, comércios e sistemas coletivos de TV. A antena também conta com tecnologia que elimina interferências da banda 4G, evitando ruídos e garantindo uma recepção mais estável. Feita com materiais de alta durabilidade, suporta chuva, sol e ventos fortes, oferecendo longa vida útil mesmo em ambientes externos. É compatível com todas as televisões e conversores digitais existentes no mercado, sendo uma solução completa para quem busca o melhor desempenho. Principais Características:Compatível com todas as TVs e conversores digitais Redução de interferências provenientes da banda 4G Ideal para instalações coletivas e residenciais Estrutura reforçada para uso externo', 85.31, 66.9, NULL, 'Computers & Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-82274-mhhqhuvr2wht24', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965617276%2F58201007150', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
