INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998638828', 'Brinco Vazado com Fecho Tarraxa em Prata 925 Legítima Feminino Moderno', 'Leve e sofisticado, este brinco vazado traz um design moderno que destaca a elegância na simplicidade. Seu acabamento delicado e fecho tarraxa garantem conforto e segurança para o uso diário. - Material: Prata 925 - Estilo: Vazado - Fecho: Tarraxa tradicional - Acompanha: Certificado de garantia de autenticidade - Observação: Não acompanha caixinha Uma peça versátil que combina com diversos estilos e ocasiões.', 40.0, 40.0, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/br-11134207-81ztl-mktiupc0imtcaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340468765%2F22998638828', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
