INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42111215523', 'Mix P&P ROCK Nuts Coco Castanha 250g Castanha de Caju do Pará Amêndoa Nozes e Crispy de Coco', 'O Mix P&P ROCK é uma combinação equilibrada de castanhas, com crispy de coco crocante, uma explosão de sabor sem igual. Você irá adorar!! Umaopção nutritiva, prática e deliciosa para lanches rápidos ou para complementar refeições saudáveis. ℹ️ Benefícios: ✅ Com MUIIIIITA castanha ✅ Fonte natural de fibras, vitaminas e minerais ✅ Snack prático e saudável ✅ Ideal para consumo direto ou em receitas ✅ Com Crispy de Coco Crocante ℹ️ Ficha Técnica: ✅ Produto: Mix P&P ROCK ✅ Ingredientes: Castanha de Caju, Amêndoa, Nozes, Castanha do pará , Amendoim e Crispy de Coco Crocante ✅ Sem Açúcar ✅ Sem Lactose ✅ Sem Glúten *Imagem ilustrativa. O produto pode apresentar variações de cor, sabor e aparência, conforme as características naturais das matérias-primas e diferenças entre as safras do ano.', 48.77, 34.97, NULL, 'Food & Beverages > Snacks > Nuts', 'https://cf.shopee.com.br/file/sg-11134201-7rdxk-mcwjqsrqfltsec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F394192376%2F42111215523', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9260469275', 'Bico Leque 15a20cm 1,1mm Mpa120 311 Vonder', 'O Bico Leque 15a20cm 1,1mm Mpa120 311 da Vonder é a escolha ideal para quem busca eficiência e qualidade em suas pinturas. Fabricado em aço inox, este bico oferece resistência superior à oxidação e corrosão, garantindo durabilidade e um desempenho excepcional. Com uma abertura de leque de 15 cm a 20 cm e espessura de 1,1 mm, ele proporciona uma cobertura uniforme e precisa, ideal para aplicações profissionais e amadoras. Este bico é especialmente indicado para uso com Máquinas de Pintura Airless da Vonder, mas pode ser compatível com outros modelos e marcas. Verifique a compatibilidade com seu equipamento para garantir o melhor desempenho. A pressão máxima indicada é de 3.300 psi, assegurando uma aplicação eficiente e rápida. **ESPECIFICAÇÕES TÉCNICAS** - Material: Aço inox - Abertura do leque: 15 cm a 20 cm - Espessura do leque: 1,1 mm - Pressão máxima indicada: 3.300 psi (lbf/pol²) - Tipo de pistola: Airless - Código universal de produto: 7893946506643 **FUNÇÕES E CARACTERÍSTICAS** - Resistente à oxidação e corrosão - Cobertura uniforme e precisa - Ideal para aplicações profissionais **INSTRUÇÕES DE USO** 1. Utilize a uma distância de 350 mm a 400 mm da superfície a ser pintada para obter o melhor resultado. 2. Após o uso, limpe o bico com cuidado para prolongar sua vida útil. 3. Armazene em local seco e seguro. **ITENS INCLUSOS** - 1 Bico leque', 125.9, 125.9, NULL, 'Home Appliances > Kitchen Appliances > Rice Cookers', 'https://cf.shopee.com.br/file/sg-11134201-825zr-ml5hxob7umfc4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442555366%2F9260469275', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
