INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993810738', 'Capa de Chuva ABC Design Multi', 'A Capa de Chuva Multi da ABC Design é um produto versátil e útil, perfeito para proteger o seu bebê e o carrinho de passeio contra o vento e a chuva. Com ela, o seu bebê volta do passeio sempre sequinho. A instalação é simples e fácil, com velcros nas laterais para reforçar o fechamento. A capa protege a estrutura do carrinho e o assento, mesmo quando a capota do carrinho estiver estendida. A Capa de Chuva Multi possui entrada de ar (pequenos furos), para evitar o acúmulo de calor, proporcionando melhor ventilação para o bebê. Pode ser utilizada quando o bebê conforto e o moisés estiverem instalados na estrutura do carrinho. Produzida com plástico reforçado, a capa é resistente a impactos e rasgos. Não contém plastificantes químicos. É compatível com os modelos de carrinhos: 3Tec, Salsa 3, Salsa 4, Condor 4, Como 4 e Merano 4. Características: Produto Alemão Sem plastificantes químicos Plástico reforçado resistente a impactos e rasgos Fácil instalação, com fechamento em velcro nas laterais Protege de vento e chuva Com entrada de ar que evita o acúmulo de calor e trazem melhor ventilação para o bebê Compatível com os carrinhos: 3Tec, Salsa 3, Salsa 4, Condor 4, Como 4 e Merano 4 Especificações: Conteúdo: 1 Capa de Chuva Multi As cores podem variar entre as imagens e o produto Os carrinhos das imagens não acompanham o produto e devem ser adquiridos separadamente Imagens meramente ilustrativas.', 159.9, 99.0, NULL, 'Mom & Baby > Baby Travel Essentials > Stroller Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rd64-m7ayccy15exv6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1419417476%2F23993810738', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
