INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19297421798', 'luminária abajur de Mesa Bojudo Escovado alumínio bivolt Com Cúpula algodão canto de sala quarto cabeceira cama', 'Sinta a textura delicada do algodão da cúpula, um convite ao aconchego e ao relaxamento. Escolha a tonalidade que mais ressoa com a sua alma: o bege que acalma, o preto que emana poder ou o branco que irradia pureza e amplitude. A base Escovado, com seu brilho sutil e acabamento impecável, não é apenas elegante – é a promessa de durabilidade e beleza que perduram. Posicione-o ao lado do seu sofá predileto, na sua mesa de cabeceira como um sussurro de luz antes do sono, ou no seu escritório, adicionando um toque de sofisticação ao seu dia a dia. Este abajur é mais do que um objeto: é a pincelada final que faltava para completar a sua obra de arte pessoal, o seu lar. Deixe que a sua luz envolva seus momentos, criando memórias preciosas em um ambiente que reflete a sua essência clássica e atemporal. Sinta o desejo de possuir esta joia luminosa que transformará seus espaços com elegância e charme incomparáveis. Especificações Técnicas: Altura Total com Cúpula: 35 cm. Cor da Base: Escovado. Lâmpada: 1 lâmpada E-27 incandescente (até 40W) ou LED (qualquer potência). Material do abajur: Alumínio. Material da cúpula: Tecido algodão revestido com acetato. Soquete: E-27. Tensão: Bivolt. Tipo de Acionamento: Rabicho na tomada com click liga/desliga. Quantidade de Lâmpadas Utilizadas: 1 (não acompanha o produto). Independentemente da cor da cúpula que você escolher, o Abajur Clássico Escovado certamente se destacará como uma peça de destaque em sua decoração, trazendo um charme clássico e atemporal ao ambiente.', 161.0, 112.7, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mibl29gcfo5e26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F718558431%2F19297421798', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
