INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698237664', 'Conjunto Infantil Menina Detalhe em Nó Elian Azul', 'O Conjunto Infantil Menina Detalhe em Nó Elian combina delicadeza e conforto em um único look. Composto por blusa em meia malha e short em malha texturizada, as peças oferecem um visual único e com toque macio. A blusa com mangas curtas possui estampa frontal com corações e a frase "Doing My Best", que tem sua tradução como "Fazendo o meu melhor". Já o shorts conta com elástico no cós e detalhe em amarração, além de estampa em toda a peça com palmeiras, garantindo um visual perfeito para os dias de sol. Aproveite e renove o guarda-roupa da sua pequena com esse look estiloso!', 99.9, 99.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-825bb-mr1t387d75dxe0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F23698237664', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
