INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799599966', 'Cueiro Papi Flanelado Estampa Cogumelo - 3 Peças', 'Cueiro Papi Flanelado Estampa Cogumelo - 3 Peças O Cueiro Papi Baby estampado é feito em tecido flanelado 100% Algodão e possui estampas fofas e divertidas. Você pode escolher entre 3 combinações e vem com 3 unidades na embalagem. O cueiro é um item extremamente versátil, usado para enrolar o bebê como charutinho e acalmá-lo, ideal para o 1º mês de vida, além disso pode ser usado como pano para forrar qualquer superfície em passeios, como paninho para cobrir o bebê conforto ou carrinho na hora da soneca, entre outros. Informações Adicionais: Tamanho: Único Cores: Colorido Referência: 4106-1859 Dimensão: 80cmX80cm Composição: Algodão Marca: Papi Dica: Essencial no enxoval do bebê', 55.8, 55.8, NULL, 'Mom & Baby > Nursery > Mattresses & Bedding', 'https://cf.shopee.com.br/file/sg-11134201-7rbml-m5yeqof324izfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F21799599966', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
