INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10548346566', 'Aparelho de Barbear Gillette Prestobarba3 Sensitive c/2 Unidades', 'A Gillette Prestobarba3 Lâmina descartável sensível para pele sensível, agora oferece mais 10 barbeamentos com sua nova tecnologia comfortgel. Durante o barbear a água ativa o lubrificante, é esticada transformando-se em uma camada protetora entre a pele e as lâminas para um barbear liso e flush. Para um melhor barbear, experimente a Espuma de Barbear Sensível Prestobarba. Até 10 barbas mais suaves; Tecnologia Comfortgel para um barbear suave e flush; Com mais lubrificação, ideal para peles sensíveis; Três lâminas (3) montadas em molas independentes e uma cabeça móvel que se ajusta ao contorno do seu rosto para obter um barbear suave; Cabo antiderrapante para um ótimo controle; Fácil de enxaguar.', 27.09, 27.09, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/sg-11134201-7rbmw-lp0tahae4jve74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F10548346566', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
