INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52162503564', 'Cadeira Presidente Executiva Giratória De Escritório Estofado Couro Mesh Ergonômica', 'Esta cadeira de escritório é ideal para ser colocada em qualquer lugar em sua casa ou escritório. O seu design permite adaptá-lo no ambiente que você deseja, dando um toque mais moderno aos seus espaços. Ajuste-a a sua medida Com seu ajuste de altura, poderás fixar a posição de seu torso em relação à mesa de trabalho e assim obterá uma cadeira mais confortável ao nível de suas necessidades. Cuide do seu corpo Os apoios de braços melhorarão a sua postura ao escrever e o ajudarão a se sentar com mais facilidade quando quiser.', 223.99, 134.9, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134207-820lw-mqosul1m58g24d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F374148566%2F52162503564', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
