INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198984908', 'Regata de Tela Grafite Com Fita Emborrachada', 'Regata de Tela Cinza Grafite com Fita Emborrachada | O Básico que Funciona Função Despojada que Abraça o Estilo do Dia a Dia A Regata de Tela com Fita Emborrachada Cinza Grafite traz a combinação perfeita de respirabilidade e versatilidade para sua rotina diária. Confeccionada inteiramente em tecido de tela para maximizar o fluxo de ar, com gola redonda clássica e design de costas nadador, esta peça prova que básico não significa sem graça. O moderno tom Cinza Grafite oferece uma cor contemporânea e neutra que complementa sem esforço qualquer estilo. Tecnologia Premium • Construção em Tela Completa: Design completo em tecido de tela garante máxima respirabilidade e ventilação durante qualquer atividade • Performance Leve: Material ultra leve proporciona conforto sem comprometer a durabilidade • Propriedades de Secagem Rápida: Tecnologia avançada de tecido mantém você seca e confortável durante todo o dia • Gola Redonda Clássica: Design atemporal que favorece todos os tipos de corpo Design Funcional • Corte Costas Nadador: Design de costas inspirado no atletismo oferece completa liberdade de movimento e ventilação aprimorada • Fita Emborrachada da Marca: Detalhe premium que adiciona autenticidade e apelo moderno • Estética Minimalista: Linhas limpas e silhueta simples para styling despojado • Versatilidade Cinza Grafite: Cor moderna e neutra que combina perfeitamente com qualquer peça para opções infinitas de styling Essencial do Cotidiano Perfeita para sessões de academia, saídas casuais ou para usar como camada sob suas peças favoritas. A combinação de respirabilidade completa em tela e design clássico torna esta regata uma parte indispensável do seu guarda-roupa ativo e casual. Simples, funcional e inegavelmente estilosa neste contemporâneo tom Cinza Grafite. COMPRE AGORA - O básico que funciona perfeitamente para seu estilo de vida ativo cotidiano.', 79.89, 79.89, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/sg-11134201-824in-mfio1sbr5mh976', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1576910750%2F23198984908', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
