INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211389711', 'Jibbitz™ Casquinha De Sorvete Marmorizada Único', 'Os maravilhosos Jibbitz™ Charms são acessórios que você coloca nos seus Crocs. Eles são fáceis de colocar e retirar, para que você possa mudar seus estilo a qualquer momento. Adicione os encantos dos Jibbitz™ Charms aos seus Crocs para mostrar que seu estilo e criatividade são únicos! De personagens conhecidos a emojis populares. Tem algo a dizer? Diga! Se ama alienígenas e unicórnios? Mostre! Fácil de colocar e ser removido, combina com qualquer look, companhia perfeita com detalhes bem visíveis. Não é um brinquedo. Não se destina a crianças menores de 3 anos de idade As imagens do produto podem sofrer pequena alteração de cor dependendo do monitor e da resolução em que elas sejam visualizadas.', 34.99, 34.99, NULL, 'Fashion Accessories > Additional Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-823ok-mopf5bk740021c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757311881%2F58211389711', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797166532', 'Tintura Schwarzkopf Igora Royal 6.88 Vermelho Rubi', 'A Coloração Igora Royal da Schwarzkopf trouxe para o mercado cores vibrantes e intensas nunca vistas antes. Com a tecnologia HD a Igora conta com uma matriz de pigmentos de alta definição o que dá a ela o título de uma das melhores do mercado. Performarce de Alta Definição • Cobertura de até 100% dos fios brancos • Resultados fiéis a cartela de cor • Selagem dos fios que proporciona uma cor duradoura. ​• Mude a cor dos seus cabelos com a coloração Schwarzkopf Igora Royal HD e obtenha resultados incríveis, cabelos brilhantes e cores vibrantes. Modo de uso: • Antes de aplicar Faça a prova de toque e teste de mecha. • Prova de Toque Prepare um pouco do produto • Aplique no antebraço ou atrás da orelha • Deixe agir por 30 minutos • Lave o local • Após 24 horas: Se neste período surgirem sintomas de • enjoo ou irritação, ardência ou vermelhidão no local (ou em sua proximidade), fica provada a hipersensibilidade ao produto e, portanto, o mesmo não deverá ser utilizado. • Sugestão de Uso Para as instruções leia atentamente a parte interna no cartucho. Uso Profissional. Utilizar emulsão de volume a sua escolha de acordo com as instruções contidas na parte interna do cartucho. (Oxigenada/Emulsão vendida separadamente) • Cuidados: Não ingerir. Em caso de contato com os olhos, enxaguar imediatamente com água abundante. #html-body [data-pb-style="646BA646709E0"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA646709F4"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 59.79, 59.79, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-7rbn9-lozd4z1i9mjb81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22797166532', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
