INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20998994074', 'Máscara Capilar Jacques Janine Professionnel Mega Volume 240g', '#html-body [data-pb-style=EFS60SE]{justify-content:Flex-start;display:Flex;flex-direction:Column;background-position:Left top;background-size:Cover;background-repeat:No-repeat;background-attachment:Scroll}Máscara de tratamento para cabelos finos e sem volume. Jacques Janine Professionnel Volume Máscara encorpa os fios e confere movimento para que não fiquem com aspecto pesado. Jacques Janine Professionnel Volume Máscara possui fórmula hidratante e nutritiva que possui um efeito anti-gravidade. Isso permite com que o cabelo ganhe mais volume e densidade de forma com o que o resultado fique leve e natural. Também traz vitalidade para fios macios e brilhantes. Modo de uso: Aplique a máscara sobre o cabelo úmido e lavado com shampoo, no comprimento e pontas. Aguarde de 5 a 10 minutos e enxague.', 117.56, 117.56, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rbm1-lmghat8ghkrd19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F20998994074', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
